package com.petfollower;

/**
 * What a single overhead bar shows. OFF hides that bar entirely, so the stack
 * can be one, two, or three bars tall.
 */
public enum BarStat
{
	OFF("Off"),
	HITPOINTS("Hitpoints"),
	PRAYER("Prayer"),
	SPEC("Spec energy"),
	DPS("DPS");

	private final String displayName;

	BarStat(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.petfollower;

/**
 * How the DPS meter decides when one fight ends and the next begins.
 */
public enum DpsSessionMode
{
	PER_TARGET("Per target"),
	CONTINUOUS("Continuous"),
	WHOLE_SESSION("Whole login session");

	private final String displayName;

	DpsSessionMode(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.petfollower;

/**
 * How eagerly the pet follows. Only the personality changes — every style
 * uses the same pathing, wall handling, and long-range catch-up, so the pet
 * can never get stuck or left behind.
 *
 * Display names stay one word: the config panel sizes the dropdown to its
 * widest entry and steals that width from the setting's own label, so
 * anything longer pushes "Following style" out of view. The temperament of
 * each style is spelled out in the config description instead.
 */
public enum FollowStyle
{
	STRONG("Strong"),
	MEDIUM("Medium"),
	LOOSE("Loose");

	private final String displayName;

	FollowStyle(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.petfollower;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("petfollower")
public interface PetFollowerConfig extends Config
{
	// ------------------------------------------------------------------
	// Sections
	// ------------------------------------------------------------------

	@ConfigSection(
		name = "Following",
		description = "How the pet moves and turns while following you.",
		position = 0
	)
	String followingSection = "following";

	@ConfigSection(
		name = "Appearance",
		description = "Transmog and per-pet visual tuning.",
		position = 1
	)
	String appearanceSection = "appearance";

	@ConfigSection(
		name = "Overhead display (experimental)",
		description = "EXPERIMENTAL and off by default - the combat HUD that floats above the pet. Turn on the first option to enable all of it.",
		position = 2
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Damage & XP trackers (experimental)",
		description = "Live DPS and XP/hr readouts. These only appear when the overhead display above is switched on.",
		position = 3
	)
	String trackerSection = "trackers";

	@ConfigSection(
		name = "Combat",
		description = "How the pet behaves while you fight (when it is not your thrall).",
		position = 4
	)
	String combatSection = "combat";

	@ConfigSection(
		name = "Thrall combat",
		description = "Your pet standing in for Arceuus thralls.",
		position = 5
	)
	String thrallSection = "thrall";

	@ConfigSection(
		name = "Interaction",
		description = "Handing control back to the real pet so you can click it.",
		position = 6
	)
	String interactionSection = "interaction";

	// ------------------------------------------------------------------
	// Following
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "followStyle",
		name = "Following style",
		description = "The pet's personality when following.<br>"
			+ "Strong - right at your heel, instant reactions (the classic).<br>"
			+ "Medium - relaxed: lets you pull a tile ahead before reacting,<br>"
			+ "and its trailing distance drifts a little over time.<br>"
			+ "Loose - its own creature: reacts late, trails at a wandering<br>"
			+ "distance, takes its time settling when you stop.<br>"
			+ "Every style paths identically around walls and always catches<br>"
			+ "up at range - only the temperament changes.",
		position = 0,
		section = followingSection
	)
	default FollowStyle followStyle()
	{
		return FollowStyle.MEDIUM;
	}

	@Range(min = 60, max = 360)
	@ConfigItem(
		keyName = "turnSpeed",
		name = "Turn speed (deg/sec)",
		description = "How fast the pet rotates when changing direction. Lower = lazier, sweeping turns; higher = snappier.",
		position = 1,
		section = followingSection
	)
	default int turnSpeed()
	{
		return 180;
	}

	@ConfigItem(
		keyName = "idleWander",
		name = "Wander when bored",
		description = "After about three minutes of you standing still, the pet gets<br>"
			+ "bored and paces around near you on its own (same collision-checked<br>"
			+ "wandering as combat). It's back at your side the moment you move.",
		position = 0,
		section = combatSection
	)
	default boolean idleWander()
	{
		return true;
	}

	@ConfigItem(
		keyName = "alwaysFaceOwner",
		name = "Pet always faces you",
		description = "The pet's body points at you at ALL times, even while moving.<br>"
			+ "Hovering/floaty pets look great with this; four-legged pets will<br>"
			+ "visibly sidestep while walking (OSRS models have no strafe<br>"
			+ "animation), which is why it's off by default.",
		position = 2,
		section = followingSection
	)
	default boolean alwaysFaceOwner()
	{
		return false;
	}

	// ------------------------------------------------------------------
	// Appearance
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "transmogPet",
		name = "Transmog pet",
		description = "Render your follower as this pet, built from the game cache. Cosmetic and client-side only - only you see it.",
		position = 0,
		section = appearanceSection
	)
	default PetTransmog transmog()
	{
		return PetTransmog.OFF;
	}

	@ConfigItem(
		keyName = "petVitals",
		name = "Overhead display (experimental)",
		description = "EXPERIMENTAL - off by default. Master switch for everything the<br>"
			+ "pet floats over its head: the HP / Prayer / Spec / DPS bars and<br>"
			+ "every tracker readout below. Turn it on and the display fades in<br>"
			+ "during combat, then fades out shortly after.<br>"
			+ "<br>"
			+ "This combat HUD is still a work in progress and is not finished -<br>"
			+ "expect rough edges at some zoom levels. Everything else the plugin<br>"
			+ "does (the pet itself, following, wandering) is unaffected.",
		position = 0,
		section = displaySection
	)
	default boolean petVitals()
	{
		return false;
	}

	@Range(min = 1, max = 120)
	@ConfigItem(
		keyName = "vitalsPersistSecs",
		name = "Keep visible after combat (s)",
		description = "How long the HP/Prayer display lingers after your last hit<br>"
			+ "before fading. Longer keeps it steady through a fight of<br>"
			+ "move-hit-move and short pauses between kills.",
		position = 1,
		section = displaySection
	)
	default int vitalsPersistSecs()
	{
		return 20;
	}

	@ConfigItem(
		keyName = "vitalsOnDamage",
		name = "Show vitals when hit",
		description = "Also raise the display when something hits YOU, even if you<br>"
			+ "never fought back - so running past aggressive mobs brings it up.<br>"
			+ "Off by default: only engaging a target yourself shows it.",
		position = 2,
		section = displaySection
	)
	default boolean vitalsOnDamage()
	{
		return false;
	}

	@ConfigItem(
		keyName = "vitalsSize",
		name = "HP/Prayer display size",
		description = "Overall size of the HP &amp; Prayer display above the pet.",
		position = 3,
		section = displaySection
	)
	default VitalsSize vitalsSize()
	{
		return VitalsSize.LARGE;
	}

	@Range(min = -150, max = 300)
	@ConfigItem(
		keyName = "vitalsOffset",
		name = "Display vertical offset (%)",
		description = "How high above the pet the whole display floats, as a percent<br>"
			+ "of the pet's on-screen size (so it holds its place at every zoom).<br>"
			+ "Negative values push it down over or below the pet.<br>"
			+ "Remembered separately for each pet.",
		position = 4,
		section = displaySection
	)
	default int vitalsOffset()
	{
		return 22;
	}

	@ConfigItem(
		keyName = "avoidNpcs",
		name = "Step around NPCs",
		description = "Drift the pet clear of NPCs so their models don't intersect.<br>"
			+ "Eased smoothly, and only for NPCs - other players are ignored,<br>"
			+ "so the pet still passes straight through them.",
		position = 3,
		section = followingSection
	)
	default boolean avoidNpcs()
	{
		return true;
	}

	@Range(min = 10, max = 100)
	@ConfigItem(
		keyName = "vitalsOpacity",
		name = "HP/Prayer opacity (%)",
		description = "How opaque the HP &amp; Prayer display is. 100 = solid, lower = more see-through.",
		position = 5,
		section = displaySection
	)
	default int vitalsOpacity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "vitalsWarnings",
		name = "Low HP/Prayer alerts",
		description = "When your Hitpoints or Prayer drop to the thresholds below, the<br>"
			+ "display blinks and your pet calls out once in the chatbox so you<br>"
			+ "know to heal or drink a prayer potion.",
		position = 6,
		section = displaySection
	)
	default boolean vitalsWarnings()
	{
		return true;
	}

	@Range(min = 1, max = 990)
	@ConfigItem(
		keyName = "hpWarnLevel",
		name = "Low HP threshold",
		description = "Blink and warn when your current Hitpoints fall to this number<br>"
			+ "or below (absolute, not a percent).",
		position = 7,
		section = displaySection
	)
	default int hpWarnLevel()
	{
		return 20;
	}

	@Range(min = 1, max = 990)
	@ConfigItem(
		keyName = "prayWarnLevel",
		name = "Low Prayer threshold",
		description = "Blink and warn when your current Prayer points fall to this<br>"
			+ "number or below (absolute, not a percent).",
		position = 8,
		section = displaySection
	)
	default int prayWarnLevel()
	{
		return 15;
	}

	@Range(min = 1, max = 120)
	@ConfigItem(
		keyName = "alertSecs",
		name = "Low HP/Prayer alert time (s)",
		description = "How long the pet stays alerted after your Hitpoints or Prayer<br>"
			+ "cross their threshold: it breaks off whatever it was doing, comes<br>"
			+ "to you, and holds the display up for this long before going back<br>"
			+ "to wandering.",
		position = 13,
		section = displaySection
	)
	default int alertSecs()
	{
		return 30;
	}

	@Range(min = 1, max = 30)
	@ConfigItem(
		keyName = "warnFlashSecs",
		name = "Warning flash time (s)",
		description = "How long the display blinks after crossing a low-HP/Prayer<br>"
			+ "threshold before settling back to steady.",
		position = 9,
		section = displaySection
	)
	default int warnFlashSecs()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "topBarStat",
		name = "First bar shows",
		description = "What the first (top) bar displays. Hitpoints and Prayer get<br>"
			+ "their smooth fill and change effects; DPS becomes the trend bar;<br>"
			+ "Spec is the special-attack energy. Low-HP chat warnings always<br>"
			+ "watch your actual Hitpoints regardless.",
		position = 10,
		section = displaySection
	)
	default BarStat topBarStat()
	{
		return BarStat.HITPOINTS;
	}

	@ConfigItem(
		keyName = "secondBarStat",
		name = "Second bar shows",
		description = "What the second bar displays, or Off to show only one bar.",
		position = 11,
		section = displaySection
	)
	default BarStat secondBarStat()
	{
		return BarStat.PRAYER;
	}

	@ConfigItem(
		keyName = "thirdBarStat",
		name = "Third bar shows",
		description = "An optional third bar. Off by default.",
		position = 12,
		section = displaySection
	)
	default BarStat thirdBarStat()
	{
		return BarStat.OFF;
	}

	@ConfigItem(
		keyName = "petDps",
		name = "DPS readout",
		description = "Your damage-per-second against the current target, shown above<br>"
			+ "the HP/Prayer display. Computed from your XP drops (with per-NPC<br>"
			+ "XP-bonus correction), so thralls and other players never pollute<br>"
			+ "it. Raid bosses' party scaling is not modeled yet, so DPS reads<br>"
			+ "high inside CoX/ToB/ToA.",
		position = 0,
		section = trackerSection
	)
	default boolean petDps()
	{
		return true;
	}

	@ConfigItem(
		keyName = "dpsSession",
		name = "DPS session",
		description = "Per target: the meter resets on every new mob, so the number<br>"
			+ "is your DPS against the one you're fighting. Best for camping.<br>"
			+ "Continuous: kills chain into one running session until the<br>"
			+ "display fades out after the fight: sustained DPS including<br>"
			+ "switch-over downtime. Best for barraging and chinning.<br>"
			+ "Whole login session: a running average over your ENTIRE time<br>"
			+ "logged in, only reset by logging out or changing this setting.",
		position = 1,
		section = trackerSection
	)
	default DpsSessionMode dpsSession()
	{
		return DpsSessionMode.PER_TARGET;
	}

	@ConfigItem(
		keyName = "petXpHr",
		name = "XP/hr readout",
		description = "The skill you're currently training and your hourly rate, shown<br>"
			+ "with the vitals display (skill icon + rate). Appears whenever XP<br>"
			+ "is flowing - combat or skilling - and matches RuneLite's own math.",
		position = 2,
		section = trackerSection
	)
	default boolean petXpHr()
	{
		return true;
	}

	@ConfigItem(
		keyName = "petKillsHr",
		name = "Kills/hr readout",
		description = "Your kills per hour, counted from mobs you were fighting when<br>"
			+ "they died. Same idle-reset as the combat XP/hr session.",
		position = 20,
		section = trackerSection
	)
	default boolean petKillsHr()
	{
		return false;
	}

	@ConfigItem(
		keyName = "xpHrMode",
		name = "XP/hr tracks",
		description = "Current skill - automatically follows whatever you're training<br>"
			+ "right now, switching as you switch.<br>"
			+ "Locked skills - shows ONLY the skills you pick below (one line each),<br>"
			+ "ignoring everything else. Set one for a single skill, or several<br>"
			+ "for multiskilling.",
		position = 3,
		section = trackerSection
	)
	default XpHrMode xpHrMode()
	{
		return XpHrMode.CURRENT;
	}

	@ConfigItem(
		keyName = "xpHrSkill1",
		name = "Locked skill 1",
		description = "First skill shown when 'XP/hr tracks' is set to Locked skills.",
		position = 4,
		section = trackerSection
	)
	default TrackedSkill xpHrSkill1()
	{
		return TrackedSkill.NONE;
	}

	@ConfigItem(
		keyName = "xpHrSkill2",
		name = "Locked skill 2",
		description = "Second locked skill (for multiskilling). Leave as None to skip.",
		position = 5,
		section = trackerSection
	)
	default TrackedSkill xpHrSkill2()
	{
		return TrackedSkill.NONE;
	}

	@ConfigItem(
		keyName = "xpHrSkill3",
		name = "Locked skill 3",
		description = "Third locked skill (for multiskilling). Leave as None to skip.",
		position = 6,
		section = trackerSection
	)
	default TrackedSkill xpHrSkill3()
	{
		return TrackedSkill.NONE;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(
		keyName = "xpResetCombatMins",
		name = "XP/hr reset - combat (min)",
		description = "Stop gaining a combat skill's XP for this many minutes and its<br>"
			+ "XP/hr session resets, so a break doesn't drag the rate down.",
		position = 7,
		section = trackerSection
	)
	default int xpResetCombatMins()
	{
		return 5;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(
		keyName = "xpResetSkillingMins",
		name = "XP/hr reset - skilling (min)",
		description = "Same, for non-combat skills - banking, running to a new spot,<br>"
			+ "and other longer pauses shouldn't reset it, so this defaults higher.",
		position = 8,
		section = trackerSection
	)
	default int xpResetSkillingMins()
	{
		return 10;
	}

	@Range(min = 1, max = 240)
	@ConfigItem(
		keyName = "xpResetLockedMins",
		name = "XP/hr reset - locked (min)",
		description = "Reset time for skills you've LOCKED above - kept separate so a<br>"
			+ "pinned skill can hold its session far longer (or shorter) than the<br>"
			+ "auto combat/skilling timers.",
		position = 9,
		section = trackerSection
	)
	default int xpResetLockedMins()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "xpHrClear",
		name = "Clear XP/hr now",
		description = "Tick to wipe every skill's current XP/hr session and start<br>"
			+ "fresh. Un-ticks itself once done.",
		position = 10,
		section = trackerSection
	)
	default boolean xpHrClear()
	{
		return false;
	}

	@ConfigItem(
		keyName = "petName",
		name = "Pet name",
		description = "A custom name shown above the HP/Prayer display, in the game's<br>"
			+ "own font. Leave empty for no name. Remembered per pet.",
		position = 1,
		section = appearanceSection
	)
	default String petName()
	{
		return "";
	}

	@ConfigItem(
		keyName = "speedTweaksEnabled",
		name = "Adjust animation speed",
		description = "Speed up the walk cycle of pets that have no real run animation,<br>"
			+ "so their feet keep up with the ground.<br>"
			+ "Turn off to leave every animation exactly as the game plays it.",
		position = 4,
		section = followingSection
	)
	default boolean speedTweaksEnabled()
	{
		return true;
	}

	@Range(min = 100, max = 300)
	@ConfigItem(
		keyName = "petSpeed",
		name = "Pet animation speed (%)",
		description = "How fast this pet's run animation plays.<br>"
			+ "100% = vanilla: the animation is not touched at all.<br>"
			+ "Raise it to speed up the run cycle of pets that have no real<br>"
			+ "run animation, so their feet keep up with the ground.<br>"
			+ "The slider always shows and edits the pet currently on screen<br>"
			+ "(real or transmog), and each pet's value is saved and restored<br>"
			+ "whenever that pet is out.",
		position = 5,
		section = followingSection
	)
	default int petSpeed()
	{
		return 100;
	}

	@Range(min = 0, max = 32)
	@ConfigItem(
		keyName = "groundClearance",
		name = "Pet ground clearance",
		description = "Raises the displayed pet slightly off the terrain.<br>"
			+ "Some pets (Youngllef etc.) have a glow/aura at their base that<br>"
			+ "sits exactly at ground level and gets swallowed by the terrain<br>"
			+ "when rendered as the ghost. A few units of clearance keeps it<br>"
			+ "visible; a tile is 128 units, so values under ~10 are invisible<br>"
			+ "as \"floating\". 0 = off. Saved per pet.",
		position = 2,
		section = appearanceSection
	)
	default int groundClearance()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "cadenceMessages",
		name = "Pet speed chat messages",
		description = "Show a chat message with the loaded speed setting whenever your<br>"
			+ "displayed pet changes (pet swap or transmog), so you always know<br>"
			+ "what the current pet is set to.",
		position = 6,
		section = followingSection
	)
	default boolean cadenceMessages()
	{
		return true;
	}

	// ------------------------------------------------------------------
	// Thrall combat
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "thrallMode",
		name = "Pet impersonates thralls",
		description = "When you summon an Arceuus thrall, your pet takes its place: the thrall is hidden, the pet fights from its spot and plays its own attack animation, and returns to your side when it expires.",
		position = 0,
		section = thrallSection
	)
	default boolean thrallMode()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tintThrallBolt",
		name = "Tint thrall projectiles",
		description = "Recolor the thrall's projectile to the color below, so a red<br>"
			+ "pet isn't shooting blue bolts. The bolt keeps its exact shape,<br>"
			+ "animation, and shading - only the color changes. Client-side<br>"
			+ "and cosmetic, like everything else here.",
		position = 1,
		section = thrallSection
	)
	default boolean tintThrallBolt()
	{
		return false;
	}

	@ConfigItem(
		keyName = "thrallBoltColor",
		name = "Projectile color",
		description = "The color the thrall's projectile (and its impact splash on the<br>"
			+ "target) is tinted to. Saved per pet: the picker always shows and<br>"
			+ "edits the pet currently displayed, like the speed slider.",
		position = 2,
		section = thrallSection
	)
	default Color thrallBoltColor()
	{
		return new Color(228, 48, 24);
	}

	@ConfigItem(
		keyName = "maxHitCelebrate",
		name = "Celebrate max hits",
		description = "When you land a hit at your session best (a max roll), the pet<br>"
			+ "plays its attack animation. That animation also cues the pet's<br>"
			+ "own attack sound, so turn this off to silence both.",
		position = 22,
		section = combatSection
	)
	default boolean maxHitCelebrate()
	{
		return true;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
		keyName = "maxHitMin",
		name = "Max-hit celebrate minimum",
		description = "Only celebrate max hits that deal at least this much damage,<br>"
			+ "so small hits on a low-HP alt don't set the pet off constantly.",
		position = 23,
		section = combatSection
	)
	default int maxHitMin()
	{
		return 20;
	}

	@ConfigItem(
		keyName = "petHitIcon",
		name = "Pet damage icon",
		description = "Show your pet's picture next to the damage it deals as your<br>"
			+ "thrall, so its hits read as its own. Uses the pet's inventory-item<br>"
			+ "sprite, matched by name automatically.",
		position = 2,
		section = combatSection
	)
	default boolean petHitIcon()
	{
		return true;
	}

	@Range(min = 8, max = 36)
	@ConfigItem(
		keyName = "petHitIconSize",
		name = "Damage icon size",
		description = "Width of the pet damage icon in pixels.",
		position = 3,
		section = combatSection
	)
	default int petHitIconSize()
	{
		return 13;
	}

	// ------------------------------------------------------------------
	// Combat
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "combatWander",
		name = "Wander in combat",
		description = "During combat the pet stops shadowing your every step and<br>"
			+ "wanders on its own within the range below, repositioning at<br>"
			+ "random intervals and watching the fight. It still follows if<br>"
			+ "you leave the area, and thrall mode always takes priority.",
		position = 4,
		section = combatSection
	)
	default boolean combatWander()
	{
		return true;
	}

	@Range(min = 2, max = 6)
	@ConfigItem(
		keyName = "wanderRange",
		name = "Wander range (tiles)",
		description = "How far from you the pet may wander during combat.",
		position = 5,
		section = combatSection
	)
	default int wanderRange()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "avoidMarkedTiles",
		name = "Avoid marked tiles",
		description = "The wandering pet will not come to a stop on any of your<br>"
			+ "Ground Markers tiles (it may still walk across them), keeping<br>"
			+ "your PvM markers readable. Thrall mode is unaffected: as your<br>"
			+ "thrall the pet stands wherever the fight puts it.",
		position = 20,
		section = combatSection
	)
	default boolean avoidMarkedTiles()
