	@Override
	protected void startUp()
	{
		hooks.registerRenderableDrawListener(drawListener);
		// Skills-tab HP/Prayer icons for the vitals labels (loaded once).
		spriteManager.getSpriteAsync(SpriteID.SKILL_HITPOINTS, 0, img -> hpIcon = img);
		spriteManager.getSpriteAsync(SpriteID.SKILL_PRAYER, 0, img -> prayIcon = img);
		spriteManager.getSpriteAsync(SpriteID.MINIMAP_ORB_SPECIAL_ICON, 0, img -> specIcon = img);
		spriteManager.getSpriteAsync(SpriteID.SKILL_ATTACK, 0, img -> attackIcon = img);
		petHitOverlay = new PetHitOverlay();
		overlayManager.add(petHitOverlay);
		petVitalsOverlay = new PetVitalsOverlay();
		overlayManager.add(petVitalsOverlay);
	}

	@Override
	protected void shutDown()
	{
		hooks.unregisterRenderableDrawListener(drawListener);
		overlayManager.remove(petHitOverlay);
		overlayManager.remove(petVitalsOverlay);
		hidingReal = false;
		clientThread.invoke(() ->
		{
			clearTintedBolts();
			releasePet();
			despawnGhost();
			pet = null;
		});
	}

	// ------------------------------------------------------------------
	// Rendering veto: hide the real pet while the ghost is active
	// ------------------------------------------------------------------

	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		if (hidingReal && renderable == pet)
		{
			return false;
		}
		if (thrall != null && ghost != null && renderable == thrall)
		{
			// Hide the thrall only while a ghost actually stands in for it —
			// with no pet out there is no ghost, and vetoing the thrall then
			// makes it silently vanish.
			return false;
		}
		return true;
	}

	// ------------------------------------------------------------------
	// Game-tick logic: follower detection, takeover, handoff
	// ------------------------------------------------------------------

	@Subscribe
	public void onGameTick(GameTick e)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}

		showReleaseNoticeOnce();

		if (suppressTakeoverTicks > 0)
		{
			suppressTakeoverTicks--;
		}

		if (rescanThrall)
		{
			rescanThrall = false;
			reacquireThrall(me);
		}

		// Refresh the worn prayer bonus once a tick: it sets how fast prayer
		// drains, which drives the prayer bar's creep.
		if (config.petVitals())
		{
			prayerBonus = computePrayerBonus();
		}

		// A provisional adoption has to be confirmed by the varbit shortly, or
		// it was somebody else's thrall after all and we hand it straight back.
		if (thrallProvisionalUntil > 0L)
		{
			if (client.getVarbitValue(Varbits.RESURRECT_THRALL) != 0)
			{
				thrallProvisionalUntil = 0L;
			}
			else if (System.currentTimeMillis() > thrallProvisionalUntil)
			{
				thrallProvisionalUntil = 0L;
				endThrall();
			}
		}

		// Backstop for a fresh cast whose NPC spawn beat the varbit update:
		// once the varbit confirms YOU have a thrall out and one of yours is
		// adjacent, adopt it here. Gated on the varbit, so it can never pick up
		// a stranger's thrall.
		if (config.thrallMode() && thrall == null && !impersonating
			&& client.getVarbitValue(Varbits.RESURRECT_THRALL) != 0)
		{
			NPC mine = findNearbyThrall(me, THRALL_ACQUIRE_RADIUS);
			if (mine != null)
			{
				thrall = mine;
				thrallAttached = false;
				lungeMs = 0f;
				docking = false;
				impersonating = true;
				thrallLostTicks = 0;
				armThrallDeadline();
			}
		}

		NPC found = findMyPet();
		if (found != null)
		{
			if (found != pet)
			{
				// New pet instance (server teleport-respawn while you outrun
				// it, or a scene reload). This game-tick path usually wins
				// the race against the render-loop one, so it MUST do the
				// same careful mid-cycle resume — when it just reset the
				// pose state instead, every pet teleport restarted the run
				// animation at frame 0 and let the materialize animation
				// play on the mirror (the "animation repeats while
				// sustained-running" bug: teleports only happen when the
				// pet can't keep up, which is why walking and short steps
				// never glitched).
				relinkPet(found);
			}
			pet = found;
		}

		// Only tear down when the follower is actually GONE (dismissed / picked
		// up) — the varp tells us this. Running out of render range leaves the
		// varp set, so the ghost stays alive and the real (slow) pet stays
		// hidden until it comes back. Never tear down mid-impersonation.
		if (!isFollowerActive() && thrall == null && !impersonating)
		{
			releasePet();
			pet = null;
			hidingReal = false;
			despawnGhost();
			return;
		}

		WorldPoint playerTile = me.getWorldLocation();
		idleTicks = playerTile.equals(lastPlayerTile) ? idleTicks + 1 : 0;
		// An instant jump this far is a teleport. Thralls never follow
		// through teleports — the summon is stranded where it was cast.
		boolean teleported = lastPlayerTile != null
			&& playerTile.distanceTo2D(lastPlayerTile) > 25;
		lastPlayerTile = playerTile;
		if (idleTicks > 2)
		{
			// Standing after the reload: the natural reaction beat applies
			// again to the next start.
			resumeAtSpeed = false;
		}

		// Combat tracking: only ACTUAL fighting arms wander, not every red
		// click. The tell is mutual targeting — in combat the NPC targets you
		// back; pickpocket / talk / shoo-away-dog it does not. (Dealing or
		// taking a hit also arms it, in onHitsplatApplied, which covers the
		// brief window before an NPC retaliates.)
		// NOTE: mutual targeting alone is NOT enough. An NPC faces you during
		// DIALOGUE too, so talking to a slayer master (Kuradel) armed combat
		// mode and the pet went wandering off afterwards. Require the NPC to be
		// something you could actually attack.
		Actor inter = me.getInteracting();
		if (inter instanceof NPC && inter.getInteracting() == me
			&& isAttackable((NPC) inter))
		{
			lastCombatMs = System.currentTimeMillis();
			lastOffenseMs = lastCombatMs; // you're squared up with it: attacking
			combatTarget = new java.lang.ref.WeakReference<>(inter);
		}
		// Pre-arm the DPS clock at engagement (any NPC you face, mutual or
		// not — a false arm on a pickpocket costs nothing, since sessions
		// only start when damage actually lands).
		if (inter instanceof NPC
			&& (dpsPending == null || dpsPending.get() != inter))
		{
			dpsPending = new java.lang.ref.WeakReference<>(inter);
			dpsPendingMs = System.currentTimeMillis();
		}

		if (hidingReal)
		{
			ensureHijack();
		}

		// Thrall impersonation is independent of the follow state and survives
		// pet render blips.
		if (thrall != null)
		{
			if (!hidingReal || ghost == null)
			{
				hidingReal = true;
				spawnGhost(me);
			}
			return;
		}

		// Thrall left render range while still active: keep impersonating and
		// re-acquire it when it (or a fresh cast) comes back, rather than
		// reverting to a normal pet. Give up only after a long timeout.
		if (impersonating)
		{
			// Unrecoverable: you teleported away (the stranded thrall can
			// never re-enter range — waiting the full window just kept the
			// pet hidden for over a minute), or the summon's own timer ran
			// out while it was off-screen. Resume normal following now.
			if (teleported || client.getTickCount() > thrallDeadlineTick
				|| client.getVarbitValue(Varbits.RESURRECT_THRALL) == 0
				// Thrall mode switched off while the summon was out of range:
				// without this the pet stayed hidden until the thrall expired.
				|| !config.thrallMode())
			{
				// The varbit is the EXACT signal: it drops to 0 the moment
				// the summon expires, no matter how far away it was — the
				// pet comes back immediately instead of waiting out the
				// magic-level estimate.
				log.debug("Thrall unrecoverable ({}); resuming follow",
					teleported ? "teleported away" : "expired");
				endThrall();
				return;
			}
			// The real pet must never show while impersonating, even mid-run.
			hidingReal = true;
			NPC t = findNearbyThrall(me, THRALL_REACQUIRE_RADIUS);
			if (t != null)
			{
				thrall = t;
				thrallAttached = false;
				lungeMs = 0f;
				thrallLostTicks = 0;
				// No deadline re-arm: same summon, same expiry (the per-frame
				// re-acquire already follows this rule).
				log.debug("Re-acquired thrall id={}", t.getId());
			}
			else if (++thrallLostTicks > THRALL_REACQUIRE_TICKS)
			{
				log.debug("Thrall gone for good; resuming follow");
				endThrall();
			}
			return;
		}

		if (!hidingReal)
		{
			if ((idleTicks == 0
					|| (idleWanderArmed() && !inCombat()))
				&& found != null && suppressTakeoverTicks == 0)
			{
				// You started moving (or stood still so long the pet got
				// bored and wants to wander): take over visually from where
				// the real pet currently is.
				hidingReal = true;
				spawnGhost(me);
			}
			return;
		}

		// The rest is normal-follow handback, which needs a live pet. During a
		// render blip just coast — no handback.
		if (found == null)
		{
			return;
		}

		// Handback: once you're idle, the ghost settled, and the real pet has
		// arrived nearby, start docking — stroll onto the pet's exact spot
		// and swap invisibly (see dockTick).
		if (idleTicks == 0)
		{
			if (docking)
			{
				abortDock();
			}
		}
		else if (config.handoffEnabled()
			&& !docking
			&& !settling
			&& !previewing // never reveal the real (different-looking) pet mid-preview
			&& !inCombat() // no handing back mid-fight (bolting a boss counts as idle)
			&& !combatWandering // a bored wanderer stays out — no dock/wander loop
			&& !idleWanderArmed()
			&& ghost != null
			&& ghostV == 0f
			&& idleTicks >= Math.max(1, config.handoffTicks())
			&& pet.getWorldLocation().distanceTo(playerTile) <= 2)
		{
			LocalPoint pp = pet.getLocalLocation();
			if (pp != null
				&& Math.hypot(pp.getX() - ghostX, pp.getY() - ghostY) <= 2.5 * Perspective.LOCAL_TILE_SIZE)
			{
				docking = true;
			}
		}
	}

	// ------------------------------------------------------------------
	// Per-frame follower simulation (BeforeRender: once per rendered frame)
	// ------------------------------------------------------------------

	@Subscribe
	public void onBeforeRender(BeforeRender e)
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			// Resolve a pending scene-origin shift BEFORE anything touches
			// local coordinates, then record this frame's base as the new
			// reference (never updated mid-load, so it stays the PRE-load
			// base until the shift is applied).
			if (pendingSceneShift)
			{
				pendingSceneShift = false;
				applySceneShift();
			}
			lastBaseX = client.getBaseX();
			lastBaseY = client.getBaseY();
		}
		// Retire queued stray bolts here — the render hook sits between
		// engine passes, so shortening a flight is safe now. End cycle goes
		// one step FORWARD (engine retires it naturally next pass); a past
		// value re-poisons the same math we crashed on.
		if (!pendingBoltKills.isEmpty())
		{
			int cyc = client.getGameCycle();
			for (Projectile bp : pendingBoltKills)
			{
				// A suppressed bolt (pet still travelling to the thrall's spot)
				// can render for the one frame between launch and this retire.
				// Recolour it to the pet's tint first so that frame is never
				// the default bolt colour — the "appears default until the pet
				// settles in" leak. (Truly invisible when the retire beats the
				// launch, which is the usual case.)
				tintBoltNow(bp);
				if (cyc < bp.getEndCycle())
				{
					bp.setEndCycle(cyc + 1);
				}
			}
			pendingBoltKills.clear();
		}
		// Bolts in flight outlive state changes (handoff, thrall expiry), so
		// they update before any early return below.
		updateTintedBolts();
		if (!hidingReal || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}

		LocalPoint p = me.getLocalLocation();
		if (p == null)
		{
			return;
		}

		// --- combat state -------------------------------------------------
		// Wander runs off OFFENSE, not mere combat: getting chipped by an
		// aggressive mob while you stand there shouldn't send the pet off
		// pacing — only you actively fighting does.
		boolean combatNow = inOffense();
		if (combatNow && !combatPrev)
		{
			combatEngagedMs = System.currentTimeMillis();
		}
		combatPrev = combatNow;

		// --- transmog preview state --------------------------------------
		// When a preview id is set, the follower renders as THAT pet: the
		// mirror stays hidden and the cache-built stand-in (with the
		// previewed pet's own pose anims) is shown full-time, driven by the
		// same simulation.
		int cfgPreview = config.transmog().getNpcId();
		if ((cfgPreview >= 0) != previewing || (previewing && cfgPreview != activePreviewId))
		{
			previewing = cfgPreview >= 0;
			activePreviewId = previewing ? cfgPreview : -1;
			// Rebuild everything for the new appearance. Restore the pet's
			// TRUE animation table before the re-capture: mid-transmog the
			// table holds the previous transmog's anim ids, and re-capturing
			// those as "original" froze the real pet's animations after
			// turning transmog off (its skeleton can't play foreign anims)
			// until a fresh NPC instance arrived with a clean table.
			releasePet();
			fallbackModel = null;
			fallbackForId = -1;
			blipAnimId = -1;
			if (pet != null)
			{
				ensureHijack();
				buildFallbackModel();
			}
			// The displayed pet changed, so its cadence profile changes with
			// it — even if the real pet NPC isn't linked right now.
			loadPetSpeed();
		}

		// The ghost mirrors the live pet NPC's model, so it can only be drawn
		// while that NPC is being rendered. When the real pet isn't rendered
		// (scene reload / far off screen), drop the ghost rather than draw its
		// recycled buffer (which would flash into other players/NPCs) — the
		// same brief absence the vanilla game shows while a pet teleports in.
		// Re-link EVERY FRAME (the game tick is too coarse: it added up to
		// 0.6 s of extra absence) so the ghost respawns the instant the pet
		// NPC renders again.
		if (pet == null)
		{
			NPC found = findMyPet();
			if (found != null)
			{
				relinkPet(found);
			}
			else if (!impersonating)
			{
				// Render blip: when you outrun render range the real pet NPC
				// despawns for a moment and the server teleports it back to
				// you. Keep ALL ghost state and keep simulating. The mirror
				// can't be drawn (recycled live buffer), so swap in the
				// animated cache-built stand-in — it keeps striding along
				// the same path until the NPC is back.
				if (ghost == null)
				{
					return;
				}
				showGhost(false);
				if (fallbackModel != null)
				{
					showBlip(true);
					updateBlipAnim();
					syncBlip();
				}
			}
		}
		// Previewing: never show the mirror; the stand-in IS the pet.
		if (previewing && ghost != null)
		{
			showGhost(false);
			if (fallbackModel != null)
			{
				showBlip(true);
				updateBlipAnim();
				syncBlip();
			}
		}
		else if (pet != null && ghost != null && !ghostShown && !impersonating)
		{
			showBlip(false);
			showGhost(true);
		}
		if (pet != null)
		{
			// Faux-run: each time the ENGINE advances the walk cycle,
			// accumulate the speed-proportional boost and push extra frames
			// as it overflows — cadence follows actual ground speed, and
			// because we only react to the engine's own advances the two
			// clocks can never stack.
			int curFrame = pet.getPoseAnimationFrame();
			float factor = cadenceFactor();
			if (cadenceEligible(factor) && hijackWalkAnim != null
				&& pet.getPoseAnimation() == poseWalk
				&& prevMirrorPoseFrame != -1 && curFrame != prevMirrorPoseFrame)
			{
				runBoostAcc += factor - 1f;
				int n = hijackWalkAnim.getNumFrames();
				while (runBoostAcc >= 1f && n > 0)
				{
					runBoostAcc -= 1f;
					curFrame = (curFrame + 1) % n;
					pet.setPoseAnimationFrame(curFrame);
				}
			}
			prevMirrorPoseFrame = curFrame;

			// Remember where the pose cycle is, so a blip re-link can resume
			// it mid-stride instead of restarting the animation.
			lastPoseFrame = curFrame;
		}
		if (ghost == null)
		{
			if (pet != null)
			{
				spawnGhost(me);
			}
			return;
		}

		long nowNanos = System.nanoTime();
		float dt = (nowNanos - lastFrameNanos) / 1_000_000f; // ms
		lastFrameNanos = nowNanos;
		dt = Math.max(0.1f, Math.min(100f, dt));
		updateFollowStyle(dt);
		// Once per frame, before anything calls place().
		updateNpcPush(dt);
		// Nothing re-places a PARKED pet, so a changed lean has to be applied
		// here. Without this it was computed but never drawn while parked,
		// then showed up as a sideways slide the moment the pet set off - and
		// the overhead display, which does follow the lean, drifted off it.
		if (thrall == null
			&& (Math.round(npcPushX) != appliedPushX || Math.round(npcPushY) != appliedPushY))
		{
			place(new LocalPoint(Math.round(ghostX), Math.round(ghostY)), pathPlane);
		}

		if (thrall != null)
		{
			if (!config.thrallMode())
			{
				endThrall();
			}
			else
			{
				thrallTick(dt);
				return;
			}
		}

		// Impersonating but the thrall is out of render range: try to
		// re-acquire every frame (instant snap-back on re-entering); until
		// then keep the ghost frozen and hidden (it's off-screen anyway) so
		// it never briefly reverts to a following pet.
		if (impersonating)
		{
			NPC t = findNearbyThrall(me, THRALL_REACQUIRE_RADIUS);
			if (t != null)
			{
				thrall = t;
				thrallAttached = false;
				lungeMs = 0f;
				thrallLostTicks = 0;
				// NOTE: no armThrallDeadline() here — re-acquiring an OLD
				// thrall must not extend its life. Re-arming on every
				// reacquire pushed the deadline out indefinitely, which is
				// why the pet never came back after running far away.
				showGhost(true);
				return;
			}
			showGhost(false);
			return;
		}

		if (docking)
		{
			dockTick(dt);
			return;
		}

		// --- combat wander ------------------------------------------------
		// In combat the pet stops shadowing you and repositions itself at
		// random intervals near you, watching the fight. Reuses the settle
		// machinery, so every move is collision-checked.
		//
		// Engage/disengage is HYSTERETIC on distance to you, and that's what
		// keeps attack-move-attack combat smooth: wander only STARTS when the
		// pet is genuinely close (within wander range), but once wandering it
		// keeps going until you're far past it (disengage margin). The wide
		// dead-band means normal moving-and-attacking never rattles the
		// pet between wander and follow — and if the pet ends up far from you
		// (e.g. it couldn't pace into a walled grid you ran into), it's
		// beyond the engage threshold, so it simply FOLLOWS your walkable
		// path back to you instead of thrashing against the boundary.
		boolean combatEligible = combatNow && config.combatWander()
			&& thrall == null && !impersonating;
		boolean combatSettledIn = System.currentTimeMillis() - combatEngagedMs
			> COMBAT_FOLLOW_GRACE_MS;
		// Bored wander: minutes of you standing still and the pet starts
		// pacing around on its own — same machinery, no fight to watch.
		boolean idleEligible = idleWanderArmed() && !inCombat()
			&& thrall == null && !impersonating;
		float distToOwner = (float) Math.hypot(p.getX() - ghostX, p.getY() - ghostY);
		float engageDist = config.wanderRange() * (float) Perspective.LOCAL_TILE_SIZE;
		float disengageDist = (config.wanderRange() + 6) * (float) Perspective.LOCAL_TILE_SIZE;
		// ALERTED by low HP/Prayer: the pet drops whatever it was doing and
		// comes to you for the alert window, then resumes wandering on its own.
		boolean alerted = System.currentTimeMillis() < petAlertUntilMs;
		if (alerted && combatWandering)
		{
			combatWandering = false;
			settling = false;
			restDone = false;
			combatReturning = true;
			reseedFromGhost();
		}
		if (!alerted && ((combatEligible && combatSettledIn) || idleEligible))
		{
			if (combatWandering ? distToOwner <= disengageDist : distToOwner <= engageDist)
			{
				combatWanderTick(dt, p);
				return;
			}
			// Too far to pace: fall back to normal follow to close the gap;
			// wander re-engages once the pet is back within engage range.
			if (combatWandering)
			{
				combatWandering = false;
				settling = false;
				restDone = false;
				combatReturning = true; // jog back, don't slingshot
				reseedFromGhost();
			}
		}
		else if (combatWandering)
		{
			// Combat over: back to being your follower.
			combatWandering = false;
			settling = false;
			restDone = false;
			combatReturning = true;
			reseedFromGhost();
		}

		// --- beside-the-owner rest state ----------------------------------
		if (settling || restDone)
		{
			if (idleTicks == 0)
			{
				// You set off again: resume following from wherever the
				// ghost stands (it left the recorded path to settle).
				settling = false;
				restDone = false;
				reseedFromGhost();
				// fall through into normal following
			}
			else if (settling)
			{
				settleTick(dt);
				return;
			}
			else
			{
				// Resting beside you: just keep watching you. Full turn rate —
				// tracking your facing is part of following, not idle glancing.
				applyPose(POSE_IDLE);
				int toPlayer = jau(p.getX() - ghostX, p.getY() - ghostY);
				if (Math.abs(wrapAngle(toPlayer - ghost.getOrientation())) > IDLE_FACE_DEADBAND)
				{
					steer(toPlayer, dt);
				}
				return;
			}
		}

		// --- extend the rendered path -----------------------------------
		// Same-plane jumps of any size just become a long path segment the
		// ghost dashes across — it never teleports. Only a plane change
		// (stairs/ladders) reparks it, since there's nothing to walk through.
		int plane = client.getPlane();
		PathPoint tail = path.peekLast();

		if (tail == null || plane != pathPlane)
		{
			resetPathBehind(p, plane);
			return;
		}

		// Follow a gently smoothed version of your path, not your exact
		// tile-by-tile positions. Diagonal running is a rapid staircase (one
		// tile forward, one across, repeating); mirrored exactly at a one-tile
		// gap the ghost jerked left/right every step. Low-pass filtering the
		// recorded points averages that zigzag into the straight diagonal it
		// approximates; a genuine sustained turn still comes through because
		// it doesn't alternate. A big single-frame jump (teleport/blip) snaps
		// through rather than smearing a long false trail.
		if (!pathSmoothInit)
		{
			pathSmoothX = p.getX();
			pathSmoothY = p.getY();
			pathSmoothInit = true;
		}
		else if ((float) Math.hypot(p.getX() - pathSmoothX, p.getY() - pathSmoothY) > PATH_SMOOTH_SNAP)
		{
			pathSmoothX = p.getX();
			pathSmoothY = p.getY();
		}
		else
		{
			float sc = Math.min(1f, dt / followSmoothTau);
			pathSmoothX += (p.getX() - pathSmoothX) * sc;
			pathSmoothY += (p.getY() - pathSmoothY) * sc;
		}

		// The smoothed sample is an AVERAGE of where you've been, so on a tight
		// corner it cuts the corner — straight through the wall, since the
		// recorded path is what the ghost then walks. (Worst on Loose, whose
		// tau is longest; Edgeville dungeon's corridors are full of these.)
		// If the smoothed point isn't legally reachable from the last recorded
		// one, record your ACTUAL position and resync the filter to it.
		if (!footprintWalkable(pathSmoothX, pathSmoothY)
			|| !strollClear(tail.x, tail.y, pathSmoothX, pathSmoothY))
		{
			pathSmoothX = p.getX();
			pathSmoothY = p.getY();
		}

		float step = (float) Math.hypot(pathSmoothX - tail.x, pathSmoothY - tail.y);
		if (step > 0.5f)
		{
			playerCum += step;
			path.addLast(new PathPoint(pathSmoothX, pathSmoothY, playerCum));
		}

		// Units per ms, smoothed over ~100 ms.
		playerSpeed += (step / dt - playerSpeed) * Math.min(1f, dt / 100f);

		// Straight-line distance to you — used by the double-back rule and
		// the short-step patience below.
		float directDX = p.getX() - ghostX;
		float directDY = p.getY() - ghostY;
		float directDist = (float) Math.hypot(directDX, directDY);

		// You doubled back INTO the ghost: a real pet doesn't keep running
		// away along its old line and then whip around — it stops, lets you
		// pass, and falls in behind. While you're heading at the ghost and
		// already inside resting distance, re-anchor its route straight to
		// you; the reseeded gap is negative, so the normal stop logic holds
		// it still (pivoting to watch you) until you've pulled ahead again.
		// Corners never trigger this: after a 90-degree turn the ghost is
		// behind your shoulder, well outside the 60-degree facing cone.
		if (idleTicks == 0 && directDist > 1f && directDist < gap)
		{
			double prad = me.getCurrentOrientation() * Math.PI / 1024.0;
			float pfx = -(float) Math.sin(prad);
			float pfy = -(float) Math.cos(prad);
			if ((pfx * -directDX + pfy * -directDY) / directDist > 0.5f)
			{
				reseedFromGhost();
			}
		}

		// --- route straightening (string pulling) -------------------------
		// See BRIDGE_LOOK. Runs continuously: one bridge per bend — after a
		// bridge the head of the route IS the chord, so it can't re-trigger
		// until a new bend enters the window.
		float bridgeArc = Math.min(ghostArc + BRIDGE_LOOK, playerCum);
		if (bridgeArc - ghostArc > 64f && path.size() >= 2)
		{
			float bx = ghostX;
			float by = ghostY;
			PathPoint bprev = path.peekFirst();
			boolean bfound = false;
			for (PathPoint pp : path)
			{
				if (pp.cum >= bridgeArc)
				{
					float span = pp.cum - bprev.cum;
					float f = span <= 0f ? 1f : (bridgeArc - bprev.cum) / span;
					bx = bprev.x + (pp.x - bprev.x) * f;
					by = bprev.y + (pp.y - bprev.y) * f;
					bfound = true;
					break;
				}
				bprev = pp;
			}
			if (!bfound)
			{
				bx = bprev.x;
				by = bprev.y;
				bridgeArc = bprev.cum;
			}
			float along = bridgeArc - ghostArc;
			float chord = (float) Math.hypot(bx - ghostX, by - ghostY);
			if (along - chord > BRIDGE_SLACK
				&& strollClear(ghostX, ghostY, bx, by))
			{
				// Rebuild the head of the route as the straight chord; keep
				// everything beyond the bridge point, distances shifted.
				Deque<PathPoint> straightened = new ArrayDeque<>();
				straightened.addLast(new PathPoint(ghostX, ghostY, 0f));
				straightened.addLast(new PathPoint(bx, by, chord));
				for (PathPoint pp : path)
				{
					if (pp.cum > bridgeArc + 0.5f)
					{
						straightened.addLast(new PathPoint(pp.x, pp.y, chord + (pp.cum - bridgeArc)));
					}
				}
				path.clear();
				path.addAll(straightened);
				playerCum = chord + (playerCum - bridgeArc);
				ghostArc = 0f;
			}
		}

		// --- decide the ghost's target speed ----------------------------
		float error = playerCum - (gap + gapDrift) - ghostArc;

		// --- break off and settle beside the owner when they stop ---------
		// Once you're standing and the ghost is within its last half-tile of
		// its on-path stop, divert to a free tile beside you instead of
		// always parking dead on your walked line (vanilla pets end up at
		// your flank as often as behind you). If no side tile passes the
		// collision checks it simply rests on the path like before.
		// Patience beat (idleTicks >= 2): the pet waits ~a second before
		// repositioning, and also settles from a short-step hold (within a
		// tile of resting range) — not just from an on-path stop.
		if (idleTicks >= followSettleTicks && !settling && !restDone
			&& (error <= STOP_DIST + 64f || directDist < gap + Perspective.LOCAL_TILE_SIZE))
		{
			if (chooseRestSpot(me))
			{
				settling = true;
				settleTick(dt);
				return;
			}
			if (ghostV == 0f)
			{
				restDone = true;
				applyPose(POSE_IDLE);
				return;
			}
		}

		float vTarget;
		if (error <= STOP_DIST)
		{
			vTarget = 0f;
		}
		else if (ghostV == 0f
			&& (error < (resumeAtSpeed ? START_DIST : followStartDist)
				|| (idleTicks >= 1 && directDist < gap + Perspective.LOCAL_TILE_SIZE)))
		{
			// Reaction beat — and short-step patience: a standing owner
			// shuffling a tile or two doesn't send the pet scurrying after
			// them at full pace. It waits, and the settle logic repositions
			// it calmly (or not at all) once you've been still a moment.
			// After a mid-run zone reload (resumeAtSpeed) the style's full
			// reaction distance is suppressed for the FIRST start: the ghost
			// respawns AT its follow spot, so the stop branch above zeroes
			// it instantly and a Loose/Medium pet then stood staring for its
			// whole reaction distance right after popping in.
			vTarget = 0f;
		}
		else if (idleTicks >= 1 && error <= 512f)
		{
			// You've stopped: approach at a pace set by the REMAINING
			// distance, like a vanilla follower — walk short corrections,
			// only run when genuinely far behind. (Inheriting your last
			// running speed here made a two-tile catch-up look like a
			// sprint next to the real thing.)
			float far = Math.min(1f, Math.max(0f, (error - 96f) / 256f));
			vTarget = WALK_SPEED + (RUN_SPEED - WALK_SPEED) * far;
		}
		else
		{
			// Continuous cruise: match your pace plus a gentle proportional
			// catch-up term, capped by a dash ceiling that scales with the
			// gap (huge gaps still close in under a second, never teleport).
			// One smooth curve — the old hard cruise/dash threshold at
			// CATCHUP_DIST banged the speed up and down around corners,
			// which read as rubber-banding.
			float v = playerSpeed + error / followSlope;
			float cap = Math.max(CATCHUP_SPEED, error / 700f);
			vTarget = Math.max(WALK_SPEED * 0.85f, Math.min(cap, v));
		}

		// Returning to follow after wandering off in combat: the pet can be
		// a few tiles behind. Cap it to a WALK — during combat you're
		// moving a lot and a pet sprinting around is distracting. But the
		// cap is ONLY for that short in-fight saunter: once combat ends, or
		// the gap says you're genuinely traveling (running away mid-fight),
		// it releases so the pet runs and keeps up like normal.
		if (combatReturning)
		{
			if (error <= gap + gapDrift + STOP_DIST)
			{
				combatReturning = false; // caught up: normal follow again
			}
			else if (!inCombat() || error > 5f * Perspective.LOCAL_TILE_SIZE)
			{
				// You're genuinely traveling (running away mid-fight or after
				// it): the pet RUNS, but at a modest sprint ceiling. Releasing
				// straight into the cruise branch's gap-scaled dash ceiling
				// slingshotted it across the screen from combat-exit gaps.
				// ~1.5x run gains 1.7 tiles/s on a running owner: a 9-tile
				// combat gap closes in a few seconds of visible sprinting.
				vTarget = Math.min(vTarget, RUN_SPEED * 1.5f);
			}
			else
			{
				vTarget = Math.min(vTarget, WALK_SPEED);
			}
		}
		if (vTarget > 0f)
		{
			// First start after the reload has happened; the style's normal
			// reaction beat applies from here on.
			resumeAtSpeed = false;
		}

		// Pivot before walking: if the path wants the ghost to head somewhere
		// its body isn't facing yet, slow it down (proportionally, floored at
		// TURN_GATE_MIN) so it visibly turns in place and then sets off,
		// rather than sliding sideways while rotating. Only a huge gap (a
		// teleport-scale 4+ tiles) overrides the gate — exempting ordinary
		// catch-up let the gap that builds DURING the pivot disable the gate
		// mid-turn, and the ghost dashed off sideways half-rotated, then
		// whipped around (the stall-then-burst artifact).
		if (vTarget > 0f && error <= 512f)
		{
			int mis = Math.abs(wrapAngle(desiredHeading - ghost.getOrientation()));
			if (mis > TURN_GATE_START)
			{
				float t = Math.min(1f, (mis - TURN_GATE_START) / (float) (TURN_GATE_FULL - TURN_GATE_START));
				vTarget *= 1f - t * (1f - TURN_GATE_MIN);
			}
		}

		// Never sprint at point-blank range: catch-up overspeed right next
		// to you is what reads as the pet LUNGING/slingshotting through
		// your character whenever its route swings. Far away it can still
		// dash; nearby it arrives at an honest run.
		if (directDist < gap * 1.5f)
		{
			vTarget = Math.min(vTarget, RUN_SPEED);
		}

		// Exponential approach (~120 ms time constant) so any target speed,
		// including big dashes, ramps smoothly.
		ghostV += (vTarget - ghostV) * Math.min(1f, dt / 120f);
		if (vTarget == 0f && ghostV < 0.02f)
		{
			ghostV = 0f;
		}

		// --- advance along the path --------------------------------------
		if (ghostV > 0f)
		{
			ghostArc = Math.min(ghostArc + ghostV * dt, playerCum - (gap + gapDrift) * 0.75f);
			moveGhostToArc(dt);
		}

		// --- pose: driven by a SLOW-smoothed speed --------------------------
		// The diagnostics showed the instantaneous speed "breathing" across
		// the walk/run threshold about twice a second while cruising (the
		// feedback between matching your pace and closing the gap), and each
		// crossing flipped the pose. Deciding on a ~400 ms-smoothed speed
		// removes the breathing entirely; hysteresis and a longer dwell
		// handle what's left. (applyPose additionally never restarts the
		// cycle unless the animation id truly changes.)
		poseSpeed += (ghostV - poseSpeed) * Math.min(1f, dt / 400f);
		int newState;
		if (vTarget == 0f && ghostV == 0f)
		{
			newState = POSE_IDLE;
		}
		else if (poseState == POSE_RUN)
		{
			newState = poseSpeed < RUN_SPEED * 0.55f ? POSE_WALK : POSE_RUN;
		}
		else
		{
			newState = poseSpeed > RUN_SPEED * 0.75f ? POSE_RUN : POSE_WALK;
		}
		long nowMs = nowNanos / 1_000_000L;
		boolean walkRunSwap = (newState == POSE_WALK && poseState == POSE_RUN)
			|| (newState == POSE_RUN && poseState == POSE_WALK);
		if (walkRunSwap && nowMs - lastPoseSwitchMs < 600)
		{
			newState = poseState;
		}
		if (newState != poseState)
		{
			lastPoseSwitchMs = nowMs;
		}
		applyPose(newState);

		// At rest, turn to face you — a pet watching its owner. Full rate:
		// keeping up with your facing is following, not idle glancing. The
		// wide deadband keeps it from fidgeting at small angles.
		if (newState == POSE_IDLE)
		{
			int toPlayer = jau(p.getX() - ghostX, p.getY() - ghostY);
			if (Math.abs(wrapAngle(toPlayer - ghost.getOrientation())) > IDLE_FACE_DEADBAND)
			{
				steer(toPlayer, dt);
			}
		}
	}

	/**
	 * Hand back to the real pet without a visible pop: stroll the ghost onto
	 * the pet's exact position, sweep to its facing, then swap.
	 */
	private void dockTick(float dt)
	{
		if (pet == null)
		{
			docking = false;
			return;
		}

		LocalPoint pp = pet.getLocalLocation();
		if (pp == null)
		{
			docking = false;
			return;
		}

		float dx = pp.getX() - ghostX;
		float dy = pp.getY() - ghostY;
		float d = (float) Math.hypot(dx, dy);

		if (d > DOCK_ARRIVE)
		{
			applyPose(d > 24f ? POSE_WALK : poseState);
			float sp = Math.min(WALK_SPEED * dt, d);
			ghostX += dx / d * sp;
			ghostY += dy / d * sp;
			steer(jau(dx, dy), dt);
			place(new LocalPoint(Math.round(ghostX), Math.round(ghostY)), pathPlane);
			return;
		}

		applyPose(POSE_IDLE);
		int facing = pet.getCurrentOrientation();
		int diff = wrapAngle(facing - ghost.getOrientation());
		if (Math.abs(diff) > DOCK_FACING)
		{
			steer(facing, dt);
			return;
		}

		// Aligned in place, pose, and facing — swap is invisible.
		releasePet();
		hidingReal = false;
		docking = false;
		despawnGhost();
	}

	/**
	 * The player moved again mid-dock: resume following from wherever the
	 * ghost stands by reseeding the path from it to the player.
	 */
	private void abortDock()
	{
		docking = false;
		reseedFromGhost();
	}

	/** Rebuild the follow path as [ghost, player] from wherever the ghost is. */
	private void reseedFromGhost()
	{
		Player me = client.getLocalPlayer();
		LocalPoint p = me != null ? me.getLocalLocation() : null;
		if (p == null)
		{
			return;
		}
		path.clear();
		pathPlane = client.getPlane();
		float d = (float) Math.hypot(p.getX() - ghostX, p.getY() - ghostY);
		path.addLast(new PathPoint(ghostX, ghostY, 0f));
		if (d > 1f)
		{
			path.addLast(new PathPoint(p.getX(), p.getY(), d));
		}
		playerCum = d;
		ghostArc = 0f;
		ghostV = 0f;
		playerSpeed = 0f;
		pathSmoothInit = false;
		if (ghost != null)
		{
			desiredHeading = ghost.getOrientation();
		}
	}

	/** Stroll the last leg onto the chosen rest tile, then watch the owner. */
	private void settleTick(float dt)
	{
		float dx = restX - ghostX;
		float dy = restY - ghostY;
		float d = (float) Math.hypot(dx, dy);

		if (d > DOCK_ARRIVE)
		{
			applyPose(d > 24f ? POSE_WALK : poseState);
			float sp = Math.min(WALK_SPEED * dt, d);
			ghostX += dx / d * sp;
			ghostY += dy / d * sp;
			int face = jau(dx, dy);
			if (combatWandering && d < 110f)
			{
				// Landing blend: begin sweeping toward the fight over the
				// last stretch of the stroll so the turn completes AS the
				// pet stops — stop-then-pivot read as unnatural.
				int watch = combatWatchHeading();
				if (watch != -1)
				{
					face = watch;
				}
			}
			// Combat repositioning otherwise faces the direction of travel —
			// the owner-lock (if enabled) resumes once parked.
			else if (config.alwaysFaceOwner() && !combatWandering)
			{
				Player owner = client.getLocalPlayer();
				LocalPoint op = owner != null ? owner.getLocalLocation() : null;
				if (op != null)
				{
					face = jau(op.getX() - ghostX, op.getY() - ghostY);
				}
			}
			steer(face, dt);
			place(new LocalPoint(Math.round(ghostX), Math.round(ghostY)), pathPlane);
			return;
		}

		ghostX = restX;
		ghostY = restY;
		place(new LocalPoint(Math.round(restX), Math.round(restY)), pathPlane);
		applyPose(POSE_IDLE);
		ghostV = 0f;
		settling = false;
		restDone = true;
	}

	/**
	 * True when the bored-wander behaviour is allowed to run right now: the
	 * option is on and you've stood still for about three minutes.
	 */
	private boolean idleWanderArmed()
	{
		if (!config.idleWander())
		{
			return false;
		}
		return idleTicks >= IDLE_WANDER_TICKS;
	}

	/**
	 * True if this NPC is something you can actually fight (it offers an
	 * "Attack" option). Shopkeepers, slayer masters and other talk-only NPCs
	 * still turn to FACE you during dialogue, which is indistinguishable from
	 * combat's mutual targeting without this check.
	 */
	private boolean isAttackable(NPC n)
	{
		NPCComposition c = n != null ? n.getTransformedComposition() : null;
		if (c == null)
		{
			return false;
		}
		String[] actions = c.getActions();
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (a != null && a.equalsIgnoreCase("Attack"))
			{
				return true;
			}
		}
		return false;
	}

	/** True within a few seconds of the last combat evidence. */
	private boolean inCombat()
	{
		return System.currentTimeMillis() - lastCombatMs < 8000;
	}

	/** True within a few seconds of evidence YOU are attacking something. */
	private boolean inOffense()
	{
		return System.currentTimeMillis() - lastOffenseMs < 8000;
	}

	/**
	 * Per-frame combat positioning: stroll to the current spot, watch the
	 * fight from it, and pick a fresh spot at random intervals. All movement
	 * goes through settleTick, so it inherits the collision-checked strolls
	 * and never clips through anything.
	 */
	private void combatWanderTick(float dt, LocalPoint p)
	{
		if (!combatWandering)
		{
			combatWandering = true;
			nextWanderMs = 0; // reposition promptly on engage
			nextDecisionMs = 0;
		}
		// Forced step-aside FIRST, even mid-stroll: if you (or the mob you're
		// fighting) are on or right next to the pet's tile, get clear NOW via a
		// dedicated nearest-clear-tile search. This bypasses the aesthetic
		// wander filters (keepOut, projectile-lane, "nice hop") that could
		// otherwise reject every nearby tile and leave the pet sitting there.
		// 1.6 tiles catches diagonal neighbours (~1.41 tiles centre-to-centre).
		float fts = (float) Perspective.LOCAL_TILE_SIZE;
		Actor ct = combatTarget != null ? combatTarget.get() : null;
		LocalPoint ctl = ct != null ? ct.getLocalLocation() : null;
		boolean crowded = Math.hypot(p.getX() - ghostX, p.getY() - ghostY) < 1.6f * fts
			|| (ctl != null
				&& Math.hypot(ctl.getX() - ghostX, ctl.getY() - ghostY) < 1.6f * fts);
		// Cooldown between step-asides: without it, a mob sitting on the pet had
		// it pick a new escape tile every frame, whipping its facing back and
		// forth (the "spins nonstop"). Commit to one move and let it complete.
		long crowdNow = System.currentTimeMillis();
		if (crowded && !settling && crowdNow >= nextStepAsideMs)
		{
			// Arm the cooldown whether or not a spot was found. Failing the
			// search used to fall straight through to the normal wander re-pick
			// (every 100-400 ms, each with a new heading), which is what kept
			// spinning the pet when a mob sat on it and there was nowhere to go.
			nextStepAsideMs = crowdNow + 900;
			if (chooseStepAside(p, ctl))
			{
				restDone = false;
				settling = true;
				// A LONG lockout after actually moving. Back-to-back step-asides
				// (each a short hop in a new direction, as the mob shuffles with
				// the pet) is what read as slowly spinning on the spot. One move,
				// then leave it alone.
				nextStepAsideMs = crowdNow + 3000;
				nextWanderMs = Math.max(nextWanderMs, crowdNow + 3000);
			}
			else
			{
				// Boxed in: hold still and keep the current facing rather than
				// pivoting uselessly. Re-checked after the cooldown.
				nextWanderMs = Math.max(nextWanderMs, crowdNow + 900);
				applyPose(POSE_IDLE);
				return;
			}
		}
		if (settling)
		{
			// The stroll is the ONLY per-frame movement (needs to be, for
			// smoothness). The landing turn blends in via settleTick.
			settleTick(dt);
			return;
		}
		long now = System.currentTimeMillis();
		// The reposition DECISION — including the tile-scan, the one costly
		// piece of this feature — is throttled to a few times a second. It
		// never needs per-frame cadence; only the movement/facing below run
		// every frame, and those are trivial.
		if (now >= nextDecisionMs)
		{
			nextDecisionMs = now + 400;
			// Stranded ON a marked tile (detached there, or a marker was
			// dropped under the pet)? Don't wait the long interval — vacate.
			boolean onMarked = config.avoidMarkedTiles() && isTileMarked(ghostX, ghostY);
			if (onMarked && nextWanderMs > now + 600)
			{
				nextWanderMs = now + 500;
			}
			// Keep pace with a moving owner: if you've walked away from the
			// pet's spot (now beyond wander range), reposition SOON instead of
			// waiting out the long idle interval. This is what lets the pet
			// amble along at your side during attack-move-attack combat
			// instead of falling behind and then having to trek back.
			float spotToOwner = (float) Math.hypot(p.getX() - ghostX, p.getY() - ghostY);
			if (spotToOwner > config.wanderRange() * (float) Perspective.LOCAL_TILE_SIZE
				&& nextWanderMs > now + 600)
			{
				nextWanderMs = now + 500;
			}
			if (now >= nextWanderMs)
			{
				if (chooseCombatSpot(p, crowded))
				{
					restDone = false;
					settling = true;
					// Park for 10-20s and watch before picking the next spot.
					nextWanderMs = now + 10000 + followRng.nextInt(10000);
					// Pick what to look at ONCE, when a new spot is chosen.
					// Re-rolling on a timer while parked made a stationary pet
					// pivot back and forth for no reason (looked like spinning);
					// now the focus only changes when the pet has moved.
					rollWanderGaze();
				}
				else
				{
					// Nothing valid; back off (a bit sooner while on a marker).
					nextWanderMs = now + (onMarked ? 1500 : 3000);
				}
			}
		}
		if (settling)
		{
			settleTick(dt);
			return;
		}
		// Parked: watch the focus picked for this spot (rollWanderGaze). It is
		// chosen once per spot and HELD - no timed re-roll - so a stationary
		// pet doesn't pivot in place. The NPC-avoidance lean never steers the
		// facing either: turning to follow it is what used to spin the pet
		// whenever a mob stood on top of it.
		applyPose(POSE_IDLE);
		if (crowded)
		{
			// Something is standing on the pet: hold the current facing rather
			// than pivoting uselessly.
			return;
		}
		if (wanderGazeMode == 0)
		{
			faceCombat(p, dt);
		}
		else
		{
			float tx = wanderGazeMode == 2 ? gazeX : p.getX();
			float ty = wanderGazeMode == 2 ? gazeY : p.getY();
			int face = jau(tx - ghostX, ty - ghostY);
			if (Math.abs(wrapAngle(face - ghost.getOrientation())) > IDLE_FACE_DEADBAND)
			{
				steerGaze(face, dt);
			}
		}
	}

	/**
	 * Choose what the parked wanderer looks at for THIS spot: the fight, you, or
	 * a bystander. Only things in line of sight qualify, so it never turns to
	 * stare at a mob through a wall.
	 */
	private void rollWanderGaze()
	{
		Actor t = combatTarget != null ? combatTarget.get() : null;
		LocalPoint tl = t != null ? t.getLocalLocation() : null;
		// Only watch things it can see AND won't have to spin around for.
		boolean fight = t != null && inOffense() && tl != null
			&& hasLos(tl) && inFrontArc(tl);
		int roll = followRng.nextInt(100);
		if (fight)
		{
			wanderGazeMode = roll < 55 ? 0 : roll < 80 ? 1 : 2;
		}
		else
		{
			wanderGazeMode = roll < 55 ? 1 : 2;
		}
		if (wanderGazeMode == 2 && !pickGazeBystander())
		{
			wanderGazeMode = 1; // nobody in sight: watch the owner
		}
	}

	/**
	 * Snapshot a nearby actor (another player or a non-pet NPC) for the pet to
	 * glance at, into gazeX/gazeY. Returns false when there's nobody worth a
	 * look, so the caller can fall back to watching the owner.
	 */
	private boolean pickGazeBystander()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return false;
		}
		java.util.List<Actor> near = new java.util.ArrayList<>();
		int range = 12 * Perspective.LOCAL_TILE_SIZE;
		for (Player pl : client.getPlayers())
		{
			LocalPoint pl2 = pl != null ? pl.getLocalLocation() : null;
			if (pl != null && pl != me && pl2 != null
				&& dist2(pl2) < range * range && hasLos(pl2) && inFrontArc(pl2))
			{
				near.add(pl);
			}
		}
		for (NPC n : client.getNpcs())
		{
			if (n == null || n == pet || n == thrall || n.getLocalLocation() == null)
			{
				continue;
			}
			NPCComposition c = n.getTransformedComposition();
			if (c != null && c.isFollower())
			{
				continue; // other pets are beneath the pet's notice
			}
			// In sight, and not behind the pet (no spinning to look).
			LocalPoint nl = n.getLocalLocation();
			if (dist2(nl) < range * range && hasLos(nl) && inFrontArc(nl))
			{
				near.add(n);
			}
		}
		if (near.isEmpty())
		{
			return false;
		}
		LocalPoint at = near.get(followRng.nextInt(near.size())).getLocalLocation();
		gazeX = at.getX();
		gazeY = at.getY();
		return true;
	}

	/** Squared distance from the ghost's current spot to a local point. */
	private float dist2(LocalPoint lp)
	{
		float dx = lp.getX() - ghostX;
		float dy = lp.getY() - ghostY;
		return dx * dx + dy * dy;
	}

	/** Clear line of sight (no wall/obstacle) from the pet to a local point. */
	private boolean hasLos(LocalPoint lp)
	{
		return strollClear(ghostX, ghostY, lp.getX(), lp.getY());
	}

	/**
	 * The point is roughly in front of the pet (within ~100 deg of its current
	 * facing), so glancing at it is a small head-turn, not a spin-in-place.
	 */
	private boolean inFrontArc(LocalPoint lp)
	{
		int face = jau(lp.getX() - ghostX, lp.getY() - ghostY);
		return Math.abs(wrapAngle(face - ghost.getOrientation())) < 570;
	}

	// --- Ground Markers avoidance --------------------------------------
	// The set of the user's marked tiles resolved to LOCAL scene tiles for
	// the current scene — built the way the Ground Markers overlay itself
	// does (read each loaded region's config JSON, WorldPoint.fromRegion,
	// then WorldPoint.toLocalInstance to map template tiles into the live
	// scene). That toLocalInstance step is what makes it work inside raids
	// and other instances, not just open world. Rebuilt lazily whenever
	// markers change or the scene reloads.
	private final Set<Integer> markedSceneTiles = new HashSet<>();
	private boolean markedTilesDirty = true;

	private void ensureMarkedTiles()
	{
		if (!markedTilesDirty)
		{
			return;
		}
		markedTilesDirty = false;
		markedSceneTiles.clear();
		try
		{
			int[] regions = client.getMapRegions();
			if (regions == null)
			{
				return;
			}
			for (int region : regions)
			{
				String json = configManager.getConfiguration("groundMarker", "region_" + region);
				if (json == null || json.isEmpty())
				{
					continue;
				}
				com.google.gson.JsonArray arr = gson.fromJson(json, com.google.gson.JsonArray.class);
				for (com.google.gson.JsonElement el : arr)
				{
					com.google.gson.JsonObject o = el.getAsJsonObject();
					int rx = o.get("regionX").getAsInt();
					int ry = o.get("regionY").getAsInt();
					int z = o.has("z") ? o.get("z").getAsInt() : 0;
					WorldPoint template = WorldPoint.fromRegion(region, rx, ry, z);
					for (WorldPoint wp : WorldPoint.toLocalInstance(client, template))
					{
						LocalPoint lp = LocalPoint.fromWorld(client, wp);
						if (lp != null)
						{
							markedSceneTiles.add(packScene(lp.getSceneX(), lp.getSceneY(), wp.getPlane()));
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			log.debug("Ground marker read failed", ex); // never break movement
		}
	}

	/** Is the tile under this local point one of the user's Ground Markers? */
	private boolean isTileMarked(float cx, float cy)
	{
		ensureMarkedTiles();
		if (markedSceneTiles.isEmpty())
		{
			return false;
		}
		LocalPoint lp = new LocalPoint(Math.round(cx), Math.round(cy));
		return markedSceneTiles.contains(packScene(lp.getSceneX(), lp.getSceneY(), client.getPlane()));
	}

	private static int packScene(int sceneX, int sceneY, int plane)
	{
		return (plane << 16) | (sceneX << 8) | sceneY;
	}

	/** Heading toward the combat target (else the owner), or -1. */
	private int combatWatchHeading()
	{
		Actor t = combatTarget != null ? combatTarget.get() : null;
		LocalPoint tl = t != null ? t.getLocalLocation() : null;
		if (tl != null)
		{
			return jau(tl.getX() - ghostX, tl.getY() - ghostY);
		}
		Player owner = client.getLocalPlayer();
		LocalPoint pl = owner != null ? owner.getLocalLocation() : null;
		return pl != null ? jau(pl.getX() - ghostX, pl.getY() - ghostY) : -1;
	}

	/** Face the combat target if it exists, else the owner. */
	private void faceCombat(LocalPoint p, float dt)
	{
		Actor t = combatTarget != null ? combatTarget.get() : null;
		LocalPoint tl = t != null ? t.getLocalLocation() : null;
		// If the target has slipped behind a wall since we settled, watch the
		// owner instead of staring through the obstacle.
		int face = tl != null && hasLos(tl)
			? jau(tl.getX() - ghostX, tl.getY() - ghostY)
			: jau(p.getX() - ghostX, p.getY() - ghostY);
		if (Math.abs(wrapAngle(face - ghost.getOrientation())) > IDLE_FACE_DEADBAND)
		{
			steerGaze(face, dt);
		}
	}

	/**
	 * Pick a collision-checked wander spot: a hop of 3-4 tiles (biased
	 * toward 3) from where the pet already stands, kept within the
	 * configured range of you. Never adjacent to you, never on or beside
	 * the target's footprint, and (optionally) never ON a Ground Markers
	 * tile — your PvM markers stay readable.
	 */
	/**
	 * Urgent get-clear move: the nearest walkable tile a couple tiles away that
	 * ISN'T on or next to the owner or the combat target. Deliberately ignores
	 * the wander-aesthetic filters (marker/keepOut/projectile-lane, preferred
	 * hop size) so it can always find somewhere when it's being stood on;
	 * returns false only when the pet is genuinely walled in.
	 */
	private boolean chooseStepAside(LocalPoint p, LocalPoint ctl)
	{
		boolean corner = (ghostSize % 2) == 0;
		float ts = Perspective.LOCAL_TILE_SIZE;
		float bestHop = Float.MAX_VALUE;
		float bx = 0f;
		float by = 0f;
		boolean have = false;
		for (int dx = -4; dx <= 4; dx++)
		{
			for (int dy = -4; dy <= 4; dy++)
			{
				float cx = snapCoord(ghostX + dx * ts, corner);
				float cy = snapCoord(ghostY + dy * ts, corner);
				float hop = (float) Math.hypot(cx - ghostX, cy - ghostY);
				if (hop < 1.2f * ts || hop > 3.5f * ts)
				{
					continue; // a couple tiles: far enough to be clear, no dash
				}
				if (Math.hypot(cx - p.getX(), cy - p.getY()) < 1.7f * ts)
				{
					continue; // still crowding the owner
				}
				if (ctl != null && Math.hypot(cx - ctl.getX(), cy - ctl.getY()) < 1.7f * ts)
				{
					continue; // still crowding the target
				}
				if (config.avoidMarkedTiles() && isTileMarked(cx, cy))
				{
					continue;
				}
				if (!footprintWalkable(cx, cy) || !strollClear(ghostX, ghostY, cx, cy))
				{
					continue;
				}
				if (hop < bestHop)
				{
					bestHop = hop;
					bx = cx;
					by = cy;
					have = true;
				}
			}
		}
		if (have)
		{
			restX = bx;
			restY = by;
			return true;
		}
		return false;
	}

	private boolean chooseCombatSpot(LocalPoint p, boolean preferNear)
	{
		Actor t = combatTarget != null ? combatTarget.get() : null;
		LocalPoint tl = t != null ? t.getLocalLocation() : null;

		float keepOut = 1.5f * Perspective.LOCAL_TILE_SIZE;
		if (t instanceof NPC)
		{
			NPCComposition tc = ((NPC) t).getTransformedComposition();
			int ts = tc != null ? tc.getSize() : 1;
			keepOut = (ts * 0.5f + 1.5f) * Perspective.LOCAL_TILE_SIZE;
		}

		boolean corner = (ghostSize % 2) == 0;
		float ts = Perspective.LOCAL_TILE_SIZE;
		int rt = config.wanderRange();
		float range = rt * ts;

		// Scan EVERY tile in range rather than sampling a few 3-4 tile hops:
		// in a tight pocket those long hops all miss the nearby open tiles,
		// which made it escape far away when a small step was right there.
		// preferred = a nice medium hop that isn't crowding you; acceptable
		// = any other valid in-range tile (used only when the area is so
		// cramped there's no room for the preferred kind).
		List<float[]> preferred = new ArrayList<>();
		List<float[]> acceptable = new ArrayList<>();
		for (int dx = -rt; dx <= rt; dx++)
		{
			for (int dy = -rt; dy <= rt; dy++)
			{
				float cx = snapCoord(p.getX() + dx * ts, corner);
				float cy = snapCoord(p.getY() + dy * ts, corner);
				float distP = (float) Math.hypot(cx - p.getX(), cy - p.getY());
				if (distP > range || distP < ts * 0.5f)
				{
					continue; // out of range, or your own tile
				}
				float hop = (float) Math.hypot(cx - ghostX, cy - ghostY);
				if (hop < ts * 0.5f)
				{
					continue; // already standing here
				}
				if (config.avoidMarkedTiles() && isTileMarked(cx, cy))
				{
					continue;
				}
				if (tl != null && Math.hypot(cx - tl.getX(), cy - tl.getY()) < keepOut)
				{
					continue;
				}
				// Stay out of the projectile lane: don't rest on the line
				// between you and the target (where your ranged/mage shots
				// fly). For melee that segment is tiny, so it costs nothing.
				if (tl != null
					&& segDist(cx, cy, p.getX(), p.getY(), tl.getX(), tl.getY()) < 0.9f * ts)
				{
					continue;
				}
				if (!footprintWalkable(cx, cy) || !strollClear(ghostX, ghostY, cx, cy)
					|| !combatPathSafe(ghostX, ghostY, cx, cy, p, tl, keepOut))
				{
					continue;
				}
				float[] cand = {cx, cy};
				float loHop = 1.5f * ts;
				float hiHop = 4.5f * ts;
				if (distP >= 2f * ts - 32f && hop >= loHop && hop <= hiHop)
				{
					preferred.add(cand);
				}
				else
				{
					acceptable.add(cand);
				}
			}
		}
		List<float[]> pool = !preferred.isEmpty() ? preferred : acceptable;
		if (!pool.isEmpty())
		{
			float[] pick;
			if (preferNear && pool.size() > 1)
			{
				// Crowded: just step a COUPLE tiles clear, not across the room.
				// Take the nearest valid spot.
				pick = null;
				float bestHop = Float.MAX_VALUE;
				for (float[] c : pool)
				{
					float hop = (float) Math.hypot(c[0] - ghostX, c[1] - ghostY);
					if (hop < bestHop)
					{
						bestHop = hop;
						pick = c;
					}
				}
			}
			else
			{
				pick = pool.get(followRng.nextInt(pool.size()));
			}
			restX = pick[0];
			restY = pick[1];
			return true;
		}
		// Escaping BEYOND the wander range is only for its original purpose:
		// the pet is stranded ON a marked tile and has to vacate. Firing it
		// any time the in-range scan came up empty (a crowded pocket, one bad
		// frame) is what randomly launched the pet across the room even with
		// the range set to 2. Otherwise stay put and retry shortly.
		if (config.avoidMarkedTiles() && isTileMarked(ghostX, ghostY))
		{
			return chooseEscapeSpot(p, tl, keepOut);
		}
		return false;
	}

	/**
	 * Nearest free UNMARKED tile beyond the wander range — the escape hatch
	 * for when markers (or tight geometry) leave no valid in-range spot.
	 * Rings outward from the pet and takes the closest that passes every
	 * check, so it leaves a marked grid by the shortest route.
	 */
	private boolean chooseEscapeSpot(LocalPoint p, LocalPoint tl, float keepOut)
	{
		boolean corner = (ghostSize % 2) == 0;
		int start = config.wanderRange() + 1;
		// Only a couple of rings past the wander range. Searching 10 rings out
		// meant a range-2 pet could legally escape TWELVE tiles away, which is
		// what randomly flung it across the room mid-fight.
		for (int ring = start; ring <= start + 2; ring++)
		{
			float r = ring * (float) Perspective.LOCAL_TILE_SIZE;
			// Sample the ring at a jittered offset so repeated escapes don't
			// all pick the same bearing.
			float base = followRng.nextFloat() * (float) Math.PI * 2f;
			for (int a = 0; a < 16; a++)
			{
				double ang = base + a * Math.PI / 8.0;
				float cx = snapCoord(ghostX + (float) (Math.sin(ang) * r), corner);
				float cy = snapCoord(ghostY + (float) (Math.cos(ang) * r), corner);
				if (config.avoidMarkedTiles() && isTileMarked(cx, cy))
				{
					continue;
				}
				if (Math.hypot(cx - p.getX(), cy - p.getY()) < 2 * Perspective.LOCAL_TILE_SIZE - 32f)
				{
					continue;
				}
				if (tl != null && Math.hypot(cx - tl.getX(), cy - tl.getY()) < keepOut)
				{
					continue;
				}
				if (!footprintWalkable(cx, cy) || !strollClear(ghostX, ghostY, cx, cy)
					|| !combatPathSafe(ghostX, ghostY, cx, cy, p, tl, keepOut))
				{
					continue;
				}
				restX = cx;
				restY = cy;
				return true;
			}
		}
		return false;
	}

	/** Shortest distance from point (px,py) to the segment (ax,ay)-(bx,by). */
	private static float segDist(float px, float py, float ax, float ay, float bx, float by)
	{
		float vx = bx - ax;
		float vy = by - ay;
		float len2 = vx * vx + vy * vy;
		float t = len2 <= 1f ? 0f : ((px - ax) * vx + (py - ay) * vy) / len2;
		t = Math.max(0f, Math.min(1f, t));
		float dx = px - (ax + t * vx);
		float dy = py - (ay + t * vy);
		return (float) Math.hypot(dx, dy);
	}

	/** The stroll line may not pass over the player or the combat target. */
	private boolean combatPathSafe(float x0, float y0, float x1, float y1,
		LocalPoint p, LocalPoint tl, float keepOut)
	{
		float d = (float) Math.hypot(x1 - x0, y1 - y0);
		int steps = Math.max(1, (int) (d / 32f));
		for (int i = 1; i <= steps; i++)
		{
			float t = i / (float) steps;
			float x = x0 + (x1 - x0) * t;
			float y = y0 + (y1 - y0) * t;
			if (Math.hypot(x - p.getX(), y - p.getY()) < 1.25f * Perspective.LOCAL_TILE_SIZE)
			{
				return false;
			}
			if (tl != null && Math.hypot(x - tl.getX(), y - tl.getY()) < keepOut - 32f)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Pick a free tile beside the owner to rest on. Prefers the flank
	 * nearest the ghost, then the rear diagonals, then directly behind (the
	 * old default). Every candidate is collision-checked — footprint
	 * walkable and the stroll line clear — so the ghost never settles into
	 * a hedge or slides through a wall. Returns false when nothing beats
	 * standing where we already are.
	 */
	private boolean chooseRestSpot(Player me)
	{
		LocalPoint p = me.getLocalLocation();
		if (p == null)
		{
			return false;
		}

		double rad = me.getCurrentOrientation() * Math.PI / 1024.0;
		float fx = -(float) Math.sin(rad); // owner's forward
		float fy = -(float) Math.cos(rad);
		float lx = -fy; // owner's left flank
		float ly = fx;

		// Center-to-center distance that puts the pet's footprint adjacent
		// to the owner for any pet size.
		float r = 64f + ghostSize * 64f;

		boolean leftFirst =
			Math.hypot(p.getX() + lx * r - ghostX, p.getY() + ly * r - ghostY)
			<= Math.hypot(p.getX() - lx * r - ghostX, p.getY() - ly * r - ghostY);
		float s = leftFirst ? 1f : -1f;

		// Preference order: directly behind first (the classic follower
		// spot), then the rear diagonals, then the flanks — nearer side
		// first in each pair. But if the ghost already stands on ANY
		// acceptable spot, it stays put: where its approach lands it is
		// where it rests, which is what makes side-resting happen naturally
		// without pointless shuffling.
		final float diag = 0.7071f;
		float[][] dirs = {
			{-fx, -fy},                                         // directly behind
			{(lx * s - fx) * diag, (ly * s - fy) * diag},       // near rear diagonal
			{(-lx * s - fx) * diag, (-ly * s - fy) * diag},     // far rear diagonal
			{lx * s, ly * s},                                   // near flank
			{-lx * s, -ly * s},                                 // far flank
		};

		boolean corner = (ghostSize % 2) == 0; // even-size pets center on tile corners
		float gsx = snapCoord(ghostX, corner);
		float gsy = snapCoord(ghostY, corner);
		float bestX = 0f;
		float bestY = 0f;
		boolean haveBest = false;

		// Rest EXACTLY where the pet came to a halt if that spot is already
		// good — no snap to tile centre, no shuffle to a "preferred" flank.
		// The recenter/flank move happened a beat AFTER the stop (once the
		// settle timer fired), which is the "stops behind you then nudges
		// forward a second later" bug. Landing spot = resting spot.
		float tile = (float) Perspective.LOCAL_TILE_SIZE;
		float dOwner = (float) Math.hypot(ghostX - p.getX(), ghostY - p.getY());
		// strollClear, not a single canStep: this spot can be up to three
		// tiles out, and canStep only means anything between NEIGHBOURING
		// tiles (it let the pet "rest beside you" across a fence).
		if (dOwner >= 0.75f * tile && dOwner <= 3.0f * tile
			&& strollClear(p.getX(), p.getY(), ghostX, ghostY)
			&& footprintWalkable(ghostX, ghostY)
			&& !(config.avoidMarkedTiles() && isTileMarked(ghostX, ghostY)))
		{
			restX = ghostX;
			restY = ghostY;
			return true;
		}

		for (float[] dir : dirs)
		{
			float cx = snapCoord(p.getX() + dir[0] * r, corner);
			float cy = snapCoord(p.getY() + dir[1] * r, corner);

			// "Beside you" must mean actually beside you: a candidate with a
			// fence or wall edge between it and your tile is out, even
			// though both tiles are walkable.
			if (!strollClear(p.getX(), p.getY(), cx, cy))
			{
				continue;
			}

			if (!footprintWalkable(cx, cy) || !strollClear(ghostX, ghostY, cx, cy))
			{
				continue;
			}

			// Already on an acceptable spot: STAY PUT unless meaningfully off
			// the tile (near a tile edge). The natural follow stop lands ~24
			// units shy of the tile center, and strolling that tiny recenter
			// after the settle pause read as a delayed "nudge toward you"
			// every time you stopped.
			if (cx == gsx && cy == gsy)
			{
				if (Math.hypot(cx - ghostX, cy - ghostY) <= 48f)
				{
					return false;
				}
				restX = cx;
				restY = cy;
				return true;
			}

			if (!haveBest)
			{
				bestX = cx;
				bestY = cy;
				haveBest = true;
			}
		}
		if (haveBest)
		{
			restX = bestX;
			restY = bestY;
			return true;
		}
		return false;
	}

	/** Snap a local coordinate to a tile center (or corner for even sizes). */
	private static float snapCoord(float v, boolean corner)
	{
		return corner
			? Math.round(v / Perspective.LOCAL_TILE_SIZE) * (float) Perspective.LOCAL_TILE_SIZE
			: (float) Math.floor(v / Perspective.LOCAL_TILE_SIZE) * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_TILE_SIZE / 2f;
	}

	/** True if the pet's whole footprint centered at (cx, cy) is walkable. */
	private boolean footprintWalkable(float cx, float cy)
	{
		int swX = (int) Math.floor((cx - (ghostSize - 1) * 64f) / Perspective.LOCAL_TILE_SIZE);
		int swY = (int) Math.floor((cy - (ghostSize - 1) * 64f) / Perspective.LOCAL_TILE_SIZE);
		for (int i = 0; i < ghostSize; i++)
		{
			for (int j = 0; j < ghostSize; j++)
			{
				if (!tileWalkable(swX + i, swY + j))
				{
					return false;
				}
			}
		}
		return true;
	}

	/**
	 * The straight settle stroll must be steppable tile-to-tile. Checking
	 * only tile walkability let the ghost slide straight through fences:
	 * walls and fences live on tile EDGES in the collision map, and the
	 * tiles either side of a fence are both perfectly walkable.
	 */
	private boolean strollClear(float x0, float y0, float x1, float y1)
	{
		float d = (float) Math.hypot(x1 - x0, y1 - y0);
		int steps = Math.max(1, (int) (d / 32f));
		int px = (int) Math.floor(x0 / Perspective.LOCAL_TILE_SIZE);
		int py = (int) Math.floor(y0 / Perspective.LOCAL_TILE_SIZE);
		for (int i = 1; i <= steps; i++)
		{
			float t = i / (float) steps;
			int cx = (int) Math.floor((x0 + (x1 - x0) * t) / Perspective.LOCAL_TILE_SIZE);
			int cy = (int) Math.floor((y0 + (y1 - y0) * t) / Perspective.LOCAL_TILE_SIZE);
			if (cx == px && cy == py)
			{
				continue;
			}
			if (!canStep(px, py, cx, cy))
			{
				return false;
			}
			px = cx;
			py = cy;
		}
		return true;
	}

	/**
	 * One tile step is passable: both tiles walkable and no wall/fence edge
	 * between them. Diagonal steps require both cardinal corners open, like
	 * real movement, so nothing ever cuts through a fence corner.
	 */
	private boolean canStep(int ax, int ay, int bx, int by)
	{
		int dx = Integer.signum(bx - ax);
		int dy = Integer.signum(by - ay);
		if (dx == 0 && dy == 0)
		{
			return true;
		}
		if (dx != 0 && dy != 0)
		{
			return canStep(ax, ay, bx, ay) && canStep(bx, ay, bx, by)
				&& canStep(ax, ay, ax, by) && canStep(ax, by, bx, by);
		}
		if (!tileWalkable(ax, ay) || !tileWalkable(bx, by))
		{
			return false;
		}
		int fa = flagsAt(ax, ay);
		int fb = flagsAt(bx, by);
		if (dx == 1)
		{
			return (fa & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0
				&& (fb & CollisionDataFlag.BLOCK_MOVEMENT_WEST) == 0;
		}
		if (dx == -1)
		{
			return (fa & CollisionDataFlag.BLOCK_MOVEMENT_WEST) == 0
				&& (fb & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0;
		}
		if (dy == 1)
		{
			return (fa & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0
				&& (fb & CollisionDataFlag.BLOCK_MOVEMENT_SOUTH) == 0;
		}
		return (fa & CollisionDataFlag.BLOCK_MOVEMENT_SOUTH) == 0
			&& (fb & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0;
	}

	/** Walkability of the scene tile containing a local-space point. */
	private boolean openAt(float localX, float localY)
	{
		int sx = (int) Math.floor(localX / Perspective.LOCAL_TILE_SIZE);
		int sy = (int) Math.floor(localY / Perspective.LOCAL_TILE_SIZE);
		return tileWalkable(sx, sy);
	}

	/** Collision-map check for a single scene tile on the current plane. */
	private boolean tileWalkable(int sceneX, int sceneY)
	{
		int f = flagsAt(sceneX, sceneY);
		int block = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
			| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
			| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;
		return f != -1 && (f & block) == 0;
	}

	/** Raw collision flags for a scene tile, or -1 (treat as blocked) when unavailable. */
	private int flagsAt(int sceneX, int sceneY)
	{
		CollisionData[] maps = client.getCollisionMaps();
		if (maps == null)
		{
			return -1;
		}
		int plane = client.getPlane();
		if (plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return -1;
		}
		int[][] flags = maps[plane].getFlags();
		if (sceneX < 0 || sceneY < 0 || sceneX >= flags.length || sceneY >= flags[sceneX].length)
		{
			return -1;
		}
		return flags[sceneX][sceneY];
	}

	// ------------------------------------------------------------------
	// Thrall impersonation
	// ------------------------------------------------------------------

	/**
	 * While a thrall is tracked it is hidden, and the ghost rides its exact
	 * position and facing — pathing, targeting, and turning are all the
	 * engine's own, so they stay native. The pet has no attack animation,
	 * so each time the thrall starts an action animation the ghost lunges
	 * forward and back instead.
	 */
	private void thrallTick(float dt)
	{
		LocalPoint tp = thrall.getLocalLocation();
		if (tp == null)
		{
			endThrall();
			return;
		}
		int plane = client.getPlane();

		float dx = tp.getX() - ghostX;
		float dy = tp.getY() - ghostY;
		float d = (float) Math.hypot(dx, dy);

		if (!thrallAttached)
		{
			if (d > Perspective.LOCAL_TILE_SIZE * 12f)
			{
				// The ghost is stranded far away (offscreen impersonation
				// loss, or a resummon while it rode the old thrall): jogging
				// across the map would leave the new thrall invisible with
				// nothing standing in — materialize on it instead. The
				// showGhost also un-hides a ghost hidden during the loss.
				ghostX = tp.getX();
				ghostY = tp.getY();
				showGhost(true);
			}
			else if (d > 6f)
			{
				showGhost(true);
				boolean attacking = (pet != null && pet.getAnimation() != -1) || lungeMs > 0f;
				if (attacking)
				{
					// An attack fired mid-approach: stop in place, face the
					// thrall's victim, let the attack play out, then resume
					// the approach from a standstill.
					lungeMs = Math.max(0f, lungeMs - dt);
					thrallApproachV = 0f;
					applyPose(POSE_IDLE);
					Actor foe = thrall.getInteracting();
					LocalPoint fl = foe != null ? foe.getLocalLocation() : null;
					int face = fl != null
						? jau(fl.getX() - ghostX, fl.getY() - ghostY)
						: jau(dx, dy);
					steer(face, dt);
				}
				else
				{
					// Ease up to a jog and ease back down into arrival — the
					// old constant full-tilt sprint across long rooms read as
					// unnatural. Speed target shrinks with the remaining
					// distance, so it decelerates into the thrall's spot.
					float target = Math.min(RUN_SPEED * 0.9f, d / 300f);
					thrallApproachV += (target - thrallApproachV) * Math.min(1f, dt / 150f);
					float sp = Math.min(thrallApproachV * dt, d);
					ghostX += dx / d * sp;
					ghostY += dy / d * sp;
					steer(jau(dx, dy), dt);
					applyPose(thrallApproachV > RUN_SPEED * 0.6f ? POSE_RUN : POSE_WALK);
				}
				place(new LocalPoint(Math.round(ghostX), Math.round(ghostY)), plane);
				prevThrallX = tp.getX();
				prevThrallY = tp.getY();
				return;
			}
			thrallAttached = true;
			thrallApproachV = 0f;
			prevThrallX = tp.getX();
			prevThrallY = tp.getY();
			thrallSpeed = 0f;
		}

		// Pose from the thrall's own movement speed.
		float moved = (float) Math.hypot(tp.getX() - prevThrallX, tp.getY() - prevThrallY);
		prevThrallX = tp.getX();
		prevThrallY = tp.getY();
		thrallSpeed += (moved / dt - thrallSpeed) * Math.min(1f, dt / 100f);

		if (thrallSpeed > 0.02f)
		{
			applyPose(thrallSpeed > RUN_SPEED * 0.7f ? POSE_RUN : POSE_WALK);
		}
		else
		{
			applyPose(POSE_IDLE);
		}

		ghostX = tp.getX();
		ghostY = tp.getY();
		int facing = thrall.getCurrentOrientation();
		ghost.setOrientation(facing);

		float ox = 0f;
		float oy = 0f;
		if (lungeMs > 0f)
		{
			lungeMs = Math.max(0f, lungeMs - dt);
			float k = (float) Math.sin((1f - lungeMs / LUNGE_MS) * Math.PI) * LUNGE_DIST;
			double rad = facing * Math.PI / 1024.0;
			ox = (float) -Math.sin(rad) * k;
			oy = (float) -Math.cos(rad) * k;
		}

		place(new LocalPoint(Math.round(ghostX + ox), Math.round(ghostY + oy)), plane);
	}

	/**
	 * True when this freshly-spawned thrall can only be yours: it materialised
	 * right on top of you and no other player is as close to it. A stranger's
	 * thrall appears beside THEM, so this is a safe stand-in for the varbit
	 * during the tick or two before the varbit is set.
	 */
	private boolean spawnedOnMe(NPC npc, Player me)
	{
		int d = npc.getWorldLocation().distanceTo(me.getWorldLocation());
		if (d > 1)
		{
			return false;
		}
		for (Player p : client.getPlayers())
		{
			if (p == null || p == me)
			{
				continue;
			}
			if (p.getWorldLocation().distanceTo(npc.getWorldLocation()) <= d)
			{
				return false;
			}
		}
		return true;
	}

	/** Thrall done for good (expired/toggled off): jog back to the player's side. */
	private void endThrall()
	{
		thrallProvisionalUntil = 0L;
		thrall = null;
		thrallAttached = false;
		thrallSpeed = 0f;
		lungeMs = 0f;
		lastThrallProjectile = null;
		docking = false;
		impersonating = false;
		thrallLostTicks = 0;
		if (ghost != null)
		{
			// If the summon died way out of sight, the ghost is stranded far
			// behind — repark behind you (like a teleport-in) instead of
			// sprinting it across half the map.
			Player owner = client.getLocalPlayer();
			LocalPoint pl = owner != null ? owner.getLocalLocation() : null;
			if (pl == null
				|| Math.hypot(pl.getX() - ghostX, pl.getY() - ghostY) > 20 * Perspective.LOCAL_TILE_SIZE)
			{
				reparkAfterTeleport();
			}
			else
			{
				reseedFromGhost();
			}
		}
	}

	/**
	 * After a scene reload the thrall NPC is re-indexed; re-find it near the
	 * player so impersonation survives teleports/region changes. If it's no
	 * longer around it may just be a render blip, so keep impersonating and
	 * let the per-tick re-acquire (or timeout) handle it.
	 */
	private void reacquireThrall(Player me)
	{
		if (!config.thrallMode())
		{
			endThrall();
			return;
		}
		NPC t = findNearbyThrall(me, THRALL_REACQUIRE_RADIUS);
		if (t != null)
		{
			thrall = t;
			thrallAttached = false;
			lungeMs = 0f;
			thrallLostTicks = 0;
			// No deadline re-arm: same still-alive summon, same expiry.
			log.debug("Re-acquired thrall id={} after scene load", t.getId());
		}
	}

	/**
	 * Latest game tick this summon could still be alive: thralls last your
	 * Magic level in seconds (level * 5/3 ticks), plus a small buffer.
	 * Re-armed on every bind — an overestimate only delays the fallback
	 * release, never hides anything longer than THRALL_REACQUIRE_TICKS.
	 */
	private void armThrallDeadline()
	{
		int lvl = Math.max(1, client.getBoostedSkillLevel(net.runelite.api.Skill.MAGIC));
		thrallDeadlineTick = client.getTickCount() + lvl * 5 / 3 + 10;
	}

	/** Nearest tracked-type thrall within the given tile radius, or null. */
	private NPC findNearbyThrall(Player me, int radius)
	{
		// Only YOUR thrall — no summon active, nothing to find. This is what
		// keeps the re-acquire path from latching onto a stranger's thrall.
		if (client.getVarbitValue(Varbits.RESURRECT_THRALL) == 0)
		{
			return null;
		}
		NPC best = null;
		int bestDist = Integer.MAX_VALUE;
		for (NPC npc : client.getNpcs())
		{
			if (!THRALL_IDS.contains(npc.getId()))
			{
				continue;
			}
			int d = npc.getWorldLocation().distanceTo(me.getWorldLocation());
			if (d <= radius && d < bestDist)
			{
				bestDist = d;
				best = npc;
			}
		}
		return best;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned e)
	{
		tryAdoptThrall(e.getNpc());
	}

	/**
	 * An NPC can also turn INTO a thrall in place (a definition change, not a
	 * fresh spawn), which never fires NpcSpawned with a thrall id. Treat that
	 * exactly like a spawn so the summon can't slip past unhidden.
	 */
	@Subscribe
	public void onNpcChanged(NpcChanged e)
	{
		tryAdoptThrall(e.getNpc());
	}

	/** Start impersonating this NPC if it is a thrall that is (or must be) yours. */
	private void tryAdoptThrall(NPC npc)
	{
		if (!config.thrallMode() || thrall != null || npc == null)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		if (!THRALL_IDS.contains(npc.getId()))
		{
			return;
		}
		// ONLY your own thrall. Without a check the pet happily adopted a
		// passing player's thrall (and then played its attack animation on
		// every one of THEIR hits). The varbit is 0 unless you have a summon
		// out, so a stranger's thrall is rejected. It can lag the spawn on a
		// fresh cast, though, and that gap is the real thrall standing there
		// in plain sight - so a spawn that is unmistakably yours (right on
		// top of you, nobody else nearer) is adopted PROVISIONALLY and the
		// tick check confirms it or hands it back once the varbit catches up.
		boolean confirmed = client.getVarbitValue(Varbits.RESURRECT_THRALL) != 0;
		if (!confirmed && !spawnedOnMe(npc, me))
		{
			return;
		}
		// On first cast a thrall materializes right next to its caster, so a
		// tight radius avoids grabbing another player's thrall. When we're
		// re-acquiring one we already know is ours, accept it anywhere in
		// render range so it snaps back instantly on re-entering the scene.
		int radius = impersonating ? THRALL_REACQUIRE_RADIUS : THRALL_ACQUIRE_RADIUS;
		int dist = npc.getWorldLocation().distanceTo(me.getWorldLocation());
		if (dist > radius)
		{
			log.debug("Ignoring thrall {} spawned {} tiles away", npc.getId(), dist);
			return;
		}
		log.debug("Tracking thrall id={} at distance {} (impersonating={})", npc.getId(), dist, impersonating);
		// Unconfirmed adoptions get a short leash (see onGameTick).
		thrallProvisionalUntil = confirmed ? 0L
			: System.currentTimeMillis() + THRALL_CONFIRM_MS;
		boolean freshCast = !impersonating;
		thrall = npc;
		thrallAttached = false;
		lungeMs = 0f;
		docking = false;
		impersonating = true;
		thrallLostTicks = 0;
		// Only a FRESH cast starts a new lifetime; a stranded thrall
		// re-entering render range keeps the deadline from its cast.
		if (freshCast)
		{
			armThrallDeadline();
		}
		// Stand in NOW, not on the next game tick: if the pet had been handed
		// back (you were standing still) there is no ghost yet, and until one
		// exists the real thrall can't be hidden.
		if (pet != null && (!hidingReal || ghost == null))
		{
			hidingReal = true;
			spawnGhost(me);
		}
	}

	/**
	 * Thrall attack: play the pet's own attack animation on the hidden pet
	 * (the ghost mirrors it), falling back to a lunge for pets without one.
	 * Note: magic thralls sometimes attack with no animation (projectile
	 * only), so ghostly thrall attacks may not always trigger this.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged e)
	{
		// Melee (zombified) and ranged (skeletal) thralls animate on attack.
		if (thrall != null && e.getActor() == thrall && thrall.getAnimation() != -1)
		{
			triggerPetAttack();
		}
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved e)
	{
		// Everything downstream (attack anim, bolt tint, splash tint, the
		// damage icon) is pet flavor — a bare thrall fighting as itself
		// keeps its own colors and gets no icon.
		if (thrall == null || ghost == null)
		{
			return;
		}
		Projectile pr = e.getProjectile();
		// React the moment the projectile is REGISTERED (cast time), not when
		// it launches: the server creates it with startCycle a few cycles in
		// the future, and that gap is the caster's wind-up. Waiting for
		// startCycle == gameCycle (the old check) meant the bolt was already
		// flying before the pet began its swing. The event re-fires every
		// cycle the projectile exists, so dedupe by identity; the startCycle
		// bound rejects mid-flight projectiles that drifted over the tile.
		if (pr == lastThrallProjectile || pr.getStartCycle() < client.getGameCycle())
		{
			return;
		}
		LocalPoint tl = thrall.getLocalLocation();
		if (tl == null
			|| Math.abs(pr.getX1() - tl.getX()) > 64
			|| Math.abs(pr.getY1() - tl.getY()) > 64)
		{
			return;
		}

		lastThrallProjectile = pr;
		log.debug("Thrall projectile id={} start={} end={} now={}",
			pr.getId(), pr.getStartCycle(), pr.getEndCycle(), client.getGameCycle());
		if (!thrallAttached)
		{
			// The pet hasn't reached the thrall's spot yet, so this bolt
			// would fire out of thin air at the hidden thrall's tile. A
			// projectile can't be MOVED (read-only API), but a past end
			// cycle is the documented way to remove one — so suppress the
			// stray bolt and hand its landing straight to the splash and
			// damage-icon pipeline with the ORIGINAL end cycle, keeping
			// attribution intact. The pet still stops and plays its attack,
			// and the victim's impact spotanim is server-side regardless.
			boolean claimed = claimedBolts.remove(pr);
			Actor victim = pr.getTargetActor();
			if (victim != null && splashTints.size() < 16)
			{
				splashTints.add(new SplashTint(victim, pr.getEndCycle(), claimed));
			}
			// NEVER mutate the projectile here: ProjectileMoved fires while
			// the engine is mid-update on this very projectile, and writing
			// a past end cycle at that moment poisoned its animation math
			// (hard client crash, frame index in the millions). Queue it;
			// the removal happens between engine passes.
			if (pendingBoltKills.size() < 16)
			{
				pendingBoltKills.add(pr);
			}
		}
		else
		{
			// Track regardless of the tint toggle: the flight's landing
			// cycle also attributes hitsplats for the pet damage icon.
			tintedBolts.add(pr);
		}
		triggerPetAttack();
	}

	/**
	 * The thrall attacked: play the pet's own attack animation on the hidden
	 * pet (the mirrored model reflects it over the movement pose), or lunge
	 * for pets that have no attack animation.
	 */
	private void triggerPetAttack()
	{
		if (pet == null || ghost == null)
		{
			return;
		}
		// One trigger per cast: a thrall that animates fires BOTH paths —
		// onAnimationChanged at cast, then the projectile at launch — and
		// the second call restarted the pet's attack animation mid-swing.
		// First signal wins. The window must beat the LONGEST anim-to-launch
		// gap: the skeletal thrall's arrow launches well over 900 ms after
		// its draw animation (the ghostly bolt is much quicker), which is
		// why the pet repeated its swing on skeleton casts only. Thralls
		// attack every 4 ticks (2400 ms), so 1800 ms cannot eat a real cast.
		long now = System.currentTimeMillis();
		if (now - lastPetAttackMs < 1800)
		{
			return;
		}
		lastPetAttackMs = now;
		int atkId = previewing ? activePreviewId : pet.getId();
		NPCComposition comp = previewing
			? client.getNpcDefinition(activePreviewId)
			: pet.getTransformedComposition();
		String name = comp != null ? comp.getName() : null;
		int atk = PetAttackAnims.forPet(atkId, name);
		log.debug("Thrall attack -> pet id={} name={} atk={}", atkId, name, atk);
		if (atk == -1)
		{
			lungeMs = LUNGE_MS;
		}
		else if (previewing && blipActive && blipObj != null)
		{
			// Preview renders through the stand-in: play the attack there
			// and hold off pose updates until it has had time to finish.
			blipObj.setAnimation(client.loadAnimation(atk));
			blipAnimId = -1;
			blipAttackUntil = System.currentTimeMillis() + 900;
		}
		else
		{
			pet.setAnimation(atk);
			pet.setAnimationFrame(0);
		}
	}

	// ------------------------------------------------------------------
	// Thrall projectile tint
	// ------------------------------------------------------------------

	/**
	 * Repaint each tracked projectile's live posed model to the config
	 * color, every rendered frame. The engine flies, animates, and draws
	 * its own bolt; we only touch the face colors of the model it is about
	 * to render. Reapplying is idempotent (hue/saturation are overwritten,
	 * luminance is preserved), so it doesn't matter whether the engine
	 * hands back a cached posed model or a freshly built one.
	 */
	private void updateTintedBolts()
	{
		if (tintedBolts.isEmpty() && splashTints.isEmpty())
		{
			return;
		}
		int cycle = client.getGameCycle();
		// Painting is gated on the toggle; flight/impact TRACKING is not,
		// because the pet damage icon attributes hitsplats from it.
		boolean paint = config.tintThrallBolt() && !tintFailed;
		short target = JagexColor.rgbToHSL(config.thrallBoltColor().getRGB(), 1.0d);
		int hue = JagexColor.unpackHue(target);
		int sat = JagexColor.unpackSaturation(target);
		int lum = JagexColor.unpackLuminance(target);
		// How achromatic the target is (black/grey/white have sat 0). For
		// those, hue carries nothing — the LUMINANCE is the color, so blend
		// the model's brightness toward it (scaled by its own shading).
		// Fully saturated picks keep the original luminance untouched,
		// which is the look that already read well.
		float achroma = 1f - sat / (float) JagexColor.SATURATION_MAX;
		try
		{
			for (Iterator<Projectile> it = tintedBolts.iterator(); it.hasNext(); )
			{
				Projectile pr = it.next();
				if (cycle >= pr.getEndCycle())
				{
					// Landing: the spotanim that starts on the victim at
					// this cycle is our impact splash — tint it too. The
					// hit-claim carries over from the in-flight phase.
					boolean claimed = claimedBolts.remove(pr);
					Actor victim = pr.getTargetActor();
					if (victim != null && splashTints.size() < 16)
					{
						splashTints.add(new SplashTint(victim, pr.getEndCycle(), claimed));
					}
					it.remove();
					continue;
				}
				Model m = paint ? pr.getModel() : null;
				if (m != null)
				{
					tintModel(m, hue, sat, lum, achroma);
				}
			}
			for (Iterator<SplashTint> it = splashTints.iterator(); it.hasNext(); )
			{
				SplashTint st = it.next();
				if (cycle > st.impactCycle + 250)
				{
					it.remove(); // splash long over (5 s hard cap)
					continue;
				}
				if (!paint)
				{
					continue;
				}
				for (ActorSpotAnim sa : st.target.getSpotAnims())
				{
					if (Math.abs(sa.getStartCycle() - st.impactCycle) <= 4)
					{
						Model m = sa.getModel();
						if (m != null)
						{
							tintModel(m, hue, sat, lum, achroma);
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			tintFailed = true;
			clearTintedBolts();
			log.debug("Thrall bolt tint disabled", ex);
		}
	}

	/**
	 * Move every face color's hue and saturation to the target while
	 * keeping its luminance (the shading) — the bolt keeps its exact shape,
	 * animation, and shading, just in the new color. Face-color conventions
	 * from the engine: faceColors3 == -2 means the face is hidden, -1 means
	 * flat shading (only faceColors1 is used). Idempotent, so per-frame
	 * reapplication is safe. Originals are snapshotted for restore.
	 */
	/** Apply the configured thrall-bolt tint to one projectile's model, now. */
	private void tintBoltNow(Projectile pr)
	{
		if (!config.tintThrallBolt() || tintFailed || pr == null)
		{
			return;
		}
		Model m = pr.getModel();
		if (m == null)
		{
			return;
		}
		short target = JagexColor.rgbToHSL(config.thrallBoltColor().getRGB(), 1.0d);
		int sat = JagexColor.unpackSaturation(target);
		float achroma = 1f - sat / (float) JagexColor.SATURATION_MAX;
		tintModel(m, JagexColor.unpackHue(target), sat,
			JagexColor.unpackLuminance(target), achroma);
	}

	private void tintModel(Model m, int hue, int sat, int lum, float achroma)
	{
		int[] c1 = m.getFaceColors1();
		int[] c2 = m.getFaceColors2();
		int[] c3 = m.getFaceColors3();
		// ALWAYS recompute from the snapshotted originals, never from the
		// current (already-tinted) colors: the luminance blend is not
		// idempotent, so cumulative per-frame reapplication decays every
		// not-fully-saturated color to near-black within one flight.
		TintSnapshot snap = tintOriginals.get(c1);
		if (snap == null)
		{
			if (tintOriginals.size() >= 128)
			{
				return; // snapshot budget exhausted; leave this model alone
			}
			snap = new TintSnapshot(c1, c2, c3);
			tintOriginals.put(c1, snap);
		}
		for (int i = 0; i < c1.length; i++)
		{
			int f3 = snap.o3[i];
			if (f3 == -2)
			{
				continue;
			}
			c1[i] = tintHsl(snap.o1[i], hue, sat, lum, achroma);
			if (f3 != -1)
			{
				c2[i] = tintHsl(snap.o2[i], hue, sat, lum, achroma);
				c3[i] = tintHsl(f3, hue, sat, lum, achroma);
			}
		}
	}

	/** One packed HSL value re-hued; see tintModel for the luminance rule. */
	private static int tintHsl(int hsl, int hue, int sat, int lum, float achroma)
	{
		int lo = JagexColor.unpackLuminance((short) hsl);
		if (achroma > 0f)
		{
			// Target luminance carrying the model's own shading pattern.
			int scaled = Math.min(JagexColor.LUMINANCE_MAX, lum * lo / 96);
			lo = Math.round(lo * (1f - achroma) + scaled * achroma);
		}
		return JagexColor.packHSL(hue, sat, lo) & 0xFFFF;
	}

	/** Un-tint every repainted model and stop tracking bolts and splashes. */
	private void clearTintedBolts()
	{
		for (TintSnapshot s : tintOriginals.values())
		{
			System.arraycopy(s.o1, 0, s.a1, 0, s.o1.length);
			System.arraycopy(s.o2, 0, s.a2, 0, s.o2.length);
			System.arraycopy(s.o3, 0, s.a3, 0, s.o3.length);
		}
		tintOriginals.clear();
		tintedBolts.clear();
		claimedBolts.clear();
		pendingBoltKills.clear();
		splashTints.clear();
		petHits.clear();
	}

	// ------------------------------------------------------------------
	// Pet damage icon
	// ------------------------------------------------------------------

	/**
	 * A hitsplat landing on a tracked projectile's victim within ~0.7 s of
	 * the landing cycle is the pet's damage. (The player hitting the same
	 * target in that same instant would also match — cosmetic and rare.)
	 */
	/**
	 * DPS tracking: convert HITPOINTS xp drops into damage. dmg = xp * 0.75 /
	 * modifier, where the per-NPC modifier corrects for monsters that grant
	 * bonus xp (wiki-derived table). A fight session ends when the overhead
	 * display fades out after combat (see dpsSessionEnded).
	 */
	/** Combat skills (their XP trails a fight); everything else = skilling. */
	private static boolean isCombatXpSkill(Skill s)
	{
		switch (s)
		{
			case ATTACK:
			case STRENGTH:
			case DEFENCE:
			case RANGED:
			case MAGIC:
			case HITPOINTS:
			case SLAYER:
				return true;
			default:
				return false;
		}
	}

	/** True if this skill is one of the XP/hr lock slots (LOCKED mode). */
	private boolean isLockedXpSkill(Skill s)
	{
		if (s == null || config.xpHrMode() != XpHrMode.LOCKED)
		{
			return false;
		}
		return config.xpHrSkill1().skill() == s
			|| config.xpHrSkill2().skill() == s
			|| config.xpHrSkill3().skill() == s;
	}

	/** Idle gap (ms) after which a skill's XP/hr session resets. */
	private long xpResetMs(Skill s)
	{
		// A pinned skill gets its OWN reset timer, kept apart from the auto
		// combat/skilling ones.
		if (isLockedXpSkill(s))
		{
			return config.xpResetLockedMins() * 60000L;
		}
		int mins = isCombatXpSkill(s)
			? config.xpResetCombatMins() : config.xpResetSkillingMins();
		return mins * 60000L;
	}

	/** A skill's session counts for display: started, and gained in the last 12s. */
	private boolean xpSessionLive(Skill s)
	{
		long[] sess = s != null ? xpSessions.get(s) : null;
		return sess != null && sess[1] != 0L
			&& System.currentTimeMillis() - sess[3] < 12000;
	}

	/**
	 * Which skills the XP/hr readout should show right now, in display order.
	 * CURRENT mode follows whatever you're actively training; LOCKED mode
	 * shows only the chosen slots (one line each — that's the multiskilling
	 * case). Either way a skill only appears while its session is live.
	 */
	private java.util.List<Skill> xpDisplaySkills()
	{
		java.util.List<Skill> out = new java.util.ArrayList<>(3);
		if (config.xpHrMode() == XpHrMode.LOCKED)
		{
			for (TrackedSkill ts : new TrackedSkill[]{
				config.xpHrSkill1(), config.xpHrSkill2(), config.xpHrSkill3()})
			{
				Skill s = ts.skill();
				if (s != null && !out.contains(s) && xpSessionLive(s))
				{
					out.add(s);
				}
			}
		}
		else if (xpSessionLive(xpActiveSkill))
		{
			out.add(xpActiveSkill);
		}
		return out;
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		// --- XP/hr bookkeeping (every skill) --------------------------
		// First sighting of a skill is the login baseline, not a gain; a
		// idle past the reset window (below) starts a fresh session.
		long xnow = System.currentTimeMillis();
		// sess = {startXp, startMs, lastXp, lastMs}. startMs == 0 is the
		// sentinel for "seen but not started" — a baseline sighting whose xp
		// we record but don't yet count from.
		long[] sess = xpSessions.get(e.getSkill());
		if (sess == null)
		{
			// First ever sighting is just the baseline; the session opens on
			// the next real gain (startMs stays 0 until then).
			xpSessions.put(e.getSkill(),
				new long[]{e.getXp(), 0L, e.getXp(), xnow});
		}
		else if (e.getXp() > sess[2])
		{
			// Idle past the skill's reset window (5 min combat / 10 min
			// skilling by default) ends the session so the downtime doesn't
			// drag the rate; the resume below re-opens it fresh.
			boolean idleReset = xnow - sess[3] > xpResetMs(e.getSkill());
			if (sess[1] == 0L || idleReset)
			{
				// This gain OPENS the session: baseline = the CURRENT xp, so
				// gained is 0 right now and grows only from here, and the clock
				// starts now. Seeding the baseline to the current value is what
				// makes the rate start at 0 and ramp up — the old code left the
				// baseline behind and started the clock at the same instant the
				// xp jumped, dividing a real delta by ~0 elapsed. THAT was the
				// spike (worst right after a teleport re-armed the reset).
				sess[0] = e.getXp();
				sess[1] = xnow;
			}
			sess[2] = e.getXp();
			sess[3] = xnow;
			lastXpGainMs = xnow;
			// Hitpoints trails every combat style — show the style itself
			// unless HP is genuinely all that's training.
			if (e.getSkill() != Skill.HITPOINTS)
			{
				xpActiveSkill = e.getSkill();
			}
			else if (xpActiveSkill == null)
			{
				xpActiveSkill = Skill.HITPOINTS;
			}
		}

		if (e.getSkill() != Skill.HITPOINTS)
		{
			return;
		}
		int xp = e.getXp();
		if (lastHpXp < 0)
		{
			lastHpXp = xp;
			return;
		}
		int diff = (int) (xp - lastHpXp);
		lastHpXp = xp;
		// No legit single hit grants thousands of hp xp — a huge delta is a
		// stale baseline (login, world hop), not damage.
		if (diff <= 0 || diff > 2000)
		{
			return;
		}
		ensureXpBonusMap();
		double modifier = 1.0;
		Actor t = combatTarget != null ? combatTarget.get() : null;
		if (t instanceof NPC)
		{
			Double m = xpBonusMap.get(((NPC) t).getId());
			if (m != null)
			{
				modifier = m;
			}
		}
		int damage = (int) Math.round(diff * 0.75 / modifier);
		if (damage <= 0)
		{
			return;
		}
		long now = System.currentTimeMillis();
		// New target = new session. The clock starts at ENGAGEMENT
		// (pre-armed above) when that's recent, so time spent winding up
		// the first hit counts.
		Actor cur = dpsTarget != null ? dpsTarget.get() : null;
		if (t instanceof NPC && t != cur)
		{
			// Continuous mode: while damage keeps flowing, a new target just
			// carries the running session on — kills chain, and the live
			// clock prices the switch-over seconds as downtime. This is what
			// makes barrage work: 5-tick casts drop xp every 3.0s while the
			// nominal target churns across the pack. Only a real lull (the
			// disengaged-gap reset below) starts a fresh session.
			if (config.dpsSession() == DpsSessionMode.CONTINUOUS
				&& fightDamage > 0 && now - lastDmgMs < 5000)
			{
				fightDamage += damage;
				lastDmgMs = now;
				dpsTarget = new java.lang.ref.WeakReference<>(t);
				return;
			}
			// A kill shot's xp can land AFTER you've already clicked the
			// next mob — credit a drop this close on the heels of the last
			// one to the OUTGOING fight, instead of seeding the new session
			// with it (that seed was the brief high spike, and the live
			// clock slumping it a second later, on every crab switch).
			if (fightDamage > 0 && now - lastDmgMs < 2500)
			{
				fightDamage += damage;
				lastDmgMs = now;
				return;
			}
			fightDamage = 0;
			fightStartMs = dpsPending != null && dpsPending.get() == t
				&& now - dpsPendingMs < 10000 ? dpsPendingMs : now;
			dpsTarget = new java.lang.ref.WeakReference<>(t);
		}
		else if (dpsSessionEnded)
		{
			// A session now ends in exactly ONE place: the overhead display
			// fading out when you leave combat. The old rule (an 8s gap while
			// not interacting with the target) is what randomly bottomed the
			// number out - a cannon does your damage for you while you stand
			// there interacting with nothing, so every wait for the next
			// spawn looked like a disengage and wiped the fight. Slow,
			// inaccurate weapons that miss for 8s+ had the same problem.
			fightDamage = 0;
			fightStartMs = now;
		}
		dpsSessionEnded = false;
		fightDamage += damage;
		lastDmgMs = now;

		// Whole-login accumulator: every point of damage, over all fights, for
		// the lifetime-average mode. Tracked only while that mode is on.
		if (config.dpsSession() == DpsSessionMode.WHOLE_SESSION)
		{
			if (sessionStartMs == 0)
			{
				sessionStartMs = now;
			}
			sessionDamage += damage;
		}
	}

	/** Lazy-load the npc-id → xp-bonus-modifier table (34KB json resource). */
	private void ensureXpBonusMap()
	{
		if (xpBonusLoaded)
		{
			return;
		}
		xpBonusLoaded = true;
		try (java.io.InputStream in = PetFollowerPlugin.class.getResourceAsStream("npcs.min.json"))
		{
			if (in == null)
			{
				return;
			}
			com.google.gson.JsonObject root = gson.fromJson(
				new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			for (Map.Entry<String, com.google.gson.JsonElement> en : root.entrySet())
			{
				double bonus = en.getValue().getAsJsonObject().get("xpbonus").getAsDouble();
				xpBonusMap.put(Integer.parseInt(en.getKey()), (bonus + 100) / 100.0);
			}
		}
		catch (Exception ex)
		{
			log.debug("xp bonus table load failed", ex); // DPS just runs at 1.0
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		// Kills/hr: count an NPC death as your kill when it's the target you
		// were fighting and dealing damage to. Clock resets after the same idle
		// gap as the combat XP session so a break doesn't drag the rate.
		if (!(e.getActor() instanceof NPC))
		{
			return;
		}
		Actor dt = dpsTarget != null ? dpsTarget.get() : null;
		Actor ct = combatTarget != null ? combatTarget.get() : null;
		if ((e.getActor() == dt || e.getActor() == ct) && fightDamage > 0)
		{
			long now = System.currentTimeMillis();
			long reset = config.xpResetCombatMins() * 60000L;
			if (killStartMs == 0 || now - killLastMs > reset)
			{
				killCount = 0;
				killStartMs = now;
			}
			killCount++;
			killLastMs = now;
		}
	}

	/** OSRS prayer drain effect per prayer (unknown/newer prayers default 12). */
	private static int prayerDrainEffect(Prayer p)
	{
		switch (p)
		{
			case RAPID_RESTORE:
				return 1;
			case PRESERVE:
				return 2;
			case THICK_SKIN:
			case BURST_OF_STRENGTH:
			case CLARITY_OF_THOUGHT:
			case SHARP_EYE:
			case MYSTIC_WILL:
			case RAPID_HEAL:
			case PROTECT_ITEM:
			case RETRIBUTION:
				return 3;
			case ROCK_SKIN:
			case SUPERHUMAN_STRENGTH:
			case IMPROVED_REFLEXES:
			case HAWK_EYE:
			case MYSTIC_LORE:
			case REDEMPTION:
				return 6;
			case STEEL_SKIN:
			case ULTIMATE_STRENGTH:
			case INCREDIBLE_REFLEXES:
			case PROTECT_FROM_MAGIC:
			case PROTECT_FROM_MISSILES:
			case PROTECT_FROM_MELEE:
			case EAGLE_EYE:
			case MYSTIC_MIGHT:
				return 12;
			case SMITE:
				return 18;
			case CHIVALRY:
			case PIETY:
			case RIGOUR:
			case AUGURY:
				return 24;
			default:
				return 12; // newer prayers (Deadeye/Mystic Vigour/Ruinous): approx
		}
	}

	/** Sum of drain effects of all currently active prayers. */
	private int totalPrayerDrain()
	{
		int total = 0;
		for (Prayer p : Prayer.values())
		{
			if (client.isPrayerActive(p))
			{
				total += prayerDrainEffect(p);
			}
		}
		return total;
	}

	/** Total prayer bonus from worn equipment (cached, refreshed on tick). */
	private int computePrayerBonus()
	{
		ItemContainer eq = client.getItemContainer(InventoryID.EQUIPMENT);
		if (eq == null)
		{
			return 0;
		}
		int bonus = 0;
		for (Item it : eq.getItems())
		{
			if (it == null || it.getId() < 0)
			{
				continue;
			}
			ItemStats st = itemManager.getItemStats(it.getId());
			if (st != null && st.getEquipment() != null)
			{
				bonus += st.getEquipment().getPrayer();
			}
		}
		return bonus;
	}

	/** Kills/hr right now, or -1 when the session is idle/empty. */
	private int killsPerHour()
	{
		long now = System.currentTimeMillis();
		if (killStartMs == 0 || killCount == 0
			|| now - killLastMs > config.xpResetCombatMins() * 60000L)
		{
			return -1;
		}
		// Count from the FIRST kill (excluding it) so the rate starts at 0, AND
		// hold the denominator at a 2-minute floor early on. Without the floor,
		// a second kill arriving 10 s after the first still extrapolated to
		// ~360/hr; the floor makes it climb from a low number and only becomes
		// the true elapsed time once the session is genuinely that old.
		float hours = Math.max(120000L, now - killStartMs) / 3600000f;
		return Math.round((killCount - 1) / hours);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		// Combat signals: taking a hit, or landing one on the NPC you're
		// interacting with (covers ranged/mage where the NPC hasn't retaliated
		// yet). This is why a red click that never trades damage — talk,
		// pickpocket, shoo — never trips wander mode.
		Player self = client.getLocalPlayer();
		if (e.getActor() == self)
		{
			// Taking a hit marks combat (vitals fade in, handoff holds) but
			// NOT offense — a mob chipping an idle player never sends the
			// pet off wandering.
			lastCombatMs = System.currentTimeMillis();
		}
		else if (self != null && e.getActor() == self.getInteracting()
			&& e.getActor() instanceof NPC)
		{
			lastCombatMs = System.currentTimeMillis();
			lastOffenseMs = lastCombatMs;
			combatTarget = new java.lang.ref.WeakReference<>(e.getActor());
			// Max-hit celebration: whenever you land a hit AT your session best
			// (a max roll or a new record) that's big enough to matter, the pet
			// plays its own attack animation. Firing on TIES too, not just new
			// records, is what keeps it going once your max plateaus - the old
			// records-only rule went quiet the moment you stopped beating it.
			// The animation also cues the hidden pet's attack SOUND, so the
			// toggle mutes both.
			if (config.maxHitCelebrate() && e.getHitsplat().isMine())
			{
				int amt = e.getHitsplat().getAmount();
				boolean atMax = amt >= sessionMaxHit;
				if (amt > sessionMaxHit)
				{
					sessionMaxHit = amt;
				}
				if (atMax && amt >= config.maxHitMin())
				{
					triggerPetAttack();
				}
			}
		}
		if (thrall == null && !impersonating && tintedBolts.isEmpty() && splashTints.isEmpty())
		{
			return;
		}
		// Slot bookkeeping for EVERY hitsplat on actors we might tag — the
		// player's own damage occupies slots too, and our icon's position
		// depends on which slot OUR hit ends up in.
		int cycle = client.getGameCycle();
		int[] slots = hitSlots.computeIfAbsent(e.getActor(), a -> new int[4]);
		int slot = -1;
		for (int i = 0; i < 4; i++)
		{
			if (slots[i] <= cycle)
			{
				slot = i;
				break;
			}
		}
		if (slot == -1)
		{
			slot = 0;
			for (int i = 1; i < 4; i++)
			{
				if (slots[i] < slots[slot])
				{
					slot = i;
				}
			}
		}
		slots[slot] = e.getHitsplat().getDisappearsOnGameCycle();

		if (!config.petHitIcon() || petIcon == null)
		{
			return;
		}
		if (e.getHitsplat().getAmount() > THRALL_MAX_HIT)
		{
			return; // can't be the thrall's damage
		}
		boolean ours = false;
		for (SplashTint st : splashTints)
		{
			if (!st.hitClaimed && st.target == e.getActor() && Math.abs(cycle - st.impactCycle) <= 35)
			{
				st.hitClaimed = true;
				ours = true;
				break;
			}
		}
		if (!ours)
		{
			for (Projectile pr : tintedBolts)
			{
				if (!claimedBolts.contains(pr) && pr.getTargetActor() == e.getActor()
					&& Math.abs(cycle - pr.getEndCycle()) <= 35)
				{
					claimedBolts.add(pr);
					ours = true;
					break;
				}
			}
		}
		if (ours && petHits.size() < 8)
		{
			// The icon lives and dies with its hitsplat, to the cycle.
			petHits.add(new PetHit(e.getActor(), e.getHitsplat().getDisappearsOnGameCycle(), slot));
		}
	}

	/**
	 * Resolve the displayed pet's inventory-item sprite (see the field
	 * comment for the matching rules). The one-time name scan runs on the
	 * client thread and is persisted per pet, misses included.
	 */
	private void resolvePetIcon(int npcId)
	{
		if (npcId == petIconKeyId)
		{
			return;
		}
		petIconKeyId = npcId;
		petIcon = null;
		Integer saved = configManager.getConfiguration("petfollower", "petItem_" + npcId, Integer.class);
		int itemId = saved != null ? saved : findPetItem(displayedPetName());
		if (saved == null)
		{
			configManager.setConfiguration("petfollower", "petItem_" + npcId, itemId);
		}
		if (itemId >= 0)
		{
			petIcon = itemManager.getImage(itemId);
		}
	}

	/** Scan item names for the pet's item: exact match, else longest contained. */
	private int findPetItem(String petName)
	{
		String want = petName.toLowerCase();
		int best = -1;
		int bestLen = 3; // ignore trivially short names
		// The live item count, not a hard-coded ceiling: newer pets' items sit
		// above the old 30,500 cutoff and were never found.
		int itemCount = client.getItemCount();
		int limit = itemCount > 0 ? itemCount : 30500;
		for (int i = 0; i < limit; i++)
		{
			try
			{
				ItemComposition ic = itemManager.getItemComposition(i);
				String n = ic != null ? ic.getName() : null;
				if (n == null || "null".equalsIgnoreCase(n))
				{
					continue;
				}
				if (n.equalsIgnoreCase(petName))
				{
					return i;
				}
				if (n.length() > bestLen && want.contains(n.toLowerCase()))
				{
					best = i;
					bestLen = n.length();
				}
			}
			catch (Exception ex)
			{
				// invalid id — skip
			}
		}
		log.debug("Pet icon for '{}' -> item {}", petName, best);
		return best;
	}

	/** Draws the pet icon beside its recent hitsplats. */
	private class PetHitOverlay extends Overlay
	{
		PetHitOverlay()
		{
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ABOVE_SCENE);
		}

		@Override
		public Dimension render(Graphics2D g)
		{
			if (petHits.isEmpty() || petIcon == null || !config.petHitIcon())
			{
				return null;
			}
			int cycle = client.getGameCycle();
			for (Iterator<PetHit> it = petHits.iterator(); it.hasNext(); )
			{
				PetHit ph = it.next();
				if (cycle >= ph.untilCycle)
				{
					it.remove();
					continue;
				}
				try
				{
					// Our hitsplat's rank among the ACTIVE slots gives how
					// many splats sit under it; the icon's midline lands on
					// that splat's midline (anchor minus rank spacings).
					int rank = 0;
					int[] slots = hitSlots.get(ph.target);
					if (slots != null)
					{
						for (int i = 0; i < ph.slot; i++)
						{
							if (slots[i] > cycle)
							{
								rank++;
							}
						}
					}
					net.runelite.api.Point p = ph.target.getCanvasImageLocation(
						petIcon, ph.target.getLogicalHeight() / 2);
					if (p != null)
					{
						int cx = p.getX() + petIcon.getWidth() / 2;
						int cy = p.getY() + petIcon.getHeight() / 2;
						int w = Math.max(8, config.petHitIconSize());
						int h = w * 22 / 26;
						g.drawImage(petIcon, cx + 12, cy - rank * HIT_SLOT_SPACING - h / 2, w, h, null);
					}
				}
				catch (Exception ex)
				{
					it.remove(); // actor gone mid-render
				}
			}
			return null;
		}
	}

	/**
	 * HP and Prayer readout for the pet: two short, wide bars stacked above the
	 * pet's head, plus a small crisp number beside its skills-tab icon pinned
	 * to the pet's lower-left (HP + heart) and lower-right (Prayer + icon).
	 * Shows only in combat and eases in/out (vitalsAlpha).
	 *
	 * The bars are drawn as plain rectangles scaled with the pet (never a
	 * scaled raster, so no blur), short and wide. The numbers use the SMALL
	 * RuneScape bitmap font at its native size, drawn 1:1 — always pixel-crisp
	 * at every zoom, the smallest legible size. Opacity, and the low-vitals
	 * blink, are a single alpha applied to the whole thing.
	 */
	private class PetVitalsOverlay extends Overlay
	{
		// Per-slot in-bar number caches (up to three configurable bars). The
		// old-buffer holds the previous SCALE for the zoom cross-fade.
		private final String[] barNumStr = new String[3];
		private final BufferedImage[] barNumBuf = new BufferedImage[3];
		private final BufferedImage[] barNumOld = new BufferedImage[3];
		// Max-hold pet height: getLogicalHeight() comes from the POSED model,
		// so the idle animation changes it every frame — feeding it straight
		// into the bar geometry made the whole display breathe and bob with
		// the pet. Hold the peak instead (tiny decay so a pet swap adapts).
		private float stableLogH;
		private int vitalsPetId = -1;
		// Dead-banded on-screen size: frozen until the projected size drifts
		// >5% (pet puttering around = no change), then eased to the new value.
		private float smoothPetPx;
		private boolean petPxChasing;
		// Integer text scale with hysteresis + a short cross-fade between
		// steps, so zooming glides through size changes instead of popping.
		private int textScale = 1;
		private long scaleSwapNanos;
		// Far-zoom fallback line (icon + current value under the pet).
		// Active is a hysteretic STATE, and the blend eases over TIME — at any
		// resting zoom the readout is fully in-bar or fully below, never
		// half-faded; the fade only plays during the actual switch.
		private boolean fbActive;
		private float fbBlend; // 0 = numbers in bars, 1 = line under pet
		// Zoomed-out bar values, cached per slot so the row doesn't rebuild
		// three pixel strings every frame while you're zoomed out.
		private final String[] fbRowStr = new String[3];
		private final BufferedImage[] fbRowBuf = new BufferedImage[3];
		// DPS readout cache.
		private String dpsStr;
		private BufferedImage dpsBuf;
		// Kills/hr readout cache.
		private String kphStr;
		private BufferedImage kphBuf;
		// Nametag cache.
		private String nameStr;
		private BufferedImage nameBuf;
		// Overhead speech (threshold shouts).
		private String overheadText;
		private long overheadUntilMs;
		private String overheadStr;
		private BufferedImage overheadBuf;
		// Spec-ready edge detector.
		private int prevSpecPct = -1;
		// Low-vitals RAISE window: crossing into low HP/Prayer brings the
		// display up for a bounded spell, rather than pinning it on the whole
		// time your prayer simply isn't full.
		private boolean prevLowRaise;
		private long warnRaiseUntilMs;
		// XP/hr readout cache, keyed per skill so several can show at once.
		private final java.util.Map<Skill, String> xpStrs =
			new java.util.EnumMap<>(Skill.class);
		private final java.util.Map<Skill, BufferedImage> xpBufs =
			new java.util.EnumMap<>(Skill.class);
		// Red-edged Attack sprite for the DPS row, cached by the height it was
		// built at (the outline is applied at DISPLAY size so it survives the
		// downscale that used to erase everything but the handle).
		private BufferedImage dpsIconBuf;
		private BufferedImage dpsIconSrc;
		private int dpsIconH = -1;
		// DPS trend state: a heavily-smoothed value to absorb per-hit variance,
		// a slowly-decaying session peak, and a slower reference the smoothed
		// value is compared against to read rising/falling.
		private float dpsSmooth;
		private float dpsPeak;
		private float dpsRef;
		// Bar change effects: a heal/restore powers UP (bright sweep), a hit
		// BLEEDS (dark-red recede), prayer drain TRICKLES. Edge-detected each
		// drawn frame; the *Until stamps hold each effect live for a spell
		// after the last change so a steady drain reads as a steady trickle.
		private int prevHpVal = -1;
		private int prevPrayVal = -1;
		private long hpUpUntil;
		private long hpDownUntil;
		private long prayUpUntil;
		private long prayDownUntil;
		// Smooth-sliding fill levels (eased toward the true fraction so the
		// line glides instead of jumping), plus the prayer "ghost" high-water
		// that lingers above the fill after a drain and eases down behind it.
		private float hpDisp = -1f;
		private float prayDisp = -1f;
		private float prayGhost;
		// Prayer drain for the bar's creep: the eased total drain effect, when
		// a prayer was last seen on (so flicking doesn't blank it), the sample
		// clock, and the resulting seconds per point.
		private float ptDrainEma;
		private long ptDrainHeldMs;
		private long ptCalcMs;
		private float praySecsPerPoint;
		// Fraction of the way to losing the NEXT prayer point, so the bar
		// edge creeps continuously instead of only moving on whole points.
		private float praySub;
		private int praySubLastPray = -1;
		private long praySubAnchorMs;
		private BufferedImage skullIconBuf;
		// The DISPLAYED dps (tenths), eased up from 0 at each fight's start so a
		// big opening hit doesn't read as a huge instantaneous rate that sags.
		private float dpsDisp;
		private long dpsDispSession;

		// Old-school readout palette: each stat wears its own colour so you can
		// read it by hue alone without parsing the number.
		private final Color TXT_HP = new Color(0, 255, 0);
		private final Color TXT_PRAY = new Color(0, 149, 221);
		private final Color TXT_XP = Color.WHITE;
		private final Color TXT_DPS = new Color(255, 0, 0);
		private final Color TXT_SPEC = new Color(200, 60, 220);

		/**
		 * The Attack sprite with a red edge burned around it, so the DPS
		 * readout reads as its own thing rather than "your Attack level".
		 *
		 * Built at the target DISPLAY height, not native res: the old version
		 * baked a 1px outline on the ~25px sprite and let the row scale it down
		 * to ~9px, which shrank the outline below a pixel everywhere except the
		 * thick handle. Scaling the sprite FIRST, then stamping the outline at
		 * that size, keeps the edge a true 1px at every zoom. Cached by height.
		 */
		private BufferedImage dpsIcon(int targetH)
		{
			if (attackIcon == null)
			{
				return null;
			}
			targetH = Math.max(6, targetH);
			if (dpsIconBuf != null && dpsIconSrc == attackIcon && dpsIconH == targetH)
			{
				return dpsIconBuf;
			}
			int sw = attackIcon.getWidth();
			int sh = attackIcon.getHeight();
			int w = Math.max(1, Math.round(targetH * sw / (float) sh));
			int h = targetH;
			// Downscale the sprite to display size first.
			BufferedImage scaled = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			Graphics2D gs = scaled.createGraphics();
			gs.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			gs.drawImage(attackIcon, 0, 0, w, h, null);
			gs.dispose();
			// Solid red stamp of that scaled silhouette.
			BufferedImage sil = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			int red = TXT_DPS.getRGB() & 0xFFFFFF;
			for (int y = 0; y < h; y++)
			{
				for (int x = 0; x < w; x++)
				{
					if ((scaled.getRGB(x, y) >>> 24) > 40)
					{
						sil.setRGB(x, y, 0xFF000000 | red);
					}
				}
			}
			// Stamp the silhouette in all 8 directions, sprite on top: the red
			// showing around the edge is a crisp 1px outline at THIS size.
			BufferedImage out = new BufferedImage(w + 2, h + 2, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g2 = out.createGraphics();
			for (int dx = 0; dx <= 2; dx++)
			{
				for (int dy = 0; dy <= 2; dy++)
				{
					if (dx != 1 || dy != 1)
					{
						g2.drawImage(sil, dx, dy, null);
					}
				}
			}
			g2.drawImage(scaled, 1, 1, null);
			g2.dispose();
			dpsIconSrc = attackIcon;
			dpsIconH = targetH;
			dpsIconBuf = out;
			return out;
		}

		/** Per-skill cached XP/hr micro-string (several skills can show at once). */
		private BufferedImage xpBufFor(Skill s, String rate, int scale)
		{
			String key = rate + "@" + scale;
			if (!key.equals(xpStrs.get(s)))
			{
				xpStrs.put(s, key);
				xpBufs.put(s, buildMicroString(rate, scale, TXT_XP));
			}
			return xpBufs.get(s);
		}

		/**
		 * Lay the readouts out as one horizontal row centred on the bar axis,
		 * spreading into the free space either side. Only when that row would
		 * run right off the pet does it wrap to a second line. Returns the
		 * height used, so the nametag above can clear it.
		 */
		private int drawTrackerCentered(Graphics2D g, java.util.List<Object[]> items,
			int barsX, int barsY, int barW, int stackH, int rowH, int gapV,
			boolean barsShown)
		{
			int n = items.size();
			if (n == 0)
			{
				return 0;
			}
			int gapH = 8;
			int[] w = new int[n];
			int total = gapH * (n - 1);
			for (int i = 0; i < n; i++)
			{
				w[i] = itemWidth(items.get(i), rowH);
				total += w[i];
			}
			// The bars are narrow when you're zoomed out, so the budget can't be
			// the bar width - that is exactly what stranded readouts off to the
			// sides. Allow a generous spread and only wrap past it.
			int budget = Math.max(170, barW * 5);
			int split = n;
			if (total > budget && n > 1)
			{
				int half = total / 2;
				int run = 0;
				for (int i = 0; i < n; i++)
				{
					run += w[i] + gapH;
					if (run >= half)
					{
						split = i + 1;
						break;
					}
				}
				split = Math.max(1, Math.min(n - 1, split));
			}
			int lines = split < n ? 2 : 1;
			int h = lines * rowH + (lines - 1) * gapV;
			int topY = !barsShown ? barsY + (stackH - h) / 2 : barsY - h - 3;
			int cx = barsX + barW / 2;
			if (lines == 2)
			{
				// Bar numbers come first in the list, so they take the LOWER
				// line - nearest the bars they belong to.
				drawRowSlice(g, items, w, split, n, cx, topY, rowH, gapH);
				drawRowSlice(g, items, w, 0, split, cx, topY + rowH + gapV, rowH, gapH);
			}
			else
			{
				drawRowSlice(g, items, w, 0, n, cx, topY, rowH, gapH);
			}
			return h;
		}

		/** Draw items[from, to) as one row centred on cx. */
		private void drawRowSlice(Graphics2D g, java.util.List<Object[]> items,
			int[] w, int from, int to, int cx, int y, int rowH, int gapH)
		{
			int total = 0;
			for (int i = from; i < to; i++)
			{
				total += w[i] + (i > from ? gapH : 0);
			}
			int x = cx - total / 2;
			for (int i = from; i < to; i++)
			{
				drawTrackerItem(g, items.get(i), x, y, rowH);
				x += w[i] + gapH;
			}
		}

		/** Put words over the pet's head for a while (pixel font). */
		void shout(String text, int ms)
		{
			overheadText = text;
			overheadUntilMs = System.currentTimeMillis() + ms;
		}

		/** Tiny skull for the kills/hr readout, same crisp pixel treatment. */
		private BufferedImage skullIcon(int h)
		{
			int scale = Math.max(1, Math.round(h / 7f));
			int size = 7 * scale + 2; // +2 for the 1px outline
			if (skullIconBuf != null && skullIconBuf.getHeight() == size)
			{
				return skullIconBuf;
			}
			// Domed cranium, two sunken eyes, a jaw with a tooth gap.
			final int[] rows = {
				0b0111110,
				0b1111111,
				0b1011101,
				0b1111111,
				0b0111110,
				0b0111110,
				0b0101010,
			};
			BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g2 = img.createGraphics();
			for (int pass = 0; pass < 2; pass++)
			{
				g2.setColor(pass == 0 ? Color.BLACK : C_DPS_AMBER);
				for (int r = 0; r < 7; r++)
				{
					for (int col = 0; col < 7; col++)
					{
						if (((rows[r] >> (6 - col)) & 1) == 0)
						{
							continue;
						}
						int px = 1 + col * scale;
						int py = 1 + r * scale;
						if (pass == 0)
						{
							g2.fillRect(px - 1, py, scale, scale);
							g2.fillRect(px + 1, py, scale, scale);
							g2.fillRect(px, py - 1, scale, scale);
							g2.fillRect(px, py + 1, scale, scale);
						}
						else
						{
							g2.fillRect(px, py, scale, scale);
						}
					}
				}
			}
			g2.dispose();
			skullIconBuf = img;
			return img;
		}

		/** 843 -> "843", 12840 -> "12K", 843200 -> "843K", 1240000 -> "1.2M". */
		private String formatXpRate(long r)
		{
			if (r >= 1000000)
			{
				long t = r / 100000;
				return t % 10 == 0 ? (t / 10) + "M" : (t / 10) + "." + (t % 10) + "M";
			}
			if (r >= 10000)
			{
				return (r / 1000) + "K";
			}
			if (r >= 1000)
			{
				long t = r / 100;
				return t % 10 == 0 ? (t / 10) + "K" : (t / 10) + "." + (t % 10) + "K";
			}
			return Long.toString(r);
		}

		PetVitalsOverlay()
		{
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ABOVE_SCENE);
		}

		@Override
		public Dimension render(Graphics2D g)
		{
			// Fade toward on-in-combat / off-otherwise every frame.
			long nn = System.nanoTime();
			float dt = vitalsLastNanos == 0 ? 16f : Math.min(120f, (nn - vitalsLastNanos) / 1_000_000f);
			vitalsLastNanos = nn;
			// The ghost is only ONE of the two things that can be on screen:
			// once it docks and hands back (standing still while skilling) the
			// REAL pet is what you see, and the readout has to ride that
			// instead of blinking out mid-session.
			boolean ghostDrawn = ghost != null && (ghostShown || blipActive);
			boolean realDrawn = pet != null && !hidingReal;
			boolean visible = config.petVitals()
				&& (ghostDrawn || realDrawn)
				&& client.getGameState() == GameState.LOGGED_IN;
			// Steady-state fast path: when there's nothing to show and the fade
			// is already spent (the default, since the display defaults OFF),
			// bail before the skill reads and list allocation below. Only the
			// brief fade-OUT transition needs the full compute.
			if (!visible && vitalsAlpha < 0.02f && xpAlpha < 0.02f)
			{
				vitalsAlpha = 0f;
				xpAlpha = 0f;
				prevHpWarn = false;
				prevPrayWarn = false;
				// Drop the change-effect baselines so re-appearing doesn't fire
				// a spurious heal/bleed off a stale value.
				prevHpVal = -1;
				prevPrayVal = -1;
				dpsSessionEnded = true;
				return null;
			}
			// Vitals + warn state, computed up front because low HP/Prayer is
			// itself a reason to raise the display (see want, below).
			int hp = client.getBoostedSkillLevel(Skill.HITPOINTS);
			int maxHp = client.getRealSkillLevel(Skill.HITPOINTS);
			int pray = client.getBoostedSkillLevel(Skill.PRAYER);
			int maxPray = client.getRealSkillLevel(Skill.PRAYER);
			boolean hpWarn = config.vitalsWarnings() && hp <= config.hpWarnLevel();
			boolean prayWarn = config.vitalsWarnings() && pray <= config.prayWarnLevel();
			boolean lowVitals = hpWarn || prayWarn;
			// Low vitals RAISE the display, but only for a bounded window on
			// each crossing — otherwise the bars never fade while your prayer
			// simply sits below full. Re-arms once you recover above the line.
			long nowV = System.currentTimeMillis();
			if (lowVitals && !prevLowRaise)
			{
				// Crossing a threshold ALERTS the pet: it holds the display up, and
			// (via petAlertUntilMs) breaks off wandering to come back to you.
			warnRaiseUntilMs = nowV + config.alertSecs() * 1000L;
			petAlertUntilMs = warnRaiseUntilMs;
			}
			prevLowRaise = lowVitals;
			boolean warnRaising = nowV < warnRaiseUntilMs;
			// Bars are COMBAT-only (plus that low-vitals raise); the XP/hr
			// readout rides its OWN fade so skilling shows the rate with no bar.
			// Engagement, not damage: a mob chipping you while you run past
			// shouldn't raise the display. lastOffenseMs only moves when YOU
			// square up (mutual targeting / your hit lands). Opt in to the
			// old "any hit shows it" with the config toggle. The linger after
			// combat is configurable and defaults long, so a whole fight of
			// move-hit-move keeps the display steady.
			long engagedMs = config.vitalsOnDamage() ? lastCombatMs : lastOffenseMs;
			long persistMs = Math.max(1000L, config.vitalsPersistSecs() * 1000L);
			boolean want = visible
				&& (nowV - engagedMs < persistMs || warnRaising);
			// Shown from the session's first drop, even while the rate still
			// reads 0 — the ramp from low is the point (see onStatChanged).
			java.util.List<Skill> xpSkills = xpDisplaySkills();
			boolean xpWant = visible && config.petXpHr() && !xpSkills.isEmpty();
			vitalsAlpha += ((want ? 1f : 0f) - vitalsAlpha) * Math.min(1f, dt / 500f);
			xpAlpha += ((xpWant ? 1f : 0f) - xpAlpha) * Math.min(1f, dt / 500f);
			if (vitalsAlpha < 0.02f && xpAlpha < 0.02f)
			{
				vitalsAlpha = 0f;
				xpAlpha = 0f;
				// Re-arm the call-outs so the next fight warns afresh.
				prevHpWarn = false;
				prevPrayWarn = false;
				// The bars are gone, so the DPS session is over. This is the
				// usual way out of a fight (XP/hr fades first), and returning
				// here without ending the session left it running forever: the
				// next fight inherited the old clock and read absurdly low.
				dpsSessionEnded = true;
				return null;
			}

			try
			{
				// hp/maxHp/pray/maxPray and the warn flags were computed above
				// (they also gate visibility). Only the fractions are display.
				float hpFrac = maxHp > 0 ? hp / (float) maxHp : 0f;
				// Reassigned below once the sub-point drain creep is known.
				float prayFrac = maxPray > 0 ? pray / (float) maxPray : 0f;

				// Edge-detect HP/Prayer changes to drive the bar effects. First
				// sighting (prev == -1) only seeds — no effect off a cold start.
				long nowFx = System.currentTimeMillis();
				if (prevHpVal >= 0)
				{
					if (hp > prevHpVal)
					{
						hpUpUntil = nowFx + BAR_FX_DUR;
					}
					else if (hp < prevHpVal)
					{
						hpDownUntil = nowFx + BAR_FX_DUR;
					}
				}
				if (prevPrayVal >= 0)
				{
					if (pray > prevPrayVal)
					{
						prayUpUntil = nowFx + BAR_FX_DUR;
					}
					else if (pray < prevPrayVal)
					{
						// Longer tail so a tick-by-tick drain reads as one
						// continuous trickle rather than separate blips.
						prayDownUntil = nowFx + PRAY_TRICKLE_DUR;
					}
				}
				prevHpVal = hp;
				prevPrayVal = pray;

				// Prayer drain rate, computed the RIGHT way (like the Prayer
				// plugin): from the ACTIVE prayers and your worn prayer bonus,
				// not measured off noisy point drops.
				//   seconds per point = 0.6 * (2*bonus + 60) / totalDrainEffect
				// It drives BOTH the time readout and the bar's creep, so it is
				// computed whenever the display is up - but throttled, because
				// walking the prayer varbits every frame is wasted work.
				long ptDt = nowFx - ptCalcMs;
				if (ptDt >= 200)
				{
					ptCalcMs = nowFx;
					int totalDrain = totalPrayerDrain();
					// Prayer FLICKING toggles prayers off and on constantly. Two
					// guards so nothing whips around: the rate is eased (~900ms)
					// rather than snapping when the active set changes, and a
					// brief all-off gap HOLDS the last rate instead of blanking.
					if (totalDrain > 0)
					{
						ptDrainHeldMs = nowFx;
						ptDrainEma = ptDrainEma <= 0f ? totalDrain
							: ptDrainEma + (totalDrain - ptDrainEma) * Math.min(1f, ptDt / 900f);
					}
					else if (nowFx - ptDrainHeldMs > 2500)
					{
						ptDrainEma = 0f; // genuinely stopped praying
					}
					praySecsPerPoint = ptDrainEma > 0.01f
						? 0.6f * (2 * prayerBonus + 60) / ptDrainEma : 0f;
				}
				boolean praying = praySecsPerPoint > 0.01f && pray > 0;
				// Sub-point creep. Prayer only ever ticks down a WHOLE point, so
				// the bar sat frozen for seconds at a time and never looked like
				// it was draining. Advance the fill edge across the gap at the
				// real rate; it resets each time a point actually goes.
				if (pray != praySubLastPray)
				{
					praySubLastPray = pray;
					praySubAnchorMs = nowFx;
					praySub = 0f;
				}
				praySub = praying
					? Math.min(0.95f, (nowFx - praySubAnchorMs) / 1000f / praySecsPerPoint)
					: 0f;
				prayFrac = maxPray > 0
					? Math.max(0f, pray - praySub) / (float) maxPray : 0f;

				// Smooth-slide the fills toward their true level so the line
				// glides continuously (no per-tick jump). The prayer ghost is a
				// high-water mark: it snaps up to the fill, then lags DOWN behind
				// it after a drain to leave a fading trail of what was lost.
				if (hpDisp < 0f)
				{
					hpDisp = hpFrac;
				}
				else
				{
					hpDisp += (hpFrac - hpDisp) * Math.min(1f, dt / 200f);
				}
				if (prayDisp < 0f)
				{
					prayDisp = prayFrac;
				}
				else
				{
					prayDisp += (prayFrac - prayDisp) * Math.min(1f, dt / 200f);
				}
				if (prayFrac >= prayGhost)
				{
					prayGhost = prayFrac;
				}
				else
				{
					prayGhost += (prayFrac - prayGhost) * Math.min(1f, dt / 750f);
				}

				// The blink runs for a configurable time after CROSSING a
				// threshold, then settles to steady — a whole fight at low
				// prayer shouldn't strobe forever.
				long nowMs = System.currentTimeMillis();
				if (hpWarn && !prevHpWarn)
				{
					hpWarnStartMs = nowMs;
				}
				if (prayWarn && !prevPrayWarn)
				{
					prayWarnStartMs = nowMs;
				}
				long flashMs = config.warnFlashSecs() * 1000L;
				// Up to three configurable bars. Any of them may show any stat.
				BarStat[] barSlots = {
					config.topBarStat(), config.secondBarStat(), config.thirdBarStat()};
				boolean dpsBar = false;
				boolean hpIsBar = false;
				boolean prayIsBar = false;
				int nBars = 0;
				for (BarStat bs : barSlots)
				{
					if (bs == BarStat.OFF)
					{
						continue;
					}
					nBars++;
					dpsBar |= bs == BarStat.DPS;
					hpIsBar |= bs == BarStat.HITPOINTS;
					prayIsBar |= bs == BarStat.PRAYER;
				}
				int dpsTrend = 0;          // -1 falling, 0 steady, +1 rising
				boolean dpsNearPeak = false;
				// Only an actual HP/Prayer bar blinks for low vitals (the chat
				// call-out below always watches real Hitpoints regardless).
				boolean hpFlash = hpIsBar && hpWarn && nowMs - hpWarnStartMs < flashMs;
				boolean prayFlash = prayIsBar && prayWarn && nowMs - prayWarnStartMs < flashMs;

				// DPS, computed up front: the top bar may display it. Live
				// wall-clock denominator while the target lives (downtime
				// bleeds the number), frozen at the last hit once it dies,
				// floored at 3s so opening hits read low and converge.
				Actor dpsT = dpsTarget != null ? dpsTarget.get() : null;
				boolean dpsLive = dpsT != null && !dpsT.isDead();
				Player dpsMe = client.getLocalPlayer();
				boolean dpsEngaged = dpsLive && dpsMe != null
					&& dpsMe.getInteracting() == dpsT;
				// The denominator is ALWAYS the live wall clock now — even after
				// the target dies. Downtime therefore BLEEDS the number down
				// gradually instead of freezing it, and it keeps reading as long
				// as you were recently in combat and the bars are still up (the
				// same persist window), rather than snapping off a cliff at 8s.
				int dpsTrueTenths = -1;
				if (config.dpsSession() == DpsSessionMode.WHOLE_SESSION)
				{
					// Lifetime average over the whole login: total damage over
					// total elapsed. Never resets per target; shows whenever the
					// display is up and you've dealt any damage this login.
					if (sessionDamage > 0 && (dpsEngaged || nowMs - lastDmgMs < persistMs))
					{
						float secs = Math.max(3f, (nowMs - sessionStartMs) / 1000f);
						dpsTrueTenths = Math.round(sessionDamage / secs * 10f);
					}
				}
				else if (fightDamage > 0 && (dpsEngaged || nowMs - lastDmgMs < persistMs))
				{
					float dpsSecs = Math.max(3f, (nowMs - fightStartMs) / 1000f);
					dpsTrueTenths = Math.round(fightDamage / dpsSecs * 10f);
				}
				// Ramp the shown number up from 0 at each fight's start, and
				// ease it back DOWN (not snap) once the session ends, so it
				// fades out with the bars instead of dropping to 0 instantly.
				long dpsSessKey = config.dpsSession() == DpsSessionMode.WHOLE_SESSION
					? sessionStartMs : fightStartMs;
				if (dpsTrueTenths >= 0)
				{
					if (dpsSessKey != dpsDispSession)
					{
						dpsDisp = 0f;
						dpsDispSession = dpsSessKey;
					}
					dpsDisp += (dpsTrueTenths - dpsDisp) * Math.min(1f, dt / 2500f);
				}
				else if (vitalsAlpha <= 0.02f)
				{
					// The bars are gone: clear the reading AND end the session, so
					// the next fight starts clean. While the display is still up the
					// last reading is HELD - including its session key, since zeroing
					// that made the number restart its ramp from 0 every time damage
					// paused and picked back up.
					dpsDisp = 0f;
					dpsDispSession = 0L;
					dpsSessionEnded = true;
				}
				int dpsTenths = dpsDisp >= 0.05f ? Math.round(dpsDisp) : -1;
				String dpsVal = dpsTenths >= 0
					? (dpsTenths / 10) + "." + (dpsTenths % 10) : "0.0";

				// Spec-ready shout: the orb quietly refilling is easy to miss
				// mid-fight — the pet calls it the moment it tops out.
				int specNow = client.getVarpValue(VarPlayer.SPECIAL_ATTACK_PERCENT) / 10;
				if (prevSpecPct >= 0 && prevSpecPct < 100 && specNow >= 100)
				{
					shout("SPEC!", 3000);
				}
				prevSpecPct = specNow;

				// Special-attack energy (any bar may show it).
				int specPct = client.getVarpValue(VarPlayer.SPECIAL_ATTACK_PERCENT) / 10;
				// DPS trend state, run every frame a bar shows DPS so it stays
				// smooth: absorb per-hit variance (~2s), a peak that decays over
				// minutes, rising/falling read off a slower reference. dpsFill
				// runs toward the session peak.
				float dpsFill = 0f;
				if (dpsBar)
				{
					float cur = dpsTrueTenths >= 0 ? dpsTrueTenths / 10f : 0f;
					dpsSmooth += (cur - dpsSmooth) * Math.min(1f, dt / 2000f);
					dpsPeak = Math.max(dpsSmooth, dpsPeak * (1f - dt * 0.00002f));
					dpsRef += (dpsSmooth - dpsRef) * Math.min(1f, dt / 4500f);
					float band = Math.max(0.15f, dpsPeak * 0.02f);
					dpsTrend = dpsSmooth - dpsRef > band ? 1
						: dpsSmooth - dpsRef < -band ? -1 : 0;
					dpsNearPeak = dpsPeak > 0.5f && dpsSmooth >= dpsPeak * 0.94f;
					dpsFill = dpsPeak > 0.1f
						? Math.max(0f, Math.min(1f, dpsSmooth / dpsPeak)) : 0f;
				}

				// Anchor to whichever pet is actually drawn: our ghost while it
				// follows, the real NPC once it has taken back over.
				// The lean is part of where the ghost is DRAWN, so the display
				// carries it too or it slides off the model.
				LocalPoint lp = ghostDrawn
					? new LocalPoint(Math.round(ghostX + npcPushX),
						Math.round(ghostY + npcPushY))
					: (pet != null ? pet.getLocalLocation() : null);
				int anchorPlane = ghostDrawn ? pathPlane : client.getPlane();
				if (lp == null)
				{
					return null;
				}
				// Sample the height ONLY between action animations: attack
				// poses (constant in thrall mode) rear the model up and the
				// peak-hold would latch that spike — that's the bars going
				// huge on a thrall summon. The idle bob is a POSE animation
				// (separate channel), so peak-hold still irons it out.
				int liveH = pet != null && pet.getAnimation() == -1
					? pet.getLogicalHeight() : 0;
				int petId = pet != null ? pet.getId() : -1;
				if (petId != -1 && petId != vitalsPetId)
				{
					vitalsPetId = petId;
					stableLogH = 0f; // new pet: relearn its height
				}
				if (liveH > 0)
				{
					// Peak-hold with a ~0.5%/s decay — slow enough that the
					// idle bob's multi-second troughs can't carve a visible dip
					// between peaks (5%/s still let ~15% of the breathing
					// through), fast enough to recover within a minute if a
					// one-off animation spikes the height.
					//
					// But REJECT samples far above the running value: a single
					// bad frame around a teleport/respawn (logicalHeight briefly
					// enormous) would otherwise latch and, because the offset is
					// a percent of pet size, fling the whole display way up the
					// screen for a minute. A real pet never doubles in height.
					if (stableLogH <= 0f)
					{
						stableLogH = liveH;
					}
					else if (liveH <= stableLogH * 1.6f)
					{
						stableLogH = Math.max(liveH, stableLogH * (1f - dt * 0.000005f));
					}
					else
					{
						stableLogH *= (1f - dt * 0.000005f); // ignore the spike, keep decaying
					}
				}
				else if (stableLogH <= 0f)
				{
					stableLogH = 200f; // nothing seen yet (blip): sane default
				}
				Point ground = Perspective.localToCanvas(client, lp, anchorPlane, 0);
				Point petTop = Perspective.localToCanvas(client, lp, anchorPlane, Math.round(stableLogH));
				// Size reference: a FIXED model height, not this pet's. Sizing off
				// the real height meant a tall pet (abyssal orphan) blew the whole
				// display up, and every untested tall pet would do the same. This
				// still scales with zoom/perspective, but is identical for every
				// pet; the real petTop is still used to POSITION it above the head.
				Point refTop = Perspective.localToCanvas(client, lp, anchorPlane, BAR_REF_HEIGHT);
				if (ground == null || petTop == null || refTop == null)
				{
					return null;
				}
				float petPx = Math.max(8f, ground.getY() - refTop.getY());
				// Dead-band the SIZE (the position must track the pet, but the
				// bar dimensions shouldn't pump as perspective shifts a few
				// percent while it moves around): hold until the target drifts
				// >5%, then ease over and freeze again. Width is height x2.4,
				// so even small height wobble is very visible in width.
				if (smoothPetPx <= 0f)
				{
					smoothPetPx = petPx;
				}
				if (!petPxChasing && Math.abs(petPx - smoothPetPx) > smoothPetPx * 0.05f)
				{
					petPxChasing = true;
				}
				if (petPxChasing)
				{
					smoothPetPx += (petPx - smoothPetPx) * Math.min(1f, dt / 200f);
					if (Math.abs(petPx - smoothPetPx) <= smoothPetPx * 0.005f)
					{
						petPxChasing = false;
					}
				}
				petPx = smoothPetPx;

				// Alpha: fade × opacity, then ONLY the low stat pulses — so a
				// low-HP flash doesn't drag the (fine) Prayer readout with it.
				float baseA = Math.max(0f, Math.min(1f,
					vitalsAlpha * (config.vitalsOpacity() / 100f)));
				float pulse = 0.3f + 0.7f * (0.5f + 0.5f * (float) Math.sin(nn / 1.6e8));
				float hpAlpha = hpFlash ? baseA * pulse : baseA;
				float prayAlpha = prayFlash ? baseA * pulse : baseA;

				// --- bars: short and WIDE, scaled with the pet ---------------
				float wFactor;   // bar width  ÷ pet on-screen height
				float hFactor;   // bar height ÷ pet on-screen height (small)
				switch (config.vitalsSize())
				{
					case SMALL:
						wFactor = 1.4f;
						hFactor = 0.15f;
						break;
					case MEDIUM:
						wFactor = 1.9f;
						hFactor = 0.19f;
						break;
					default: // LARGE
						wFactor = 2.4f;
						hFactor = 0.24f;
						break;
				}
				int barW = Math.max(24, Math.round(petPx * wFactor));
				int barH = Math.max(2, Math.round(petPx * hFactor));
				int barGap = Math.max(1, barH / 3);
				int stackH = nBars > 0 ? nBars * barH + (nBars - 1) * barGap : barH;
				// The height slider is a percent of the pet's on-screen size so
				// the displacement holds its proportion at every zoom. Saved
				// per pet.
				float off = config.vitalsOffset() / 100f * petPx;
				int barsX = ground.getX() - barW / 2;
				int barsY = petTop.getY() - Math.round(off) - stackH;
				// OSRS overhead-bar colours: bright green over bright red, blue
				// over dark for Prayer, hard black outline.
				// The HP fill mirrors the orb's poison states: sickly green
				// while poisoned, dark green under venom.
				int poisonVarp = client.getVarpValue(VarPlayer.POISON);
				Color hpFill = poisonVarp >= 1000000 ? C_HP_VENOM
					: poisonVarp > 0 ? C_HP_POISON : C_HP_FILL;

				// Shared number scale: the largest that fits INSIDE the bar, in
				// both directions. Width counts as much as height - measuring
				// only the height is what pushed a wide number like "99/99" out
				// of a narrow bar when a size down would have sat inside fine.
				// The value strings are built first so their length can drive
				// the choice instead of being measured after the fact.
				String[] barVals = new String[3];
				Color[] barCols = new Color[3];
				int longest = 1;
				for (int si = 0; si < 3; si++)
				{
					BarStat st = barSlots[si];
					if (st == BarStat.OFF)
					{
						barNumStr[si] = null;
						continue;
					}
					switch (st)
					{
						case HITPOINTS:
							barVals[si] = hp + "/" + maxHp;
							barCols[si] = TXT_HP;
							break;
						case PRAYER:
							barVals[si] = pray + "/" + maxPray;
							barCols[si] = TXT_PRAY;
							break;
						case SPEC:
							barVals[si] = Integer.toString(specPct);
							barCols[si] = TXT_SPEC;
							break;
						// Bare value: the flanking swords name the bar, and the
						// word crowded them out of the space they need.
						default:
							barVals[si] = dpsVal;
							barCols[si] = Color.WHITE;
							break;
					}
					longest = Math.max(longest, barVals[si].length());
				}
				int innerW = barW - 2;
				int fitScale = 1;
				for (int sc = 3; sc >= 1; sc--)
				{
					if (microWidth(longest, sc) <= innerW && 5 * sc + 2 <= barH)
					{
						fitScale = sc;
						break;
					}
				}
				int desired = textScale;
				// Step UP only with a few pixels to spare (hysteresis), but step
				// DOWN the moment it no longer fits, so it never overflows.
				if (fitScale > textScale
					&& microWidth(longest, textScale + 1) + 4 <= innerW
					&& 5 * (textScale + 1) + 6 <= barH)
				{
					desired = textScale + 1;
				}
				else if (fitScale < textScale)
				{
					desired = fitScale;
				}
				boolean scaleChanged = desired != textScale;
				if (scaleChanged)
				{
					textScale = desired;
					scaleSwapNanos = nn;
				}
				float swapT = Math.min(1f, (nn - scaleSwapNanos) / 8e8f);
				float swap = swapT * swapT * swapT * (swapT * (swapT * 6f - 15f) + 10f);

				// Build each active bar's in-bar number at the chosen scale.
				for (int si = 0; si < 3; si++)
				{
					if (barVals[si] == null)
					{
						continue;
					}
					if (scaleChanged)
					{
						barNumOld[si] = barNumBuf[si];
					}
					else if (swapT >= 1f)
					{
						barNumOld[si] = null;
					}
					String key = barVals[si] + "@" + textScale + "#" + barCols[si].getRGB();
					if (!key.equals(barNumStr[si]))
					{
						barNumStr[si] = key;
						barNumBuf[si] = buildMicroString(barVals[si], textScale, barCols[si]);
					}
				}
				// Numbers only leave the bars when even the SMALLEST size can't
				// sit inside. Keeping the two thresholds a couple of pixels
				// apart is all the hysteresis this needs - the old wide band
				// (needing 1.5x the room to come back) is why zooming out and
				// back in left the text outside a bar it plainly fitted.
				int need1 = microWidth(longest, 1);
				if (!fbActive && (need1 > innerW || barH < 7))
				{
					fbActive = true;
				}
				else if (fbActive && need1 + 2 <= innerW && barH >= 8)
				{
					fbActive = false;
				}
				fbBlend += ((fbActive ? 1f : 0f) - fbBlend) * Math.min(1f, dt / 600f);
				if (fbBlend < 0.01f)
				{
					fbBlend = 0f;
				}
				else if (fbBlend > 0.99f)
				{
					fbBlend = 1f;
				}

				// Draw each active bar: body, effect, and (zoomed in) its number. Collect
				// the fallback entries {icon, value, colour, alpha} for the zoomed-out line.
				java.util.List<Object[]> fbBars = new java.util.ArrayList<>(3);
				int drawn = 0;
				for (int si = 0; si < 3; si++)
				{
					BarStat st = barSlots[si];
					if (st == BarStat.OFF)
					{
						continue;
					}
					int by = barsY + drawn * (barH + barGap);
					drawn++;
					float sAlpha = baseA;
					switch (st)
					{
						case HITPOINTS:
							sAlpha = hpFlash ? baseA * pulse : baseA;
							drawBar(g, barsX, by, barW, barH, hpDisp, hpFill, C_HP_BK, sAlpha);
							drawHpWave(g, barsX, by, barW, barH, hpDisp, nn, hpUpUntil, hpDownUntil, sAlpha);
							fbBars.add(new Object[]{hpIcon, Integer.toString(hp), TXT_HP, sAlpha});
							break;
						case PRAYER:
							sAlpha = prayFlash ? baseA * pulse : baseA;
							drawBar(g, barsX, by, barW, barH, prayDisp, C_PRAY_FILL, C_PRAY_BK, sAlpha);
							drawPrayTrail(g, barsX, by, barW, barH, prayDisp, prayGhost,
								prayUpUntil, praying, nn, sAlpha);
							fbBars.add(new Object[]{prayIcon, Integer.toString(pray), TXT_PRAY, sAlpha});
							break;
						case SPEC:
							drawBar(g, barsX, by, barW, barH,
								Math.max(0f, Math.min(1f, specPct / 100f)), C_SPEC_FILL, C_SPEC_BK, sAlpha);
							fbBars.add(new Object[]{specIcon, Integer.toString(specPct), TXT_SPEC, sAlpha});
							break;
						default: // DPS
							drawDpsTrendBar(g, barsX, by, barW, barH, dpsFill, dpsTrend, dpsNearPeak, nn, sAlpha);
							fbBars.add(new Object[]{dpsIcon(5 * textScale + 2), dpsVal, TXT_DPS, sAlpha});
							break;
					}
					if (fbBlend < 1f)
					{
						// The stat's own icon flanks the number inside the bar,
						// so each bar identifies itself at a glance.
						// Every bar gets its icon, DPS included (the swords).
						Object[] lastFb = fbBars.get(fbBars.size() - 1);
						drawBarIcons(g, (BufferedImage) lastFb[0],
							barsX, by, barW, barH,
							barNumBuf[si] != null ? barNumBuf[si].getWidth() : 0,
							sAlpha * (1f - fbBlend));
						drawBarText(g, barNumBuf[si], barNumOld[si], swap, barsX, by, barW, barH,
							sAlpha * (1f - fbBlend));
					}
				}

				// --- tracker row ------------------------------------------
				// Never UNDER the bars - that is exactly where the pet is. Once the
				// bar numbers step outside ("far"), the trackers drop to the small
				// size too so the whole row matches.
				boolean far = fbBlend >= 0.5f;
				int trScale = far ? 1 : Math.min(2, textScale);
				// Unit suffixes cost more width than they are worth at anything
				// but the closest zoom, where there is room to spell them out.
				boolean ultra = !far && trScale >= 2;
				float xpBaseA = Math.max(0f, Math.min(1f,
					xpAlpha * (config.vitalsOpacity() / 100f)));
				boolean barsShown = baseA > 0.02f;
				// Everything lives in one row, so nothing swaps position at the
				// crossover and there is no jump to hide with an alpha dip.
				float camFade = 1f;
				int trGlyphH = 5 * trScale + 2;
				// Tracker readouts in row order: DPS, kills/hr, then one entry per
				// XP/hr skill (several when multiskilling with locked skills).
				java.util.List<Object[]> dpsItems = new java.util.ArrayList<>(1);
				java.util.List<Object[]> xpItems = new java.util.ArrayList<>(3);
				if (config.petDps() && dpsTenths >= 0 && !dpsBar && baseA > 0.02f)
				{
					String ds = dpsVal;
					String dKey = ds + "@" + trScale;
					if (!dKey.equals(dpsStr))
					{
						dpsStr = dKey;
						dpsBuf = buildMicroString(ds, trScale, TXT_DPS);
					}
					dpsItems.add(new Object[]{dpsIcon(trGlyphH), dpsBuf, baseA * camFade});
				}
				// Kills/hr (left group).
				if (config.petKillsHr() && baseA > 0.02f)
				{
					int kph = killsPerHour();
					if (kph >= 0)
					{
						String ds = kph + (ultra ? " KPH" : "");
						String key = ds + "@" + trScale;
						if (!key.equals(kphStr))
						{
							kphStr = key;
							kphBuf = buildMicroString(ds, trScale, C_DPS_AMBER);
						}
						dpsItems.add(new Object[]{skullIcon(trGlyphH), kphBuf, baseA * camFade});
					}
				}
				if (config.petXpHr() && xpBaseA > 0.02f)
				{
					boolean multi = xpSkills.size() > 1;
					for (Skill sk : xpSkills)
					{
						long[] xs = xpSessions.get(sk);
						if (xs == null)
						{
							continue;
						}
						// True elapsed since the session's first gain: the rate starts
						// at 0 and ramps up (see onStatChanged). Idle past the reset
						// window starts a fresh session.
						long gained = xs[2] - xs[0];
						float hours = Math.max(1000L, nowMs - xs[1]) / 3600000f;
						boolean label = ultra && !multi;
						String rate = formatXpRate(Math.round(gained / hours))
							+ (label ? "/HR" : "");
						xpItems.add(new Object[]{
							skillIconManager.getSkillImage(sk, true),
							xpBufFor(sk, rate, trScale), xpBaseA * camFade});
					}
				}
				// One row for EVERYTHING: the zoomed-out bar numbers and the
				// tracker readouts share a single line centred on the bar axis,
				// spreading out into the free space either side. The old split
				// (a row of three on top plus two vertical flank stacks) is why
				// only three readouts ever made it across the top while the
				// sides sat empty.
				java.util.List<Object[]> row = new java.util.ArrayList<>(
					fbBars.size() + dpsItems.size() + xpItems.size());
				if (fbBlend > 0f)
				{
					for (int i = 0; i < fbBars.size(); i++)
					{
						Object[] b = fbBars.get(i);
						String key = b[1] + "@" + textScale + "#" + ((Color) b[2]).getRGB();
						if (!key.equals(fbRowStr[i]))
						{
							fbRowStr[i] = key;
							fbRowBuf[i] = buildMicroString((String) b[1], textScale, (Color) b[2]);
						}
						row.add(new Object[]{b[0], fbRowBuf[i], fbBlend * (Float) b[3]});
					}
				}
				row.addAll(dpsItems);
				row.addAll(xpItems);
				int rowH = 0;
				for (Object[] it : row)
				{
					rowH = Math.max(rowH, Math.max(9, ((BufferedImage) it[1]).getHeight()));
				}
				int gapV = 3;
				int crownStack = 0;
				if (rowH > 0)
				{
					crownStack = drawTrackerCentered(g, row, barsX, barsY, barW,
						stackH, rowH, gapV, barsShown);
				}
				// The nametag and shout stack above whatever the row occupies.
				int headroom = barsShown && crownStack > 0 ? crownStack + 3 : 0;

				// --- pet nametag ------------------------------------------
				// Custom per-pet name in the same pixel font, topmost of the
				// stack. Uppercased: the micro font is caps-only.
				int nameH = 0;
				String petLabel = config.petName();
				if (petLabel != null && !petLabel.trim().isEmpty())
				{
					String nm = petLabel.trim().toUpperCase();
					int nScale = Math.max(1, Math.min(2, textScale));
					String nKey = nm + "@n" + nScale;
					if (!nKey.equals(nameStr))
					{
						nameStr = nKey;
						nameBuf = buildMicroString(nm, nScale);
					}
					nameH = nameBuf.getHeight() + 3;
					blitImg(g, nameBuf, barsX + (barW - nameBuf.getWidth()) / 2,
						barsY - headroom - nameBuf.getHeight() - 3,
						nameBuf.getWidth(), nameBuf.getHeight(), baseA, true);
				}

				// Edge-triggered chat call-out: the pet warns you once each time
				// you cross a threshold (re-arms when you recover above it).
				// The same trigger also puts words over the pet's head.
				if (want)
				{
					if (hpWarn && !prevHpWarn)
					{
						chat("Your " + displayedPetName() + " yelps - heal up!");
						overheadText = "HEAL UP!";
						overheadUntilMs = nowMs + 4000;
					}
					if (prayWarn && !prevPrayWarn)
					{
						chat("Your " + displayedPetName() + " nudges you - restore Prayer!");
						overheadText = "PRAYER!";
						overheadUntilMs = nowMs + 4000;
					}
					prevHpWarn = hpWarn;
					prevPrayWarn = prayWarn;
				}

				// --- overhead speech --------------------------------------
				// Short shout above everything, pixel font like the rest.
				// Fades out over its last 400ms.
				if (overheadText != null && nowMs < overheadUntilMs)
				{
					int oScale = Math.max(1, Math.min(2, textScale));
					String oKey = overheadText + "@o" + oScale;
					if (!oKey.equals(overheadStr))
					{
						overheadStr = oKey;
						overheadBuf = buildMicroString(overheadText, oScale);
					}
					float oA = Math.min(1f, (overheadUntilMs - nowMs) / 400f) * baseA;
					blitImg(g, overheadBuf,
						barsX + (barW - overheadBuf.getWidth()) / 2,
						barsY - headroom - nameH - overheadBuf.getHeight() - 4,
						overheadBuf.getWidth(), overheadBuf.getHeight(), oA, true);
				}
			}
			catch (Exception ex)
			{
				// Never let overlay math disturb the game render.
			}
			return null;
		}

		/**
		 * Centre a number image inside its bar, cross-fading from the previous
		 * scale's image after a size step. The caller decides visibility (the
		 * shared in-bar/fallback cross-fade) and bakes it into alpha.
		 */
		/**
		 * A bar's own stat icon, drawn INSIDE the bar flanking the centred
		 * number on both sides, so each bar says what it is without a legend.
		 * Skipped when the bar is too short to fit the sprite legibly.
		 */
		private void drawBarIcons(Graphics2D g, BufferedImage icon, int x, int y,
			int w, int h, int numW, float alpha)
		{
			// Below ~12px the detailed skills-tab sprites turn to mush (the
			// Prayer icon reads as a circle or a plus sign), so don't draw them
			// at all rather than show an unrecognisable blob.
			if (icon == null || alpha <= 0.02f || h < 14)
			{
				return;
			}
			int ih = h - 2;
			int iw = Math.max(1, Math.round(ih * icon.getWidth() / (float) icon.getHeight()));
			// Only if there's real room either side of the number.
			int side = (w - numW) / 2;
			if (side < iw + 3)
			{
				return;
			}
			int iy = y + (h - ih) / 2;
			blitImg(g, icon, x + 2, iy, iw, ih, alpha, false);
			blitImg(g, icon, x + w - iw - 2, iy, iw, ih, alpha, false);
		}

		private void drawBarText(Graphics2D g, BufferedImage buf, BufferedImage old,
			float swap, int x, int y, int w, int h, float alpha)
		{
			if (buf == null || alpha <= 0f)
			{
				return;
			}
			float a = alpha;
			if (old != null && swap < 1f)
			{
				blitImg(g, old,
					x + (w - old.getWidth()) / 2, y + (h - old.getHeight()) / 2,
					old.getWidth(), old.getHeight(), a * (1f - swap), true);
				a *= swap;
			}
			blitImg(g, buf,
				x + (w - buf.getWidth()) / 2, y + (h - buf.getHeight()) / 2,
				buf.getWidth(), buf.getHeight(), a, true);
		}

		/** Width of a tracker entry (optional icon + gap + its text) at row height. */
		private int itemWidth(Object[] it, int rowH)
		{
			BufferedImage ic = (BufferedImage) it[0];
			BufferedImage bf = (BufferedImage) it[1];
			int lh = Math.max(9, bf.getHeight());
			return (ic != null
				? Math.round(lh * ic.getWidth() / (float) ic.getHeight()) + 2 : 0)
				+ bf.getWidth();
		}

		/** Blit one tracker entry with its own alpha, vertically centred in rowH. */
		private void drawTrackerItem(Graphics2D g, Object[] it, int x, int y, int rowH)
		{
			BufferedImage ic = (BufferedImage) it[0];
			BufferedImage bf = (BufferedImage) it[1];
			float a = (Float) it[2];
			int th = bf.getHeight();
			int lh = Math.max(9, th);
			if (ic != null)
			{
				int iw = Math.round(lh * ic.getWidth() / (float) ic.getHeight());
				blitImg(g, ic, x, y + (rowH - lh) / 2, iw, lh, a, false);
				x += iw + 2;
			}
			blitImg(g, bf, x, y + (rowH - th) / 2,
				bf.getWidth(), bf.getHeight(), a, true);
		}

		/**
		 * The DPS bar as a TREND, not a level. The fill runs toward the session
		 * peak; its colour tells you which way DPS is heading right now:
		 *   rising  → yellow, with a bright edge sweeping up (charging);
		 *   falling → red, with a dim wave washing down;
		 *   steady near your peak → green with a soft glow;
		 *   steady below peak → amber, still.
		 * All fed from a heavily-smoothed value, so ordinary hit-to-hit
		 * variance doesn't flap it between colours.
		 */
		private void drawDpsTrendBar(Graphics2D g, int x, int y, int w, int h,
			float frac, int trend, boolean nearPeak, long nn, float alpha)
		{
			frac = Math.max(0f, Math.min(1f, frac));
			Color fill;
			Color back;
			if (nearPeak && trend >= 0)
			{
				fill = C_DPST_PEAK;   // at/near peak: cyan
				back = C_DPST_PEAK_BK;
			}
			else if (trend > 0)
			{
				fill = C_DPST_RISE;   // rising: gold
				back = C_DPST_RISE_BK;
			}
			else if (trend < 0)
			{
				fill = C_DPST_FALL;   // falling: orange
				back = C_DPST_FALL_BK;
			}
			else
			{
				fill = C_DPST_STEADY; // steady below peak: violet
				back = C_DPST_STEADY_BK;
			}
			g.setColor(argb(Color.BLACK, 235, alpha));
			g.fillRect(x - 1, y - 1, w + 2, h + 2);
			g.setColor(argb(back, 255, alpha));
			g.fillRect(x, y, w, h);
			int fw = Math.round(w * frac);
			g.setColor(argb(fill, 255, alpha));
			g.fillRect(x, y, fw, h);
			if (fw <= 0)
			{
				return;
			}
			float t = (nn % 1_000_000_000L) / 1e9f; // 0..1 each second
			if (nearPeak && trend >= 0)
			{
				// Peak glow: gentle full-width brightness pulse.
				float pulse = 0.5f + 0.5f * (float) Math.sin(t * 2f * Math.PI);
				g.setColor(argb(C_DPST_GLOW, Math.round(70 * pulse), alpha));
				g.fillRect(x, y, fw, h);
			}
			else if (trend > 0)
			{
				// Charging: a bright band sweeps toward the leading edge.
				int bandW = Math.max(2, w / 6);
				int bx = x + Math.round((fw + bandW) * t) - bandW;
				int x0 = Math.max(x, bx);
				int x1 = Math.min(x + fw, bx + bandW);
				if (x1 > x0)
				{
					g.setColor(argb(Color.WHITE, 90, alpha));
					g.fillRect(x0, y, x1 - x0, h);
				}
			}
			else if (trend < 0)
			{
				// Losing: a dim band washes back toward the start.
				int bandW = Math.max(2, w / 6);
				int bx = x + fw - Math.round((fw + bandW) * t);
				int x0 = Math.max(x, bx);
				int x1 = Math.min(x + fw, bx + bandW);
				if (x1 > x0)
				{
					g.setColor(argb(Color.BLACK, 90, alpha));
					g.fillRect(x0, y, x1 - x0, h);
				}
			}
		}

		/** A short, wide bar: black border, dark backing, coloured fill. */
		private void drawBar(Graphics2D g, int x, int y, int w, int h,
			float frac, Color fill, Color back, float alpha)
		{
			frac = Math.max(0f, Math.min(1f, frac));
			g.setColor(argb(Color.BLACK, 235, alpha));
			g.fillRect(x - 1, y - 1, w + 2, h + 2);
			g.setColor(argb(back, 255, alpha));
			g.fillRect(x, y, w, h);
			g.setColor(argb(fill, 255, alpha));
			g.fillRect(x, y, Math.round(w * frac), h);
		}

		/**
		 * Prayer GHOST TRAIL. The solid fill is already drawn at prayDisp (the
		 * smooth-sliding level); this paints the translucent chunk between the
		 * fill edge and the lingering high-water mark (prayGhost) as a fading
		 * afterimage of what just drained, and a bright leading pulse just after
		 * a restore. Continuous by construction: prayDisp/prayGhost ease every
		 * frame, so a tick-by-tick drain reads as one smooth receding trail.
		 */
		private void drawPrayTrail(Graphics2D g, int x, int y, int w, int h,
			float dispFrac, float ghostFrac, long upUntil, boolean draining,
			long nanos, float alpha)
		{
			int fillW = Math.round(w * Math.max(0f, Math.min(1f, dispFrac)));
			int ghostW = Math.round(w * Math.max(0f, Math.min(1f, ghostFrac)));
			// Drain trail: from the current fill edge out to the high-water mark.
			if (ghostW > fillW)
			{
				float gap = ghostFrac - dispFrac;               // how much still trailing
				int a = Math.round(150 * Math.min(1f, gap * 6f)); // fades as it closes
				g.setColor(argb(C_TRICKLE, a, alpha));
				g.fillRect(x + fillW, y, ghostW - fillW, h);
			}
			// Drain shimmer: a pale band riding the fill edge whenever prayers
			// are actually burning. The trail above only appears on a whole
			// point drop, which left the bar looking frozen in between.
			if (draining && fillW > 0)
			{
				float ph = (nanos % 1_400_000_000L) / 1.4e9f;
				float wave = 0.5f - 0.5f * (float) Math.cos(ph * 2 * Math.PI);
				int bandW = Math.max(2, w / 10);
				g.setColor(argb(C_PRAY_EDGE, Math.round(60 + 115 * wave), alpha));
				g.fillRect(x + Math.max(0, fillW - bandW), y,
					Math.min(bandW, fillW), h);
			}
			// Restore pulse: a bright edge riding the rising fill for a moment.
			long now = System.currentTimeMillis();
			if (now < upUntil && fillW > 1)
			{
				float p = 1f - (upUntil - now) / (float) BAR_FX_DUR;
				int bandW = Math.max(2, w / 8);
				int a = Math.round(150 * (1f - p));
				g.setColor(argb(C_HEAL, a, alpha));
				g.fillRect(x + Math.max(0, fillW - bandW), y, Math.min(bandW, fillW), h);
			}
		}

		/**
		 * HP LIQUID WAVE. Over the smooth-sliding fill, a shallow sinusoidal
		 * shimmer runs along the surface so the bar reads like liquid: it swells
		 * green just after a heal, sloshes red just after a hit, and idles as a
		 * faint ripple otherwise.
		 */
		private void drawHpWave(Graphics2D g, int x, int y, int w, int h,
			float dispFrac, long nn, long upUntil, long downUntil, float alpha)
		{
			int fillW = Math.round(w * Math.max(0f, Math.min(1f, dispFrac)));
			if (fillW <= 1)
			{
				return;
			}
			long now = System.currentTimeMillis();
			Color tint = now < downUntil ? C_BLEED : now < upUntil ? C_HEAL : Color.WHITE;
			// Recency amps the ripple; it never fully dies so the surface always
			// "lives" a little.
			float amp = 0.25f;
			if (now < downUntil)
			{
				amp = 0.35f + 0.5f * (1f - (downUntil - now) / (float) BAR_FX_DUR);
			}
			else if (now < upUntil)
			{
				amp = 0.35f + 0.5f * (1f - (upUntil - now) / (float) BAR_FX_DUR);
			}
			float t = (nn % 1_400_000_000L) / 1.4e8f; // ~1.4s loop
			int step = Math.max(2, w / 24);
			for (int sx = 0; sx < fillW; sx += step)
			{
				float phase = t + sx / (float) w * 6.283f * 2f;
				float s = (float) Math.sin(phase);
				if (s <= 0f)
				{
					continue;
				}
				int a = Math.round(70 * amp * s);
				if (a <= 0)
				{
					continue;
				}
				g.setColor(argb(tint, a, alpha));
				g.fillRect(x + sx, y, Math.min(step, fillW - sx), h);
			}
		}

		/** Draw an image at (x,y,w,h) with the master alpha; crisp = nearest. */
		private void blitImg(Graphics2D g, BufferedImage img, int x, int y, int w, int h,
			float alpha, boolean crisp)
		{
			if (img == null || w <= 0 || h <= 0)
			{
				return;
			}
			Object prevInterp = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
			Composite prevComp = g.getComposite();
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				crisp ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR
					: RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
				Math.max(0f, Math.min(1f, alpha))));
			g.drawImage(img, x, y, w, h, null);
			g.setComposite(prevComp);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				prevInterp != null ? prevInterp : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		}

		private Color argb(Color c, int baseAlpha, float alpha)
		{
			int a = Math.max(0, Math.min(255, Math.round(baseAlpha * alpha)));
			return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
		}

		/**
		 * Render a number ("72/99") in a tiny hand-drawn 3x5 pixel font at an
		 * integer pixel scale, yellow with a 1px black outline. Drawn 1:1 by
		 * the caller so it is pixel-crisp at any size — much smaller than the
		 * smallest built-in font, with no scaling to blur it.
		 */
		/**
		 * Pixel width buildMicroString would produce for an n-character string
		 * at this scale - without building it, so the fit test above can ask
		 * "would this fit?" before committing to a size.
		 */
		private int microWidth(int n, int scale)
		{
			if (n <= 0)
			{
				return 0;
			}
			return n * 3 * scale + (n - 1) * Math.max(3, scale + 1) + 2;
		}

		private BufferedImage buildMicroString(String str, int scale)
		{
			return buildMicroString(str, scale, Color.YELLOW);
		}

		private BufferedImage buildMicroString(String str, int scale, Color colour)
		{
			// The micro font is caps-only: a lowercase char has no glyph and
			// silently renders as blank (this is why the "45s" suffix vanished).
			// Fold case here so no caller can hit that again.
			str = str.toUpperCase();
			int n = str.length();
			int glyphW = 3 * scale;
			// Inter-glyph gap must clear BOTH glyphs' 1px outlines plus a 1px
			// space, else adjacent digits' outlines touch and "bleed" together
			// (worst at scale 1). 3px is the floor; it grows a little with scale.
			int spW = Math.max(3, scale + 1);
			int contentW = n * glyphW + Math.max(0, n - 1) * spW;
			int pad = 1;
			int w = contentW + 2 * pad;
			int h = 5 * scale + 2 * pad;
			BufferedImage img = new BufferedImage(Math.max(1, w), Math.max(1, h), BufferedImage.TYPE_INT_ARGB);
			Graphics2D g2 = img.createGraphics();
			// 1px black outline (crisp, unscaled) then the coloured digits.
			drawMicro(g2, str, pad - 1, pad, scale, Color.BLACK);
			drawMicro(g2, str, pad + 1, pad, scale, Color.BLACK);
			drawMicro(g2, str, pad, pad - 1, scale, Color.BLACK);
			drawMicro(g2, str, pad, pad + 1, scale, Color.BLACK);
			drawMicro(g2, str, pad, pad, scale, colour);
			g2.dispose();
			return img;
		}

		/** Fill the set pixels of each glyph in one colour at the given origin. */
		private void drawMicro(Graphics2D g2, String str, int ox, int oy, int scale, Color color)
		{
			g2.setColor(color);
			int x = ox;
			for (int i = 0; i < str.length(); i++)
			{
				int[] rows = microGlyph(str.charAt(i));
				for (int r = 0; r < 5; r++)
				{
					int bits = rows[r];
					for (int col = 0; col < 3; col++)
					{
						if (((bits >> (2 - col)) & 1) != 0)
						{
							g2.fillRect(x + col * scale, oy + r * scale, scale, scale);
						}
					}
				}
				x += 3 * scale + Math.max(3, scale + 1);
			}
		}

		/** 3-wide x 5-tall bitmap for a digit or '/', one 3-bit value per row. */
		private int[] microGlyph(char c)
		{
			switch (c)
			{
				case '0': return new int[]{7, 5, 5, 5, 7};
				case '1': return new int[]{2, 6, 2, 2, 7};
				case '2': return new int[]{7, 1, 7, 4, 7};
				case '3': return new int[]{7, 1, 7, 1, 7};
				case '4': return new int[]{5, 5, 7, 1, 1};
				case '5': return new int[]{7, 4, 7, 1, 7};
				case '6': return new int[]{7, 4, 7, 5, 7};
				case '7': return new int[]{7, 1, 2, 4, 4};
				case '8': return new int[]{7, 5, 7, 5, 7};
				case '9': return new int[]{7, 5, 7, 1, 7};
				case '/': return new int[]{1, 1, 2, 4, 4};
				case '.': return new int[]{0, 0, 0, 0, 2};
				case ':': return new int[]{0, 2, 0, 2, 0};
				case '-': return new int[]{0, 0, 7, 0, 0};
				case '!': return new int[]{2, 2, 2, 0, 2};
				case 'A': return new int[]{2, 5, 7, 5, 5};
				case 'B': return new int[]{6, 5, 6, 5, 6};
				case 'C': return new int[]{3, 4, 4, 4, 3};
				case 'D': return new int[]{6, 5, 5, 5, 6};
				case 'E': return new int[]{7, 4, 6, 4, 7};
				case 'F': return new int[]{7, 4, 6, 4, 4};
				case 'G': return new int[]{3, 4, 5, 5, 3};
				case 'H': return new int[]{5, 5, 7, 5, 5};
				case 'I': return new int[]{7, 2, 2, 2, 7};
				case 'J': return new int[]{1, 1, 1, 5, 2};
				case 'K': return new int[]{5, 6, 4, 6, 5};
				case 'L': return new int[]{4, 4, 4, 4, 7};
				case 'M': return new int[]{5, 7, 7, 5, 5};
				case 'N': return new int[]{6, 5, 5, 5, 5};
				case 'O': return new int[]{2, 5, 5, 5, 2};
				case 'P': return new int[]{7, 5, 7, 4, 4};
				case 'Q': return new int[]{2, 5, 5, 7, 3};
				case 'R': return new int[]{6, 5, 6, 6, 5};
				case 'S': return new int[]{3, 4, 2, 1, 6}; // not the 5 glyph
				case 'T': return new int[]{7, 2, 2, 2, 2};
				case 'U': return new int[]{5, 5, 5, 5, 7};
				case 'V': return new int[]{5, 5, 5, 5, 2};
				case 'W': return new int[]{5, 5, 7, 7, 5};
				case 'X': return new int[]{5, 5, 2, 5, 5};
				case 'Y': return new int[]{5, 5, 2, 2, 2};
				case 'Z': return new int[]{7, 1, 2, 4, 7};
				default:  return new int[]{0, 0, 0, 0, 0};
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (!config.callFollowerInteract())
		{
			return;
		}
		String opt = e.getMenuOption();
		if (opt == null)
		{
			return;
		}
		String o = opt.toLowerCase();
		if (o.contains("call") && o.contains("follower"))
		{
			// Show the real pet so it's right-clickable, and don't re-ghost it
			// for a few seconds so you can interact.
			handBackNow();
			suppressTakeoverTicks = 8;
			log.debug("Call Follower: handed back for interaction");
		}
	}

	/** Immediately reveal the real pet (end any ghosting/impersonation). */
	private void handBackNow()
	{
		if (impersonating)
		{
			endThrall();
		}
		releasePet();
		hidingReal = false;
		docking = false;
		despawnGhost();
	}

	/**
	 * Persist the true pose-animation table captured from a real pet, keyed
	 * by both NPC id and (sanitized) name so every id variant of the same
	 * pet benefits. Transmogs prefer this over the imported table.
	 */
	private void learnPetAnims()
	{
		if (pet == null || origWalk <= 0)
		{
			return;
		}
		String val = origIdle + "," + origWalk + "," + origRun;
		// Runs on every relink (the server re-spawns the pet constantly while
		// you outrun it), so only write when something actually changed.
		if (val.equals(configManager.getConfiguration("petfollower", "anims_" + pet.getId())))
		{
			return;
		}
		configManager.setConfiguration("petfollower", "anims_" + pet.getId(), val);
		NPCComposition comp = pet.getTransformedComposition();
		String name = comp != null ? comp.getName() : null;
		if (name != null && !name.isEmpty())
		{
			configManager.setConfiguration("petfollower", "anims_name_" + sanitizeKey(name), val);
		}
	}

	/** {idle, walk, run} learned from a real sighting of this pet, or null. */
	private int[] learnedAnims(int npcId, String name)
	{
		String v = configManager.getConfiguration("petfollower", "anims_" + npcId);
		if (v == null && name != null && !name.isEmpty())
		{
			v = configManager.getConfiguration("petfollower", "anims_name_" + sanitizeKey(name));
		}
		if (v == null)
		{
			return null;
		}
		try
		{
			String[] p = v.split(",");
			return new int[]{Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2])};
		}
		catch (Exception ex)
		{
			return null;
		}
	}

	private static String sanitizeKey(String s)
	{
		return s.toLowerCase().replaceAll("[^a-z0-9]", "_");
	}

	private int poseFor(int state)
	{
		switch (state)
		{
			case POSE_WALK:
				return poseWalk;
			case POSE_RUN:
				return poseRun != -1 ? poseRun : poseWalk;
			default:
				return poseIdle;
		}
	}

	/**
	 * Position the ghost at ghostArc along the recorded polyline, dropping
	 * path points it has already passed, and steer it along the segment.
	 */
	private void moveGhostToArc(float dt)
	{
		// Drop points the ghost has fully passed, always keeping the point
		// just behind it so the bracket [a, b] straddles ghostArc.
		while (true)
		{
			PathPoint second = secondOf(path);
			if (second == null || second.cum > ghostArc)
			{
				break;
			}
			path.pollFirst();
		}

		PathPoint a = path.peekFirst();
		PathPoint b = secondOf(path);
		if (a == null)
		{
			return;
		}

		float nx;
		float ny;
		float dirX = 0f;
		float dirY = 0f;
		if (b == null || b.cum <= a.cum)
		{
			nx = a.x;
			ny = a.y;
		}
		else
		{
			float f = (ghostArc - a.cum) / (b.cum - a.cum);
			f = Math.max(0f, Math.min(1f, f));
			nx = a.x + (b.x - a.x) * f;
			ny = a.y + (b.y - a.y) * f;
			dirX = b.x - a.x;
			dirY = b.y - a.y;
		}

		// Pure pursuit: aim at a point LOOKAHEAD units further along the
		// path rather than this tiny segment, turning corners into arcs.
		float lx = nx;
		float ly = ny;
		{
			float lookArc = ghostArc + LOOKAHEAD;
			PathPoint prev = a;
			boolean found = false;
			for (PathPoint pp : path)
			{
				if (pp.cum >= lookArc)
				{
					float span = pp.cum - prev.cum;
					float f2 = span <= 0f ? 1f : (lookArc - prev.cum) / span;
					lx = prev.x + (pp.x - prev.x) * f2;
					ly = prev.y + (pp.y - prev.y) * f2;
					found = true;
					break;
				}
				prev = pp;
			}
			if (!found)
			{
				// Path doesn't extend that far (slowing to a stop): aim at
				// its end.
				lx = prev.x;
				ly = prev.y;
			}
		}

		float ldx = lx - nx;
		float ldy = ly - ny;
		if (Math.hypot(ldx, ldy) > 4)
		{
			int desired = jau(ldx, ldy);

			if (config.alwaysFaceOwner() && pathSmoothInit)
			{
				// Full owner-lock: the body points at you even mid-stride.
				// Aimed at the SMOOTHED position so sidesteps can't twitch it.
				desired = jau(pathSmoothX - nx, pathSmoothY - ny);
			}
			else if (pathSmoothInit)
			{
				// Lean the facing a little toward the player so the pet reads
				// as watching you through the turn (capped: never strafes).
				// Aim the lean at the SMOOTHED player position: leaning at the
				// raw position twitched the whole body the instant you sidestep,
				// which read as the pet reacting inhumanly fast.
				int toPlayer = jau(pathSmoothX - nx, pathSmoothY - ny);
				int bias = (int) (wrapAngle(toPlayer - desired) * PLAYER_BIAS);
				bias = Math.max(-PLAYER_BIAS_CAP, Math.min(PLAYER_BIAS_CAP, bias));
				desired = (desired + bias) & 2047;
			}
			desiredHeading = desired;

			int diff = wrapAngle(desired - ghost.getOrientation());
			if (Math.abs(diff) > TURN_DEADBAND)
			{
				steer(desired, dt);
			}
			else
			{
				turnV *= 0.6f;
			}
		}

		ghostX = nx;
		ghostY = ny;
		place(new LocalPoint(Math.round(nx), Math.round(ny)), pathPlane);
	}

	/**
	 * A scene reload shifted the local coordinate origin. Translate ALL of
	 * the ghost's local-space state into the new frame so it glides through
	 * loading lines mid-stride — speed, route, facing, and rest state all
	 * untouched. A big world jump at the same moment is a real teleport
	 * instead: clean repark (gliding across the world map would be worse),
	 * resuming at speed rather than with the standing-start beat.
	 */
	private void applySceneShift()
	{
		if (ghost == null)
		{
			pendingShiftFrom = null;
			return;
		}
		Player me = client.getLocalPlayer();
		WorldPoint now = me != null ? me.getWorldLocation() : null;
		// Crossing an instance boundary (into or out of a raid, or between
		// rooms that rebuild the instance) makes world coordinates
		// incomparable: they describe different template layouts, so the
		// distance below is meaningless and the base-delta translation would
		// strand the ghost. Repark instead — the pet reappears behind you.
		boolean instanced = client.isInInstancedRegion();
		boolean instanceChanged = instanced != wasInstanced;
		wasInstanced = instanced;
		// Compare against the position captured when loading STARTED (see
		// pendingShiftFrom). Different planes yield MAX_VALUE, so ladders
		// and stairs that reload the scene classify as teleports and repark.
		int jump = now != null && pendingShiftFrom != null
			? pendingShiftFrom.distanceTo(now)
			: Integer.MAX_VALUE;
		pendingShiftFrom = null;
		if (instanceChanged || jump > 10)
		{
			reparkAfterTeleport();
			return;
		}

		float dx = -(client.getBaseX() - lastBaseX) * (float) Perspective.LOCAL_TILE_SIZE;
		float dy = -(client.getBaseY() - lastBaseY) * (float) Perspective.LOCAL_TILE_SIZE;
		if (dx != 0f || dy != 0f)
		{
			ghostX += dx;
			ghostY += dy;
			pathSmoothX += dx;
			pathSmoothY += dy;
			restX += dx;
			restY += dy;
			Deque<PathPoint> shifted = new ArrayDeque<>(path.size());
			for (PathPoint pp : path)
			{
				shifted.addLast(new PathPoint(pp.x + dx, pp.y + dy, pp.cum));
			}
			path.clear();
			path.addAll(shifted);
		}

		// Belt and braces: if the translation left the ghost far from you
		// (or off the scene grid entirely), the load was NOT a simple
		// walk-crossing — whatever the classifier thought. Repark rather
		// than strand an invisible ghost that later slingshots in.
		LocalPoint mp = me != null ? me.getLocalLocation() : null;
		if (mp == null
			|| Math.hypot(mp.getX() - ghostX, mp.getY() - ghostY) > 15 * Perspective.LOCAL_TILE_SIZE)
		{
			reparkAfterTeleport();
			return;
		}

		// Registration can be scene-scoped: cycle it, then reseat on the
		// new scene's terrain.
		if (ghostShown)
		{
			client.removeRuneLiteObject(ghost);
			client.registerRuneLiteObject(ghost);
		}
		pathPlane = client.getPlane();
		place(new LocalPoint(Math.round(ghostX), Math.round(ghostY)), pathPlane);
		if (blipActive)
		{
			syncBlip();
		}
	}

	/**
	 * A real teleport (or anything that looks like one): tear the follow
	 * state down cleanly; the next takeover reparks the ghost behind you,
	 * setting off at speed instead of the standing-start beat.
	 */
	private void reparkAfterTeleport()
	{
		resumeAtSpeed = hidingReal;
		releasePet();
		despawnGhost();
		hidingReal = false;
		// Relearn the pet's on-screen height after the jump: a stale peak here
		// is what floated the readout absurdly high after a teleport.
		if (petVitalsOverlay != null)
		{
			petVitalsOverlay.stableLogH = 0f;
		}
		// You disengaged by leaving: clear the combat linger, or the pet
		// spends its first seconds back in wander mode instead of following.
		lastCombatMs = 0;
		combatTarget = null;
		combatPrev = false;
	}

	/**
	 * Restart the path after a teleport/plane change: park the ghost right
	 * behind your rendered position, facing the same way you do.
	 */
	private void resetPathBehind(LocalPoint p, int plane)
	{
		Player me = client.getLocalPlayer();
		int facing = me != null ? me.getCurrentOrientation() : 0;
		// Park one tile behind the direction you're facing, with the path
		// seeded [ghost, you] so the arc bookkeeping stays consistent.
		double rad = facing * Math.PI / 1024.0;
		float bx = p.getX() + (float) (Math.sin(rad) * gap);
		float by = p.getY() + (float) (Math.cos(rad) * gap);
		// ...but that spot is wherever you happen to be facing, which after a
		// teleport / login / staircase is very often a wall, a rock, or the
		// inside of a building. Sweep outward from it for the first open tile
		// and fall back to your own, which is walkable by definition.
		if (!openAt(bx, by))
		{
			boolean found = false;
			for (int step = 1; step <= 3 && !found; step++)
			{
				for (int sign = -1; sign <= 1 && !found; sign += 2)
				{
					double a = rad + sign * step * (Math.PI / 4.0);
					float cx = p.getX() + (float) (Math.sin(a) * gap);
					float cy = p.getY() + (float) (Math.cos(a) * gap);
					if (openAt(cx, cy))
					{
						bx = cx;
						by = cy;
						found = true;
					}
				}
			}
			if (!found)
			{
				bx = p.getX();
				by = p.getY();
			}
		}
		ghostX = bx;
		ghostY = by;

		path.clear();
		pathPlane = plane;
		path.addLast(new PathPoint(ghostX, ghostY, 0f));
		path.addLast(new PathPoint(p.getX(), p.getY(), gap));
		playerCum = gap;
		playerSpeed = 0f;
		ghostArc = 0f;
		ghostV = 0f;
		pathSmoothInit = false;

		if (ghost != null)
		{
			ghost.setOrientation(facing);
			place(new LocalPoint(Math.round(ghostX), Math.round(ghostY)), plane);
		}
		turnV = 0f;
		desiredHeading = facing;
		applyPose(POSE_IDLE);
	}

	private static PathPoint secondOf(Deque<PathPoint> deque)
	{
		java.util.Iterator<PathPoint> it = deque.iterator();
		if (!it.hasNext())
		{
			return null;
		}
		it.next();
		return it.hasNext() ? it.next() : null;
	}

	// ------------------------------------------------------------------
	// Ghost lifecycle
	// ------------------------------------------------------------------

	/**
	 * Renders exactly what the hidden pet NPC renders this frame:
	 * NPC.getModel() is already posed, scaled, and recolored by the engine,
	 * so the ghost is pixel-identical to the real pet — only its position and
	 * facing are ours. When the real pet isn't being drawn (reload gap) the
	 * ghost is despawned rather than drawing this (recycled) buffer.
	 */
	private final class Ghost extends RuneLiteObjectController
	{
		private Model lastModel;

		Ghost(Model initial)
		{
			lastModel = initial;
		}

		@Override
		public Model getModel()
		{
			NPC p = pet;
			if (p != null)
			{
				Model m = p.getModel();
				if (m != null)
				{
					// The normal NPC draw path computes bounds before face
					// sorting; doing it here keeps the triangle sort stable
					// (otherwise a blur-like shimmer).
					m.calculateBoundsCylinder();
					setRadius(m.getRadius());
					lastModel = m;
					return m;
				}
			}
			if (fallbackModel != null)
			{
				// The real NPC is momentarily gone (teleport-respawn blip):
				// draw our own cache-built copy — never the recycled live
				// buffer, which flashes other actors' geometry.
				setRadius(fallbackModel.getRadius());
				return fallbackModel;
			}
			return lastModel;
		}
	}

	/**
	 * Build our own copy of the pet's model from the game cache: the pet's
	 * definition lists its model parts, recolors, and exact resize values
	 * (128 = 1.0x), so the copy matches the real pet without guessing at
	 * scale. Drawn only while the real NPC is momentarily absent.
	 */
	private void buildFallbackModel()
	{
		int wantId = previewing ? activePreviewId : (pet != null ? pet.getId() : -1);
		if (wantId == -1 || (fallbackForId == wantId && fallbackModel != null))
		{
			return;
		}
		fallbackModel = null;
		fallbackForId = wantId;

		NPCComposition comp = previewing
			? client.getNpcDefinition(activePreviewId)
			: pet.getTransformedComposition();
		if (comp == null)
		{
			return;
		}
		int[] ids = comp.getModels();
		if (ids == null || ids.length == 0)
		{
			return;
		}
		ModelData[] parts = new ModelData[ids.length];
		for (int i = 0; i < ids.length; i++)
		{
			parts[i] = client.loadModelData(ids[i]);
			if (parts[i] == null)
			{
				return;
			}
		}
		// ALWAYS merge, even a single part: mergeModels emits a fresh,
		// animation-ready copy (labels intact) that's safe to mutate. Never
		// touch the shared cache entries directly, and never reassign
		// through the clone chain — a chained clone loses the animation
		// skeleton mapping, and animating it shreds the vertices (the
		// black exploded-geometry glitch). This mirrors exactly how the
		// battle-tested Companion Pets plugin builds its models.
		ModelData md = client.mergeModels(parts);
		if (md == null)
		{
			return;
		}

		short[] find = comp.getColorToReplace();
		short[] repl = comp.getColorToReplaceWith();
		if (find != null && repl != null)
		{
			int n = Math.min(find.length, repl.length);
			for (int i = 0; i < n; i++)
			{
				md.recolor(find[i], repl[i]);
			}
		}

		// NO pre-scaling: animating a pre-scaled model distorts resize pets
		// (animation offsets are authored for the full-size skeleton). The
		// def's resize is applied per-frame to the ANIMATED output instead,
		// in the blip object's getModel() override.
		fbWidthScale = comp.getWidthScale();
		fbHeightScale = comp.getHeightScale();

		// NPC-style lighting (64 ambient / 850 contrast, standard light
		// vector) as the baseline...
		Model m = md.light(64, 850, -30, -50, -30);
		if (m == null)
		{
			return;
		}

		// ...then copy the EXACT per-face colors from the live engine-lit
		// model. Every NPC has its own ambient/contrast in its definition
		// (not exposed through the API), so any fixed lighting numbers are
		// wrong for someone — but the engine already lit the real pet
		// perfectly, and our stand-in is built from the same parts in the
		// same order, so the face arrays line up one-to-one. Works for
		// every pet with zero per-pet tuning. (Not possible for previews —
		// there's no live model of a pet you don't own — so previews use
		// the baseline lighting, which can read slightly flat.)
		if (!previewing && pet != null)
		{
			Model live = pet.getModel();
			if (live != null)
			{
				copyFaceColors(live.getFaceColors1(), m.getFaceColors1());
				copyFaceColors(live.getFaceColors2(), m.getFaceColors2());
				copyFaceColors(live.getFaceColors3(), m.getFaceColors3());
			}
		}

		m.calculateBoundsCylinder();
		fallbackModel = m;
	}

	private static void copyFaceColors(int[] src, int[] dst)
	{
		if (src != null && dst != null && src.length == dst.length)
		{
			System.arraycopy(src, 0, dst, 0, dst.length);
		}
	}

	private void spawnGhost(Player me)
	{
		despawnGhost();
		if (pet == null)
		{
			return;
		}

		Model m = pet.getModel();
		LocalPoint petPos = pet.getLocalLocation();
		LocalPoint playerPos = me.getLocalLocation();
		if (m == null || petPos == null || playerPos == null)
		{
			hidingReal = false;
			return; // not renderable yet; retry next takeover
		}

		int plane = client.getPlane();
		path.clear();
		pathPlane = plane;
		// Seed the path with the leg from the pet's current spot to you, so
		// the ghost visibly runs up from where the real pet stood.
		float d = (float) Math.hypot(playerPos.getX() - petPos.getX(), playerPos.getY() - petPos.getY());
		path.addLast(new PathPoint(petPos.getX(), petPos.getY(), 0f));
		if (d > 1f)
		{
			path.addLast(new PathPoint(playerPos.getX(), playerPos.getY(), d));
		}
		playerCum = d;
		playerSpeed = 0f;
		ghostArc = 0f;
		ghostV = 0f;
		if (resumeAtSpeed)
		{
			// Interrupted mid-run: appear already walking. A nonzero speed
			// bypasses the standing-start reaction gate, and the normal
			// speed curve takes over from the very next frame (it also
			// eases straight back to a stop if you actually stood still).
			ghostV = WALK_SPEED;
			resumeAtSpeed = false;
		}
		turnV = 0f;
		lastFrameNanos = System.nanoTime();
		ghostX = petPos.getX();
		ghostY = petPos.getY();

		ensureHijack();
		poseState = -1;
		buildFallbackModel();
		NPCComposition comp = previewing
			? client.getNpcDefinition(activePreviewId)
			: pet.getTransformedComposition();
		ghostSize = comp != null ? comp.getSize() : 1;
		// Bigger/longer pets sit further back at rest so they don't clip into
		// the player when idle (Scorpia's offspring, Callisto cub, etc.).
		gap = GAP + (ghostSize - 1) * 96f + IDLE_PUSHBACK;

		ghost = new Ghost(m);
		// Size it up front: the RuneLiteObject's default radius before the
		// first getModel() call could leave it unculled/misdrawn for a frame.
		m.calculateBoundsCylinder();
		ghost.setRadius(m.getRadius());

		// If we're (re)spawning while impersonating a thrall — e.g. after a
		// teleport — appear directly on the thrall already "attached", so it
		// doesn't jog/rubberband across to it on reappear.
		LocalPoint thrallPos = thrall != null ? thrall.getLocalLocation() : null;
		if (thrallPos != null)
		{
			ghostX = thrallPos.getX();
			ghostY = thrallPos.getY();
			prevThrallX = thrallPos.getX();
			prevThrallY = thrallPos.getY();
			thrallAttached = true;
			place(thrallPos, plane);
			ghost.setOrientation(thrall.getCurrentOrientation());
			client.registerRuneLiteObject(ghost);
			ghostShown = true;
			return;
		}

		// The real pet pops in at your server-side tile, which can be ahead
		// of your rendered character or far behind it. Spawning the ghost
		// there looks wrong (falls back from in front / sprints up from way
		// back). If the pet materialized in front of you or far away, appear
		// directly at the proper follow position behind you — like vanilla
		// pets teleporting in. Only a close, behind-you pet (the normal
		// standing-start takeover) is used as the spawn point for the
		// seamless swap.
		double rad = me.getCurrentOrientation() * Math.PI / 1024.0;
		float fx = -(float) Math.sin(rad);
		float fy = -(float) Math.cos(rad);
		float relX = petPos.getX() - playerPos.getX();
		float relY = petPos.getY() - playerPos.getY();
		float ahead = relX * fx + relY * fy;
		boolean moving = idleTicks == 0;

		// Landing on your own tile is the teleport case: the server drops the
		// pet right on top of you, and spawning the ghost there buries it
		// INSIDE your character. Park it behind you instead.
		boolean onTopOfMe = d < 0.75f * Perspective.LOCAL_TILE_SIZE;

		// Position and orient BEFORE registering. Registering first left the
		// object at the scene origin (right by the camera) for the opening
		// frame — that's the "giant pet" flash on the first spawn after login.
		if (onTopOfMe || d > 2.5f * Perspective.LOCAL_TILE_SIZE || (moving && ahead > 48f))
		{
			resetPathBehind(playerPos, plane);
			client.registerRuneLiteObject(ghost);
			ghostShown = true;
			return;
		}

		place(petPos, plane);
		ghost.setOrientation(pet.getOrientation());
		client.registerRuneLiteObject(ghost);
		ghostShown = true;
		desiredHeading = pet.getOrientation();
	}

	/** Activate/deactivate the animated blip stand-in. */
	private void showBlip(boolean show)
	{
		if (show)
		{
			if (blipObj == null)
			{
				// Companion Pets' proven pattern: apply the def's resize to
				// the ANIMATED output each frame (never to the model data),
				// so resize pets animate cleanly at the right size.
				blipObj = new RuneLiteObject(client)
				{
					@Override
					public Model getModel()
					{
						Model m = super.getModel();
						if (m != null && (fbWidthScale != 128 || fbHeightScale != 128))
						{
							m = m.scale(fbWidthScale, fbHeightScale, fbWidthScale);
						}
						return m;
					}
				};
				blipObj.setShouldLoop(true);
			}
			if (!blipActive)
			{
				blipObj.setModel(fallbackModel);
				blipModelApplied = fallbackModel;
				blipActive = true;
				// Note: blipAnimId is NOT reset — rapid blip on/off chains
				// (outrunning the pet) keep the same animation running
				// instead of restarting it each time.
				updateBlipAnim();
				syncBlipPhase();
				syncBlip();
				blipObj.setActive(true);
			}
			else if (blipModelApplied != fallbackModel && fallbackModel != null)
			{
				// The cache model was rebuilt while the stand-in was live
				// (transmog switch): push the new model AND its own anims.
				// Leaving the old model up while the new pet's animation
				// played on it warped it into a morphed hybrid.
				blipObj.setModel(fallbackModel);
				blipModelApplied = fallbackModel;
				blipAnimId = -1;
				updateBlipAnim();
			}
		}
		else if (blipActive)
		{
			blipObj.setActive(false);
			blipActive = false;
		}
	}

	/** Hand the mirror's current animation phase to the stand-in. */
	private void syncBlipPhase()
	{
		AnimationController ac = blipObj != null ? blipObj.getAnimationController() : null;
		Animation anim = ac != null ? ac.getAnimation() : null;
		if (anim != null && lastPoseFrame > 0 && lastPoseFrame < anim.getNumFrames())
		{
			ac.setFrame(lastPoseFrame);
		}
	}

	/** Keep the stand-in on the ghost's position, height, and facing. */
	private void syncBlip()
	{
		if (!blipActive || blipObj == null || ghost == null)
		{
			return;
		}
		LocalPoint at = new LocalPoint(Math.round(ghostX), Math.round(ghostY));
		blipObj.setLocation(at, pathPlane);
		blipObj.setZ(Perspective.getFootprintTileHeight(client, at, pathPlane, ghostSize)
			- config.groundClearance());
		blipObj.setOrientation(ghost.getOrientation());

		// Speed-up for the stand-in: feed extra time into the controller's
		// OWN clock so it advances through its native duration logic —
		// smooth, even pacing. Frame-index pushes (setFrame) desynced its
		// internal timing and produced the transmog-only hitching.
		long nnBlip = System.nanoTime();
		float bdt = blipClockNanos == 0 ? 0f : Math.min(100f, (nnBlip - blipClockNanos) / 1_000_000f);
		blipClockNanos = nnBlip;
		float factor = cadenceFactor();
		if (cadenceEligible(factor))
		{
			AnimationController ac = blipObj.getAnimationController();
			if (ac != null)
			{
				blipExtraMs += (factor - 1f) * bdt;
				int extraTicks = (int) (blipExtraMs / 20f);
				if (extraTicks > 0)
				{
					blipExtraMs -= extraTicks * 20f;
					ac.tick(extraTicks);
				}
			}
		}
		else
		{
			blipExtraMs = 0f;
		}
	}

	/** Play the pose animation matching the ghost's current motion. */
	private void updateBlipAnim()
	{
		if (!blipActive || blipObj == null)
		{
			return;
		}
		// An attack is playing on the stand-in (preview mode): let it finish
		// before the pose animation takes the channel back.
		if (System.currentTimeMillis() < blipAttackUntil)
		{
			return;
		}
		// Follow the SAME smoothed + dwell-debounced pose state machine as
		// the mirror. Computing a state here from raw ghostV re-created the
		// exact threshold-flapping bug the mirror was cured of: every flap
		// called setAnimation (= restart at frame 0), so TRANSMOGS
		// stutter-looped while real pets looked perfect — the stand-in is
		// all you see in preview.
		if (poseState == -1)
		{
			return;
		}
		int id = poseFor(poseState);
		if (id != -1 && id != blipAnimId)
		{
			blipAnimId = id;
			blipObj.setAnimation(client.loadAnimation(id));
			// Pick the cycle up where the mirrored pet left off — every
			// blip restarting the stride at frame 0 was the visible
			// "feet reset" while outrunning the pet.
			syncBlipPhase();
		}
	}

	/** Register/unregister the ghost so it stops drawing without losing state. */
	private void showGhost(boolean show)
	{
		if (ghost == null || show == ghostShown)
		{
			return;
		}
		if (show)
		{
			client.registerRuneLiteObject(ghost);
		}
		else
		{
			client.removeRuneLiteObject(ghost);
		}
		ghostShown = show;
	}

	private void despawnGhost()
	{
		showBlip(false);
		if (ghost != null)
		{
			client.removeRuneLiteObject(ghost);
			ghost = null;
		}
		ghostShown = false;
		path.clear();
		playerCum = 0f;
		playerSpeed = 0f;
		ghostArc = 0f;
		ghostV = 0f;
		turnV = 0f;
		// Don't carry a stale lean into the next spawn.
		npcPushX = 0f;
		npcPushY = 0f;
		poseState = -1;
		docking = false;
		settling = false;
		restDone = false;
		combatWandering = false;
		combatReturning = false;
		pathSmoothInit = false;
	}

	/**
	 * Drift a PARKED ghost clear of NPC models it would otherwise be drawn
	 * inside. Draw order can't solve this (the GPU renderer depth-tests per
	 * pixel, so overlapping models genuinely interpenetrate); the only fix is
	 * not to overlap. It is a RENDER-space offset: the simulation, path and
	 * collision all run on the true position. The lean points straight away
	 * from the offender (fixed in world space, so it can't feed back into
	 * the pet's facing), eases in, and is rate-limited so it reads as a step
	 * aside rather than a shove. A travelling pet just walks its route.
	 */
	private void updateNpcPush(float dt)
	{
		float tx = 0f;
		float ty = 0f;
		// The lean is for a PARKED pet only. Running it while the pet is
		// pathing meant a constantly-shifting offset: the pet drifted about
		// far more than it should, and following that swinging heading is what
		// span it when a mob sat on its tile. While it is travelling, the pet
		// simply walks its route (and clips, which is the lesser evil).
		boolean parked = ghostV <= 0.01f && !settling && !docking && !combatReturning;
		if (config.avoidNpcs() && !impersonating && ghost != null && parked)
		{
			double rad = ghost.getOrientation() * Math.PI / 1024.0;
			float fx = -(float) Math.sin(rad);
			float fy = -(float) Math.cos(rad);
			float bestNeed = 0f;
			float bestAwayX = 0f;
			float bestAwayY = 0f;
			for (NPC n : client.getNpcs())
			{
				if (n == null || n == pet || n == thrall)
				{
					continue;
				}
				LocalPoint np = n.getLocalLocation();
				if (np == null)
				{
					continue;
				}
				float sx = np.getX() - ghostX;
				float sy = np.getY() - ghostY;
				// Cheap distance cull BEFORE the composition lookup: an NPC well
				// past our reach (lookahead + the biggest plausible footprint)
				// can't affect the lean, so skip it without the per-NPC
				// getTransformedComposition() call — the cost that mattered in a
				// crowd (GE, Wintertodt, raids).
				if (sx * sx + sy * sy > NPC_CULL_SQ)
				{
					continue;
				}
				NPCComposition c = n.getTransformedComposition();
				if (c != null && c.isFollower())
				{
					continue; // other people's pets aren't worth stepping around
				}
				// Only mobs that MATTER: the one you're fighting, or anything
				// nearby while you're actually in combat. Leaning away from
				// every idle NPC in the world kept the pet shuffling constantly
				// for no reason the player could see.
				Actor ctgt = combatTarget != null ? combatTarget.get() : null;
				if (n != ctgt && !inCombat())
				{
					continue;
				}
				float d = (float) Math.hypot(sx, sy);
				float minD = ((c != null ? c.getSize() : 1) * 0.5f + 0.45f)
					* Perspective.LOCAL_TILE_SIZE;
				if (d >= minD)
				{
					continue;
				}
				float need = minD - d;
				if (need > bestNeed)
				{
					bestNeed = need;
					// Straight AWAY from whatever is crowding us. The old
					// direction was a PERPENDICULAR to the pet's own facing,
					// which meant the lean rotated every time the pet turned -
					// and the pet turned to follow the lean. Away is fixed in
					// world space, so it cannot chase its own tail. (Parked
					// pets only, so there is no pass-by for it to swing on.)
					float sl = (float) Math.hypot(sx, sy);
					if (sl > 1f)
					{
						bestAwayX = -sx / sl;
						bestAwayY = -sy / sl;
					}
					else
					{
						bestAwayX = 0f;
						bestAwayY = 0f; // dead centre; resolved below
					}
				}
			}
			if (bestNeed > 0f)
			{
				float ax = bestAwayX;
				float ay = bestAwayY;
				if (ax == 0f && ay == 0f)
				{
					// Standing dead on the pet's tile: there is no meaningful
					// "away", so keep whatever direction is already committed,
					// and only fall back to the facing to break the tie.
					float pl = (float) Math.hypot(npcPushX, npcPushY);
					if (pl > 0.01f)
					{
						ax = npcPushX / pl;
						ay = npcPushY / pl;
					}
					else
					{
						ax = -fy;
						ay = fx;
					}
				}
				float lean = Math.min(bestNeed, NPC_MAX_LEAN);
				// There isn't always anywhere to go: a one-tile corridor with
				// a mob in it, or a room packed with them. Stepping into the
				// wall would look far worse than clipping the mob, so the
				// lean is only taken if the pet could actually STAND there.
				// Straight away first, then either way around it, then give
				// up and accept the overlap.
				float[][] dirs = {{ax, ay}, {-ay, ax}, {ay, -ax}};
				boolean placed = false;
				for (float[] d : dirs)
				{
					for (float frac = 1f; frac >= 0.33f; frac -= 0.335f)
					{
						float cx = d[0] * lean * frac;
						float cy = d[1] * lean * frac;
						if (footprintWalkable(ghostX + cx, ghostY + cy))
						{
							tx = cx;
							ty = cy;
							placed = true;
							break;
						}
					}
					if (placed)
					{
						break;
					}
				}
			}
		}
		// Frame-rate independent ease...
		float k = 1f - (float) Math.exp(-dt / NPC_EASE_TAU);
		float nx = npcPushX + (tx - npcPushX) * k;
		float ny = npcPushY + (ty - npcPushY) * k;
		// ...with a hard ceiling on how fast it may travel, so a target
		// that appears all at once still gets approached at walking pace.
		float mvx = nx - npcPushX;
		float mvy = ny - npcPushY;
		float mv = (float) Math.hypot(mvx, mvy);
		float maxStep = NPC_MAX_RATE * dt;
		if (mv > maxStep)
		{
			nx = npcPushX + mvx / mv * maxStep;
			ny = npcPushY + mvy / mv * maxStep;
		}
		// Settle exactly on zero once the lean has let go, so a parked pet
		// isn't re-placed every frame chasing a vanishing offset.
		if (tx == 0f && ty == 0f && Math.abs(nx) < 0.5f && Math.abs(ny) < 0.5f)
		{
			nx = 0f;
			ny = 0f;
		}
		npcPushX = nx;
		npcPushY = ny;
	}

	private void place(LocalPoint at, int plane)
	{
		appliedPushX = Math.round(npcPushX);
		appliedPushY = Math.round(npcPushY);
		if (npcPushX != 0f || npcPushY != 0f)
		{
			at = new LocalPoint(Math.round(at.getX() + npcPushX),
				Math.round(at.getY() + npcPushY));
		}
		ghost.setLocation(at, plane);
		// Seat the ghost on the terrain the same way the engine seats the
		// real NPC: footprint-averaged height, so wide flat pets (Scorpia's
		// offspring etc.) don't sink into slopes. Uses the size captured at
		// spawn so it stays correct even while the pet is a render blip.
		// Negative Z is up; the clearance lifts base-level glows/auras just
		// above the terrain plane so the ground can't swallow them.
		int z = Perspective.getFootprintTileHeight(client, at, plane, ghostSize)
			- config.groundClearance();
		ghost.setZ(z);
		if (blipActive && blipObj != null)
		{
			blipObj.setLocation(at, plane);
			blipObj.setZ(z);
			blipObj.setOrientation(ghost.getOrientation());
			updateBlipAnim();
		}
	}

	/**
	 * Make the ghost's mirrored model play exactly one animation at native
	 * speed: rewrite the hidden pet's pose-animation TABLE (idle/walk/run
	 * all point at the id the ghost needs). The engine re-decides the pose
	 * whenever the real pet moves, but every choice lands on the same id, so
	 * the cycle is never reset — overriding pose/frame after the fact
	 * (previous approach) restarted or fast-forwarded the animation, which
	 * showed as sped-up, jittery playback.
	 */
	private void applyPose(int state)
	{
		applyPose(state, 0);
	}

	private void applyPose(int state, int frame)
	{
		if (pet == null || state == poseState)
		{
			return;
		}
		int id = poseFor(state);
		if (id == -1)
		{
			return;
		}
		poseState = state;
		pet.setIdlePoseAnimation(id);
		pet.setWalkAnimation(id);
		pet.setRunAnimation(id);
		// Only restart the cycle when the ANIMATION actually changes. A
		// state change that resolves to the same id (many pets share one
		// walk/run animation — the beaver's walk and run are both 10010)
		// must never touch the frame: resetting it on every borderline
		// walk<->run flip was the visible quarter-second animation-restart
		// rhythm while running.
		if (pet.getPoseAnimation() != id)
		{
			pet.setPoseAnimation(id);
			pet.setPoseAnimationFrame(frame);
		}
	}

	/**
	 * Adopt a fresh pet NPC instance (server teleport-respawn or scene
	 * reload) without any visible animation restart: re-capture its factory
	 * anim table, resume the pose MID-CYCLE (taking the phase from the blip
	 * stand-in if it was carrying it), and cancel the spawn/materialize
	 * action animation so it never plays on the mirror. Used by BOTH
	 * re-link paths — having the game-tick path skip these steps was the
	 * "run animation repeats while outrunning the pet" bug.
	 */
	private void relinkPet(NPC found)
	{
		int prevState = poseState;
		animsHijacked = false;
		pet = found;
		ensureHijack();
		buildFallbackModel();
		if (prevState != -1)
		{
			if (blipActive && blipObj != null && blipObj.getAnimationController() != null)
			{
				lastPoseFrame = blipObj.getAnimationController().getFrame();
			}
			applyPose(prevState, lastPoseFrame);
		}
		pet.setAnimation(-1);
	}

	/**
	 * Capture the pet's real pose-animation table once, before applyPose
	 * rewires it. Re-runs after a pet instance change (animsHijacked reset).
	 */
	private void ensureHijack()
	{
		if (pet == null || animsHijacked)
		{
			return;
		}
		origIdle = pet.getIdlePoseAnimation();
		origWalk = pet.getWalkAnimation();
		origRun = pet.getRunAnimation();

		// LEARN: these are the pet's TRUE pose anims, straight from the
		// game. Persist them so transmogs of this pet (by anyone's id
		// variant — also keyed by name) use the real thing instead of the
		// imported table, whose rows are sometimes the BOSS's animations
		// (chaos elemental jr's row was the boss's frantic loop — the
		// "animation repeat" look on transmogs).
		learnPetAnims();

		// Pose anims actually USED for rendering: the real pet's, unless the
		// transmog preview is active — then the best data we have for the
		// previewed pet: learned-from-a-real-sighting first, imported table
		// as fallback (origX stay untouched for restore).
		poseIdle = origIdle;
		poseWalk = origWalk;
		poseRun = origRun;
		if (previewing)
		{
			NPCComposition pc = client.getNpcDefinition(activePreviewId);
			String pname = pc != null ? pc.getName() : null;
			int[] learned = learnedAnims(activePreviewId, pname);
			if (learned != null)
			{
				poseIdle = learned[0];
				poseWalk = learned[1];
				poseRun = learned[2];
			}
			else
			{
				PetPoseAnims.Pose pp = PetPoseAnims.forPet(activePreviewId, pname);
				if (pp != null)
				{
					poseIdle = pp.idle;
					poseWalk = pp.walk;
					poseRun = pp.run;
				}
			}
		}

		hijackWalkAnim = poseWalk != -1 ? client.loadAnimation(poseWalk) : null;
		prevMirrorPoseFrame = -1;
		runBoostAcc = 0f;
		blipExtraMs = 0f;
		blipClockNanos = 0;
		animsHijacked = true;
		poseState = -1;
		loadPetSpeed();
	}

	/** Apply the selected follow style, easing the trailing-distance drift. */
	private void updateFollowStyle(float dt)
	{
		float driftAmp;
		switch (config.followStyle())
		{
			case LOOSE:
				// Sets off sooner (~1.2 tiles of slack rather than 1.6) and
				// tracks a little tighter, so it stops looking like it forgot
				// about you. Its lazy trailing distance, late settle and drift
				// are untouched, so the style still reads as loose.
				followStartDist = 150f;
				followSlope = 620f;
				followSmoothTau = 285f;
				followSettleTicks = 5;
				driftAmp = 90f;
				break;
			case MEDIUM:
				followStartDist = 128f;
				followSlope = 500f;
				followSmoothTau = 230f;
				followSettleTicks = 3;
				driftAmp = 45f;
				break;
			default:
				followStartDist = START_DIST;
				followSlope = 350f;
				followSmoothTau = PATH_SMOOTH_TAU;
				followSettleTicks = 2;
				driftAmp = 0f;
				break;
		}

		if (driftAmp <= 0f)
		{
			gapDrift = 0f;
			gapDriftTarget = 0f;
			return;
		}
		// FREEZE the drift the moment you stop. It sets the pet's trailing
		// distance, so letting it keep wandering after you've halted slid the
		// resting spot forward/back a second later — the "stops then nudges
		// forward" bug, worst on the styles with the most drift and when the
		// pet sits directly behind you (drift maps straight to fore/aft there).
		if (idleTicks >= 1)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now >= gapDriftRetargetMs)
		{
			// Only ever ADDS distance (drifting closer than the base gap
			// would nose into the player); eased over ~1.5 s so the change
			// reads as the pet ambling, not snapping.
			gapDriftTarget = followRng.nextFloat() * driftAmp;
			gapDriftRetargetMs = now + 3000 + followRng.nextInt(5000);
		}
		gapDrift += (gapDriftTarget - gapDrift) * Math.min(1f, dt / 1500f);
	}

	/**
	 * Load the displayed pet's remembered settings (cadence, clearance) and
	 * reflect them in the config sliders, so the sliders always show and
	 * edit the pet you actually have out (or are transmogged to).
	 */
	private void loadPetSpeed()
	{
		int id = previewing ? activePreviewId : (pet != null ? pet.getId() : -1);
		if (id < 0)
		{
			return;
		}
		boolean petChanged = id != speedKeyId;
		speedKeyId = id;
		Integer saved = configManager.getConfiguration("petfollower", "petSpeed_" + id, Integer.class);
		// Clamp: values below 100 could be saved by older builds that tried
		// (and failed) to support below-native slowing.
		petSpeedPct = Math.max(100, saved != null ? saved : 100);
		if (config.petSpeed() != petSpeedPct)
		{
			syncingSpeedUi = true;
			configManager.setConfiguration("petfollower", "petSpeed", petSpeedPct);
			syncingSpeedUi = false;
		}
		// Ground clearance is per-pet too — synced silently, no chat line.
		Integer savedClr = configManager.getConfiguration("petfollower", "clearance_" + id, Integer.class);
		int clr = Math.max(0, Math.min(32, savedClr != null ? savedClr : 0));
		if (config.groundClearance() != clr)
		{
			syncingSpeedUi = true;
			configManager.setConfiguration("petfollower", "groundClearance", clr);
			syncingSpeedUi = false;
		}
		// Vitals offset is per-pet AND per-position (a hovering pet wants a
		// higher "Above" than a cat; a wide pet wants a farther "Left").
		syncVitalsOffsetUi(id);
		// Custom pet name is per-pet too.
		String savedName = configManager.getConfiguration("petfollower", "petName_" + id);
		String name = savedName != null ? savedName : "";
		if (!name.equals(config.petName()))
		{
			syncingSpeedUi = true;
			configManager.setConfiguration("petfollower", "petName", name);
			syncingSpeedUi = false;
		}
		// Projectile tint color is per-pet as well (red Hunllef, green Olm
		// jr, ...). A pet with no saved color keeps whatever is set, and
		// only gets its own entry once the user picks a color for it.
		java.awt.Color savedTint = configManager.getConfiguration("petfollower", "boltColor_" + id, java.awt.Color.class);
		if (savedTint != null && !savedTint.equals(config.thrallBoltColor()))
		{
			syncingSpeedUi = true;
			configManager.setConfiguration("petfollower", "thrallBoltColor", savedTint);
			syncingSpeedUi = false;
		}
		// Keep the damage-icon sprite in step with the displayed pet.
		resolvePetIcon(id);
		// Announce the loaded profile in the chatbox whenever the displayed
		// pet changes: an already-OPEN config panel does not repaint when a
		// plugin changes a value under it, so the slider can look stale
		// until reopened — the chat line is the always-visible truth.
		if (petChanged && config.cadenceMessages())
		{
			chat("Pet cadence: " + displayedPetName() + " - " + petSpeedPct + "%"
				+ (saved != null ? " (saved)" : " (default)") + ".");
		}
	}

	/**
	 * Reflect the displayed pet's stored vitals height into the config
	 * slider — the slider always shows and edits the pet on screen.
	 */
	private void syncVitalsOffsetUi(int id)
	{
		Integer saved = configManager.getConfiguration("petfollower",
			"vitalsOff_" + id, Integer.class);
		// Same range as the slider: negative offsets are allowed (below the
		// pet), and clamping at 0 here silently wiped them on every pet load.
		int off = Math.max(-150, Math.min(300, saved != null ? saved : 22));
		if (config.vitalsOffset() != off)
		{
			syncingSpeedUi = true;
			configManager.setConfiguration("petfollower", "vitalsOffset", off);
			syncingSpeedUi = false;
		}
	}

	/** Name of the pet currently displayed (transmog wins over the real pet). */
	private String displayedPetName()
	{
		NPCComposition comp = previewing
			? client.getNpcDefinition(activePreviewId)
			: (pet != null ? pet.getTransformedComposition() : null);
		String name = comp != null ? comp.getName() : null;
		return name != null && !name.isEmpty() ? name : "pet";
	}

