	 * One-off note in the chatbox the first time this build runs: what is
	 * new, and that the combat HUD is experimental. Remembered in the
	 * config, so it shows once and never again.
	 */
	private void showReleaseNoticeOnce()
	{
		if (releaseNoticeChecked)
